E["item:aged-kodo-hide"] = {t="item",n="Aged Kodo Hide",z="desolace",s="Aged Kodo Hide comes from aged kodos in Desolace. Kreldig Ungor needs three hides for Reclaimers Inc., alongside Scorpashi venom.",h="Aged Kodo Hide comes from aged kodos in Desolace.",sec={{t="A Kodo Reagent",b="Kreldig Ungor needs three Aged Kodo Hides in Desolace, as well as seven vials of Scorpashi venom. The hide must come from an aged kodo; dying and ancient kodos do not provide the reagent.",sp=0}},faq={{q="Where do Aged Kodo Hides come from?",a="Aged Kodo Hides come from aged kodos in Desolace.",al={"aged kodo hide source","where hide","kodo hide"}},{q="Who needs Aged Kodo Hide?",a="Kreldig Ungor needs three Aged Kodo Hides for Reagents for Reclaimers Inc.",al={"who wants the hide","kreldig's reagents","reclaimers inc hide"}},{q="Will any kodo provide the hide?",a="No. The hide must come from an aged kodo, not a dying or ancient kodo.",al={"which kodo","dying kodo hide","ancient kodo hide"}},{q="What else does Kreldig need?",a="Kreldig also needs seven vials of Scorpashi Venom.",al={"other reagents","scorpashi venom","what else for kreldig"}}},ang={["class:Mage"]="As a mage, you may recognize Aged Kodo Hide as one of the reagents on Leftwitch's list for Reclaimers Inc."},kw={"aged kodo","aged kodo hide","desolace","kodo graveyard","kreldig ungor","leftwitch","reclaimers inc","scorpashi venom"},rel={"quest:1458","item:scorpashi-venom","npc:kreldig-ungor","zone:desolace","subzone:kodo-graveyard"},src={"Wowpedia: Aged Kodo Hide","Reagents for Reclaimers Inc. (2)"}}
E["item:book-of-the-ancients"] = {t="item",n="Book of the Ancients",z="desolace",s="The Book of the Ancients holds secrets about the naga, kept for centuries. Azore Aldamort seeks it at Ethel Rethor to learn more about these scaled foes.",h="The Book of the Ancients holds secrets about the naga, kept for centuries.",sec={{t="A Serpent's Charge",b="On Ranazjar Isle in Desolace, the Book of the Ancients lies under the guard of a naga protector. Azore Aldamort gives you the Gem of the Serpent and asks you to place it in the hand of the Serpent Statue. The book holds knowledge of the naga that has been kept for centuries, and Azore means to study it.",sp=0},{t="To the High Council",b="When you bring the book back to Azore at the tower in Ethel Rethor, he promises to pass it to the Argent Dawn's high council. He hopes its old secrets will teach them much about their scaled foes.",sp=0}},faq={{q="What is in the Book of the Ancients?",a="The Book of the Ancients contains secrets about the naga that have been kept for centuries.",al={"book contents","what does the book say","naga book"}},{q="Where is the Book of the Ancients?",a="The book is guarded on Ranazjar Isle in Desolace.",al={"book location","where is the book","ranazjar isle book"}},{q="Who wants the book?",a="Azore Aldamort at the tower in Ethel Rethor seeks the book so its knowledge can help the Argent Dawn.",al={"who needs the book","azore book","argent dawn book"}},{q="What is the Gem of the Serpent for?",a="Azore Aldamort gives you the Gem of the Serpent to place in the hand of the Serpent Statue on Ranazjar Isle, summoning the book's protector.",al={"serpent gem","gem statue","how summon guardian"}},{q="Who receives the book?",a="Azore Aldamort says he will pass the book to the Argent Dawn's high council.",al={"where does azore send it","high council book","book destination"}}},ang={["faction:Alliance"]="As an Alliance traveler, the Book of the Ancients offers the Argent Dawn knowledge of the naga, foes who threaten the coast."},kw={"argent dawn","azore aldamort","book of the ancients","desolace","ethel rethor","gem of the serpent","naga","ranazjar isle"},rel={"quest:6027","item:gem-of-the-serpent","subzone:ethel-rethor","zone:desolace","quest:5741","topic:naga","topic:argent-dawn"},src={"Wowpedia: Book of the Ancients","Book of the Ancients (quest)"}}
E["item:broken-tears"] = {t="item",n="Broken Tears",z="desolace",s="Broken Tears are crystal fragments from the cave at Bolgan's Hole in southern Desolace. Warug of the Magram asks for them as proof that the clan can destroy what the Gelkis revere.",h="Broken Tears are crystal fragments from the cave at Bolgan's Hole in southern Desolace.",sec={{t="At Bolgan's Hole",b="In Bolgan's Hole, the Gelkis keep crystals called the tears of Theradras. Warug of the Magram wants you to break them and carry three fragments to Magram Village. He claims Theradras will not protect the Gelkis, and says the Magram need no protection. Their feud gives the broken crystals their meaning.",sp=0}},faq={{q="What are Broken Tears?",a="Broken Tears are pieces of the crystals known as the tears of Theradras, kept in a cave at Bolgan's Hole.",al={"broken tears item","what are the tears"}},{q="Who wants the Broken Tears?",a="Warug, a Magram centaur in Magram Village, asks you to bring him three Broken Tears.",al={"who needs them","warug tears"}},{q="Why does Warug want them?",a="Warug wants the crystals destroyed to show the Gelkis that Theradras will not protect them.",al={"why break crystals","magram reason"}},{q="Where do the Broken Tears come from?",a="The tears of Theradras are kept in a cave at Bolgan's Hole in southern Desolace.",al={"broken tears location","bolgans hole crystals"}},{q="What do the Gelkis believe about Theradras?",a="The Gelkis believe that Theradras protects the centaur; Warug calls that belief foolish.",al={"gelkis theradras","who protects gelkis"}}},kw={"bolgan's hole","broken tears","centaur","desolace","gelkis","magram","tears of theradras","warug"},rel={"quest:1369","subzone:bolgan-s-hole","subzone:magram-village","topic:centaur","zone:desolace"},src={"Wowpedia: Broken Tears","Broken Tears (quest)"}}
E["item:centaur-ear"] = {t="item",n="Centaur Ear",z="desolace",s="A centaur ear is taken as proof of a centaur slain in Desolace. Both the Horde and Alliance demand them as a sign of weakening the clans.",h="A centaur ear is taken as proof of a centaur slain in Desolace.",sec={{t="A Grim Tally",b="In Desolace, centaur ears are gathered for the Horde and Alliance alike. Felgur Twocuts asks Horde travelers for a great hoard, believing fewer centaur will weaken the clans' resolve. At Nijel's Point, Corporal Melkins demands ears in service of the Alliance and its hope for peace. Both banners turn a grisly token into a measure of their struggle with the centaur.",sp=0}},faq={{q="Why do they collect centaur ears?",a="Horde and Alliance officers use centaur ears as proof of slain centaur and as a tally meant to weaken the clans.",al={"why ears","centaur ear purpose","what are ears for"}},{q="Who wants centaur ears for the Horde?",a="Felgur Twocuts in Desolace asks Horde travelers to bring him a hoard of centaur ears.",al={"horde ear guy","felgur wants what","who is felgur"}},{q="Who wants centaur ears for the Alliance?",a="Corporal Melkins at Nijel's Point asks Alliance travelers to bring him centaur ears.",al={"alliance ear npc","melkins ears","nijel ears"}},{q="Do the clans matter which ears are taken from?",a="Felgur Twocuts says the Horde may hunt any centaur clan in Desolace.",al={"which clan","any centaur ears","clan ears"}}},ang={["faction:Horde"]="For the Horde, bringing ears to Felgur Twocuts is meant to weaken the centaur clans and mark the banner behind the bloodshed.",["faction:Alliance"]="At Nijel's Point, Corporal Melkins calls the taking of centaur ears a service to the Alliance and a step toward peace."},kw={"alliance","centaur","centaur bounty","centaur ear","corporal melkins","desolace","felgur twocuts","horde","nijel's point"},rel={"topic:centaur","zone:desolace","subzone:nijel-s-point","npc:felgur-twocuts","topic:horde","topic:alliance","quest:1366"},src={"Wowpedia: Centaur Ear","Centaur Bounty (Horde)","Centaur Bounty (Alliance)"}}
E["item:crate-of-ghost-magnets"] = {t="item",n="Crate of Ghost Magnets",z="desolace",s="The Crate of Ghost Magnets draws Magram ghosts toward a gathering place in the Valley of Bones. Hornizz Brimbuzzle hopes the captured ghost-o-plasm will fetch a fine price from the centaurs.",h="The Crate of Ghost Magnets draws Magram ghosts toward a gathering place in the Valley of Bones.",sec={{t="Ghostly Bait",b="Hornizz Brimbuzzle gives you the Crate of Ghost Magnets for use in the Valley of Bones. Set between the two Dead Goliaths, it draws Magram ghosts close enough for their ghost-o-plasm to be gathered. Hornizz means to sell the strange substance to the centaurs.",sp=0}},faq={{q="What does the crate do?",a="The Crate of Ghost Magnets draws Magram ghosts toward it in the Valley of Bones.",al={"ghost magnet crate","what are ghost magnets for"}},{q="Who gives you the Crate of Ghost Magnets?",a="Hornizz Brimbuzzle gives you the Crate of Ghost Magnets.",al={"where get ghost magnets","hornizz crate"}},{q="Where is the crate used?",a="The crate is used in the Valley of Bones, between the two Dead Goliaths.",al={"ghost magnets location","where place crate"}},{q="Why does Hornizz want ghost-o-plasm?",a="Hornizz hopes to sell ghost-o-plasm to the Magram centaurs.",al={"why collect ghost plasma","what's hornizz doing"}}},kw={"crate of ghost magnets","dead goliaths","ghost magnets","ghost-o-plasm","hornizz brimbuzzle","magram","valley of bones"},rel={"quest:6134","item:ghost-o-plasm","subzone:valley-of-bones","zone:desolace"},src={"Wowpedia: Crate of Ghost Magnets","Ghost-o-plasm Round Up"}}
E["item:crude-charm"] = {t="item",n="Crude Charm",z="desolace",s="A Crude Charm is carried by Kolkar centaurs in Desolace. Uthek the Wise asks for them to help the Gelkis maintain their standing among the clans.",h="A Crude Charm is carried by Kolkar centaurs in Desolace.",sec={{t="Charms of the Kolkar",b="Uthek the Wise wants the Kolkar's charms brought to Gelkis Village. The Gelkis seek to maintain their standing with their neighbors, and Uthek means to burn the charms as proof that Kolkar magic cannot protect them. His contempt for the Kolkar is plain, and he expects their fear to weaken them further.",sp=0}},faq={{q="What is a Crude Charm?",a="A Crude Charm is carried by Kolkar centaurs in Desolace and sought by Uthek the Wise in Gelkis Village.",al={"crude charm","kolkar charm"}},{q="Who wants the charms?",a="Uthek the Wise of Gelkis Village wants the Kolkar's Crude Charms.",al={"who wants crude charms","uthek charms"}},{q="Why does Uthek want Crude Charms?",a="Uthek means to burn the Kolkar charms to show that their magic is weak.",al={"why charms","what are charms for"}},{q="What do the Gelkis want from the Kolkar?",a="The Gelkis seek to maintain their standing among the clans, and Uthek believes weakening Kolkar confidence will help.",al={"gelkis kolkar","why raid kolkar"}}},kw={"centaur","crude charm","desolace","gelkis","kolkar","strange alliance","uthek the wise"},rel={"quest:1384","subzone:gelkis-village","zone:desolace","topic:centaur","quest:1382"},src={"Wowpedia: Crude Charm","Raid on the Kolkar"}}
E["item:crudely-dried-meat"] = {t="item",n="Crudely Dried Meat",z="desolace",s="Crudely Dried Meat is stored food taken from the Magram camp in Desolace. The Gelkis use the stolen stores to sustain their fight against the Magram.",h="Crudely Dried Meat is stored food taken from the Magram camp in Desolace.",sec={{t="Meat Stores",b="Magram hunters preserve extra meat so their people can fight between hunts. Uthek the Wise asks you to take those stores from the Magram camp and bring them to Gelkis Village. He gives the meat to the Gelkis, who mean to fight on full bellies.",sp=0}},faq={{q="What is Crudely Dried Meat?",a="Crudely Dried Meat is preserved food stored by the Magram in Desolace.",al={"dried meat","crude meat","what meat is this"}},{q="Who wants the meat?",a="Uthek the Wise wants you to bring the Magram's stored meat to him in Gelkis Village.",al={"who needs this meat","uthek meat","meat for gelkis"}},{q="Why do the Gelkis want it?",a="The Gelkis plan to eat the meat so they can fight the Magram for many days without rest.",al={"why steal the meat","gelkis hungry","what do they use it for"}},{q="Where does the meat come from?",a="The Magram store extra meat at their camp in Desolace, east of Gelkis Village.",al={"where find dried meat","magram meat","meat sacks"}}},kw={"crudely dried meat","desolace","dried meat","gelkis","magram","stealing supplies","uthek the wise"},rel={"quest:1370","subzone:gelkis-village","topic:centaur","zone:desolace"},src={"Wowpedia: Crudely Dried Meat","Stealing Supplies"}}
E["item:demon-box"] = {t="item",n="Demon Box",z="desolace",s="The Burning Blade holds the Demon Box at Thunder Axe Fortress in Desolace. Taiga Wisemane in Shadowprey Village wants it to help oppose the demonic threat.",h="The Burning Blade holds the Demon Box at Thunder Axe Fortress in Desolace.",sec={{t="A Sealed Relic",b="At Thunder Axe Fortress in Desolace, the Burning Blade guards the Demon Box. Within it lies the Hand of Iruxos, which the Burning Blade uses to open demonic portals at Mannoroc Coven. Taiga Wisemane in Shadowprey Village seeks the box so the portals can be opposed.",sp=0}},faq={{q="What is the Demon Box?",a="The Demon Box holds the Hand of Iruxos, a powerful artifact used by the Burning Blade to open demonic portals.",al={"demon box","what box","box contents"},sp=1},{q="Where is the Demon Box?",a="The Burning Blade keeps it inside Thunder Axe Fortress, in Desolace.",al={"box location","where box","thunder axe box"}},{q="What does the Burning Blade use it for?",a="The Burning Blade uses the Demon Box's Hand of Iruxos to open demonic portals at Mannoroc Coven.",al={"burning blade box","why do they want it","demon portals"},sp=1},{q="Who wants the Demon Box?",a="Taiga Wisemane in Shadowprey Village seeks the Demon Box and the Demon Pick.",al={"who wants box","taiga wisemane box","shadowprey village"}},{q="How do you open the red crystal?",a="Use the Demon Pick on the red crystal in Thunder Axe Fortress to gain access to the Demon Box.",al={"red crystal","get demon box","demon pick crystal"}}},ang={["faction:Horde"]="As a member of the Horde, you can bring the Demon Box to Taiga Wisemane in Shadowprey Village to help oppose the Burning Blade's portals."},kw={"burning blade","demon box","demon pick","desolace","hand of iruxos","mannoroc coven","shadowprey village","taiga wisemane","thunder axe fortress"},rel={"quest:5381","item:demon-pick","quest:5581","subzone:thunder-axe-fortress","subzone:mannoroc-coven","npc:taiga-wisemane","subzone:shadowprey-village","zone:desolace"},src={"Wowpedia: Demon Box","Hand of Iruxos (quest)"}}
E["item:demon-pick"] = {t="item",n="Demon Pick",z="desolace",s="The Demon Pick opens a red crystal inside Thunder Axe Fortress. Taiga Wisemane needs it to reach the Demon Box held by the Burning Blade.",h="The Demon Pick opens a red crystal inside Thunder Axe Fortress.",sec={{t="The Red Crystal",b="Beyond the fortress walls, the red crystal bars the way to the Demon Box. The Demon Pick opens it, granting access to what the Burning Blade keeps within Thunder Axe Fortress. Taiga Wisemane waits in Shadowprey Village for the pick and the box, so the threat at Mannoroc Coven can be faced.",sp=0}},faq={{q="What does the Demon Pick open?",a="The Demon Pick opens a red crystal in Thunder Axe Fortress, giving access to the Demon Box.",al={"demon pick use","pick for red crystal"}},{q="Where do I use the Demon Pick?",a="Use the Demon Pick on the red crystal inside Thunder Axe Fortress.",al={"where use demon pick","demon pick location"}},{q="Who needs the Demon Pick?",a="Taiga Wisemane in Shadowprey Village asks for the Demon Pick along with the Demon Box.",al={"who wants the pick","taiga pick"}},{q="Why does Taiga want the Demon Pick?",a="Taiga needs the Demon Pick to reach the Demon Box, which the Burning Blade holds at Thunder Axe Fortress.",al={"why demon pick","demon pick reason"}},{q="What is in the Demon Box?",a="The powerful Hand of Iruxos lies within the Demon Box.",al={"demon box contents","what's in the box"},sp=1},{q="Why is the Demon Box dangerous?",a="The Burning Blade uses the Hand of Iruxos inside the box to open demonic portals at Mannoroc Coven.",al={"burning blade box","demon portals"},sp=1}},kw={"burning blade","demon box","demon pick","hand of iruxos","mannoroc coven","red crystal","shadowprey village","taiga wisemane","thunder axe fortress"},rel={"quest:5381","item:demon-box","subzone:thunder-axe-fortress","npc:taiga-wisemane","subzone:shadowprey-village","quest:5581","subzone:mannoroc-coven"},src={"Wowpedia: Demon Pick","Hand of Iruxos (quest)"}}
E["item:doomwarder-blood"] = {t="item",n="Doomwarder Blood",z="desolace",s="Doomwarder Blood is gathered from powerful demons near Mannoroc Coven in Desolace. Kreldig Ungor needs ten vials for a mage’s experiments.",h="Doomwarder Blood is gathered from powerful demons near Mannoroc Coven in Desolace.",sec={{t="A Demon’s Blood",b="Kreldig Ungor in Desolace asks for ten vials of Doomwarder Blood as the final part of his request for Reagents for Reclaimers Inc. The blood comes from Doomwarder Captains or lords among the demons near Mannoroc Coven. Kreldig warns that collecting it is harder than gathering the other reagents, and the demons are far from the land’s centaur camps.",sp=0}},faq={{q="Who needs Doomwarder Blood?",a="Kreldig Ungor needs ten vials of Doomwarder Blood for Reagents for Reclaimers Inc., a set of reagents requested for a mage’s experiments.",al={"who wants the blood","kreldig's reagents","blood for kreldig"}},{q="Where does Doomwarder Blood come from?",a="Doomwarder Blood comes from Doomwarder Captains and lords near Mannoroc Coven in southern Desolace.",al={"where to find doomwarder blood","blood location","doomwarder blood source"}},{q="Why does Kreldig want the blood?",a="Kreldig gathers the blood as one of three reagents for a mage’s experiments.",al={"why blood","what is it for","mage experiment"}},{q="How many vials are needed?",a="Kreldig asks for ten vials of Doomwarder Blood.",al={"how much blood","number of vials","how many doomwarder"}},{q="Is the blood the only reagent Kreldig needs?",a="No. Kreldig also asks for ten Felhound Brains and ten Nether Wings.",al={"other reagents","what else does he need","brain and wings"}}},kw={"desolace","doomwarder blood","doomwarder captain","felhound brain","kreldig ungor","mannoroc coven","nether wing","reagents for reclaimers inc"},rel={"zone:desolace","subzone:mannoroc-coven","npc:kreldig-ungor","quest:1458","item:felhound-brain","item:nether-wing"},src={"Wowpedia: Doomwarder Blood","Reagents for Reclaimers Inc. (3)"}}
E["item:draenethyst-shard"] = {t="item",n="Draenethyst Shard",z="desolace",s="A Draenethyst Shard is a red crystal brought from the Swamp of Sorrows to the Gelkis centaur in Desolace. Uthek the Wise seeks its magic to strengthen the Gelkis against their enemies.",h="A Draenethyst Shard is a red crystal brought from the Swamp of Sorrows to the Gelkis centaur in Desolace.",sec={{t="A Red Crystal",b="Uthek the Wise speaks of draenethyst as new to the earth, carried from a distant land where demons rule. He asks you to bring him a shard from the Swamp of Sorrows, held by Ongeku, whom the Gelkis call the lost one. Uthek believes its magic can aid his people against their enemies.",sp=0}},faq={{q="What is a Draenethyst Shard?",a="A Draenethyst Shard is a piece of red crystal that Uthek the Wise says came from a distant land ruled by demons.",al={"draenethyst","red crystal","what shard is this"}},{q="Who wants the shard?",a="Uthek the Wise of the Gelkis in Desolace wants the shard, believing its magic can strengthen his people.",al={"who needs draenethyst","uthek shard","gelkis crystal"}},{q="Where do I find a Draenethyst Shard?",a="Ongeku holds a Draenethyst Shard in the Swamp of Sorrows.",al={"where shard","ongeku shard","draenethyst location"}},{q="Who is Ongeku?",a="Ongeku is the lost one who holds the Draenethyst Shard in the Swamp of Sorrows.",al={"ongeku who","lost one","who has the crystal"}},{q="Why does Uthek want it?",a="Uthek believes the shard's magic will strengthen him and help the Gelkis fight their enemies.",al={"why crystal","what does shard do","gelkis magic"}}},ang={["faction:Horde"]="The Gelkis seek the shard in the Swamp of Sorrows, near Stonard, a Horde town in the southern swamp."},kw={"desolace","draenethyst","draenethyst shard","gelkis","ongeku","red crystal","swamp of sorrows","uthek the wise"},rel={"quest:1373","zone:desolace","zone:swampofsorrows","subzone:gelkis-village","topic:centaur"},src={"Wowpedia: Draenethyst Shard","Ongeku (quest)"}}
E["item:felhound-brain"] = {t="item",n="Felhound Brain",z="desolace",s="A Felhound Brain is a demon part sought in Desolace for Reagents for Reclaimers Inc. Kreldig Ungor gathers them with other materials for a mage’s experiments.",h="A Felhound Brain is a demon part sought in Desolace for Reagents for Reclaimers Inc.",sec={{t="A Mage’s Reagents",b="Near Mannoroc Coven, Ley Hunters, Mage Hunters, and Mana Eaters carry the brains Kreldig Ungor seeks. He asks for ten alongside Nether Wings and Doomwarder Blood, the final group of materials for Reagents for Reclaimers Inc. The work brings you against demons in a land where centaur hold much of the country.",sp=0}},faq={{q="What is a Felhound Brain for?",a="Kreldig Ungor needs ten Felhound Brains for Reagents for Reclaimers Inc., where they join Nether Wings and Doomwarder Blood as materials for a mage’s experiments.",al={"felhound brain use","why collect felhound brains"}},{q="Which demons have Felhound Brains?",a="Ley Hunters, Mage Hunters, and Mana Eaters in Desolace carry Felhound Brains.",al={"brain from which demon","felhound brain mobs"}},{q="Where can I find the felhounds?",a="The felhounds are near Mannoroc Coven in southern Desolace, beyond the Kodo Graveyard.",al={"felhound brain location","where are ley hunters"}},{q="Who wants the Felhound Brains?",a="Kreldig Ungor asks for the Felhound Brains as part of the materials for Reagents for Reclaimers Inc.",al={"who needs the brains","kreldig ungor brain"}}},ang={["class:Mage"]="Kreldig Ungor gathers Felhound Brains and other demon materials for a mage’s experiments."},kw={"felhound","felhound brain","kreldig ungor","ley hunter","mage hunter","mana eater","mannoroc coven","reagents for reclaimers inc"},rel={"quest:1458","item:doomwarder-blood","item:nether-wing","subzone:mannoroc-coven","zone:desolace"},src={"Wowpedia: Felhound Brain","Reagents for Reclaimers Inc. (3)"}}
E["item:gem-of-the-serpent"] = {t="item",n="Gem of the Serpent",z="desolace",s="The Gem of the Serpent is entrusted to you by Azore Aldamort at Ethel Rethor. It is used to seek the Book of the Ancients, which holds secrets of the naga.",h="The Gem of the Serpent is entrusted to you by Azore Aldamort at Ethel Rethor.",sec={{t="A Serpent's Charge",b="Azore Aldamort gives you the Gem of the Serpent at his tower in Ethel Rethor. He bids you place it in the hand of the Serpent Statue on Ranazjar Isle, northwest of the tower. The gem will summon the guardian of the Book of the Ancients, a tome said to hold secrets of the naga.",sp=0}},faq={{q="What is the Gem of the Serpent for?",a="Azore Aldamort entrusts you with the Gem of the Serpent so you can summon the guardian of the Book of the Ancients.",al={"gem purpose","what does serpent gem do"}},{q="Where do I use the Gem of the Serpent?",a="Place the Gem of the Serpent in the hand of the Serpent Statue on Ranazjar Isle, a small island northwest of Ethel Rethor.",al={"where gem go","serpent statue location"}},{q="Who gives you the Gem of the Serpent?",a="Azore Aldamort, at the tower in Ethel Rethor, entrusts you with the Gem of the Serpent.",al={"who gives gem","azore gem"}},{q="What does the gem summon?",a="Placed on the Serpent Statue's hand, the Gem of the Serpent summons the protector of the Book of the Ancients.",al={"gem summon","serpent gem guardian"}},{q="Why does Azore want the Book of the Ancients?",a="Azore Aldamort wants the Book of the Ancients because it contains secrets of the naga, kept for centuries.",al={"why book wanted","naga secrets book"}}},kw={"azore aldamort","book of the ancients","ethel rethor","gem of the serpent","naga","ranazjar isle","serpent statue"},rel={"quest:6027","subzone:ethel-rethor","zone:desolace","quest:5741","topic:naga"},src={"Wowpedia: Gem of the Serpent","Book of the Ancients (quest)"}}
E["item:ghost-o-plasm"] = {t="item",n="Ghost-o-Plasm",z="desolace",s="Ghost-o-Plasm is ghostly energy gathered from Magrami Spectres in Desolace. Hornizz Brimbuzzle hopes to sell it to the Magram centaurs.",h="Ghost-o-Plasm is ghostly energy gathered from Magrami Spectres in Desolace.",sec={{t="Gathered in the Valley",b="Between the two great skeletons called the Dead Goliaths, a crate of ghost magnets draws Magrami Spectres from the Valley of Bones. Their ghost-o-plasm is what Hornizz Brimbuzzle wants. He hopes the Magram centaurs will pay well for it, though he still has to convince them what the strange substance is.",sp=0}},faq={{q="What is Ghost-o-Plasm?",a="Ghost-o-Plasm is ghostly energy taken from Magrami Spectres in Desolace.",al={"ghost o plasm","ghost stuff","what is this slime"}},{q="Where do I find Ghost-o-Plasm?",a="Magrami Spectres in the Valley of Bones yield Ghost-o-Plasm when drawn to a crate of ghost magnets.",al={"where ghost plasm","get ghost-o-plasm","ghost stuff location"}},{q="Who wants Ghost-o-Plasm?",a="Hornizz Brimbuzzle wants Ghost-o-Plasm, hoping to sell it to the Magram centaurs.",al={"who needs ghost plasm","hornizz stuff","sell ghost energy"}},{q="Why does Hornizz want it?",a="Hornizz believes the Magram centaurs will pay well for captured ghost energy.",al={"why hornizz wants it","why collect ghost stuff","centaur ghost energy"}}},ang={["race:Gnome"]="As a gnome, you may recognize Hornizz's ghost magnets as clever devices, though his plan depends on what the Magram centaurs will pay.",["faction:Horde"]="As a member of the Horde, you are helping Hornizz bargain with the Magram centaurs through a strange trade in ghost energy."},kw={"ghost energy","ghost-o-plasm","ghostoplasm","hornizz brimbuzzle","magnet","magram centaurs","magrumi spectres","valley of bones"},rel={"quest:6134","item:crate-of-ghost-magnets","subzone:valley-of-bones","zone:desolace","topic:centaur"},src={"Wowpedia: Ghost-o-Plasm","Ghost-o-plasm Round Up"}}
E["item:hand-of-iruxos"] = {t="item",n="Hand of Iruxos",z="desolace",s="The Hand of Iruxos is a gruesome artifact that can open demonic portals and close those it has opened. Taiga Wisemane needs it to help banish the portals at Mannoroc Coven.",h="The Hand of Iruxos is a gruesome artifact that can open demonic portals and close those it has opened.",sec={{t="A Gruesome Sight",b="At Shadowprey Village, Taiga Wisemane gives you the Hand of Iruxos and asks you to carry it to Mannoroc Coven. The Burning Blade cultists there have opened portals that bring demons into the world. The hand can close portals it has opened, and Taiga needs its power to stem the growing demon threat.",sp=0}},faq={{q="What is the Hand of Iruxos?",a="It is a grisly relic that opens demonic portals, and can close the ones it opened.",al={"hand of iruxos","iruxos hand"}},{q="Who gives me the Hand of Iruxos?",a="Taiga Wisemane at Shadowprey Village gives you the Hand of Iruxos and asks you to use it against the portals at Mannoroc Coven.",al={"who has the hand","taiga hand"}},{q="Where do I use the Hand of Iruxos?",a="Taiga Wisemane asks you to use the Hand of Iruxos to banish demonic portals at Mannoroc Coven.",al={"hand location","where use hand"}},{q="Why are there demons at Mannoroc Coven?",a="Burning Blade cultists at Mannoroc Coven have opened portals that bring demons into the world.",al={"mannoroc demons","why demons"}},{q="Can the Hand of Iruxos close portals?",a="The Hand of Iruxos can close demonic portals it has opened.",al={"close portals","portal hand"}}},kw={"burning blade","demonic portals","hand of iruxos","iruxos","mannoroc coven","shadowprey village","taiga wisemane"},rel={"item:demon-box","quest:5581","npc:taiga-wisemane","subzone:mannoroc-coven","zone:desolace"},src={"Wowpedia: Hand of Iruxos","Portals of the Legion (Classic)"}}
E["item:hatefury-claw"] = {t="item",n="Hatefury Claw",z="desolace",s="A Hatefury Claw is taken from the satyrs east of Nijel’s Point in Desolace. Kreldig Ungor gathers claws and horns for a gnome mage in Kharanos.",h="A Hatefury Claw is taken from the satyrs east of Nijel’s Point in Desolace.",sec={{t="A Reclaimer’s List",b="Kreldig Ungor has come to Desolace with a list of reagents from Leftwitch, a gnome mage in Kharanos. The Hatefury satyrs among Sargeron’s ruins, east of Nijel’s Point, carry the claws and horns he needs. Bring the gathered materials to Kreldig, and he will set about the next item on the list.",sp=0}},faq={{q="Who wants Hatefury Claws?",a="Kreldig Ungor gathers Hatefury Claws and horns for Leftwitch, a gnome mage in Kharanos.",al={"who needs the claws","claw buyer"}},{q="Where do Hatefury Claws come from?",a="Hatefury satyrs in the Sargeron ruins, east of Nijel’s Point in Desolace, carry the claws.",al={"where claws from","claw location"}},{q="Why is Kreldig collecting claws?",a="Kreldig is gathering reagents from a list sent by Leftwitch, a gnome mage in Kharanos.",al={"why claws","reagents for reclaimers"}},{q="What else does Kreldig need?",a="Kreldig needs Hatefury Horns as well as Hatefury Claws for Leftwitch’s list.",al={"what other reagents","horns too"}}},ang={["race:Gnome"]="As a gnome, Leftwitch’s request reaches you through Kreldig Ungor, who gathers reagents in Desolace for the mage in Kharanos.",["class:Mage"]="As a mage, you may recognize the practical need behind Leftwitch’s list: Kreldig is gathering claws and horns as reagents."},kw={"hatefury claw","hatefury horn","hatefury satyr","kreldig ungor","leftwitch","nijel's point","reagents","sargeron"},rel={"quest:1458","item:hatefury-horn","subzone:sargeron","subzone:nijel-s-point","zone:desolace"},src={"Wowpedia: Hatefury Claw","Reagents for Reclaimers Inc. (quest)"}}
E["item:hatefury-horn"] = {t="item",n="Hatefury Horn",z="desolace",s="A Hatefury Horn is taken from one of the satyrs in the Sargeron ruins east of Nijel’s Point. Kreldig Ungor gathers horns and claws for a reagent list from Kharanos.",h="A Hatefury Horn is taken from one of the satyrs in the Sargeron ruins east of Nijel’s Point.",sec={{t="A Reagent from Sargeron",b="East of Nijel’s Point, the Hatefury satyrs haunt the Sargeron ruins. Their horns are among the reagents Kreldig Ungor needs for Leftwitch, a gnome mage in Kharanos. Kreldig asks for ten horns alongside ten Hatefury claws, though he cannot promise their quality.",sp=0}},faq={{q="Where do Hatefury Horns come from?",a="Hatefury satyrs in the Sargeron ruins east of Nijel’s Point carry the horns.",al={"hatefury horn source","where get horns","satyr horns"}},{q="Who wants Hatefury Horns?",a="Kreldig Ungor collects ten Hatefury Horns for a reagent list sent by Leftwitch, a gnome mage in Kharanos.",al={"who needs hatefury horns","kreldig horns","reagents for reclaimers"}},{q="Why is Kreldig collecting them?",a="Kreldig gathers the horns as reagents for Leftwitch in Kharanos.",al={"why horns","leftwitch reagents","what are horns for"}},{q="What else does Kreldig need?",a="Kreldig also asks for ten Hatefury Claws.",al={"other reagents","hatefury claws","what with the horns"}}},ang={["race:Gnome"]="As a gnome, you may know Leftwitch by reputation: the mage in Kharanos sent the Reclaimers a list of reagents."},kw={"hatefury claw","hatefury horn","hatefury satyr","kreldig ungor","leftwitch","nijel's point","reagents","sargeron"},rel={"quest:1458","item:hatefury-claw","subzone:sargeron","subzone:nijel-s-point","zone:desolace","topic:satyr"},src={"Wowpedia: Hatefury Horn","Reagents for Reclaimers Inc. (quest)"}}
E["item:karnitol-s-satchel"] = {t="item",n="Karnitol's Satchel",z="desolace",s="Karnitol's Satchel holds belongings sought after the Karnitol shipwreck in Desolace. Kreldig Ungor directs the search toward the Slitherblade naga along the coast.",h="Karnitol's Satchel holds belongings sought after the Karnitol shipwreck in Desolace.",sec={{t="Among the Slitherblade",b="Kreldig Ungor points you toward Ranazjar Isle, where the Slitherblade naga dwell among night elf ruins beneath the sea. He suspects the powerful tidehunters and sea witches may have gathered Karnitol's belongings. The satchel is recovered from them along the Desolace coast.",sp=0},{t="Back to the Reclaimers",b="In Desolace, you return the recovered satchel to Kreldig Ungor, who calls it a great service to the Reclaimers. He sends it onward to Roetten Stonehammer in Ironforge. Roetten says the chest was destroyed, but the belongings are present, and leaves Karnitol to judge their condition.",sp=0}},faq={{q="Who is looking for Karnitol's satchel?",a="Kreldig Ungor directs the search for Karnitol's belongings on behalf of the Reclaimers. The satchel is then taken to Roetten Stonehammer in Ironforge.",al={"who wants the satchel","karnitol belongings","satchel for who"}},{q="Where can I find the satchel?",a="The Slitherblade naga along the Desolace coast may have Karnitol's belongings. Kreldig Ungor points you toward their tidehunters and sea witches near Ranazjar Isle.",al={"where satchel","satchel location","find karnitol's bag"}},{q="What are the Slitherblade?",a="The Slitherblade are a tribe of naga dwelling among night elf ruins beneath the sea near Ranazjar Isle in Desolace.",al={"slitherblade naga","naga in desolace","who lives at ranazjar"}},{q="Who receives the satchel in Ironforge?",a="Roetten Stonehammer receives the satchel in Ironforge and says Karnitol can judge whether the recovered belongings are satisfactory.",al={"satchel ironforge","who gets the bag","roetten's satchel"},sp=1},{q="Was Karnitol's chest recovered intact?",a="No. Roetten Stonehammer says the chest was destroyed, though the belongings are there for Karnitol to inspect.",al={"what happened to chest","chest destroyed","karnitol things damaged"},sp=1}},ang={["faction:Alliance"]="The Reclaimers seek Karnitol's belongings, and Kreldig Ungor calls their recovery a great service to them."},kw={"desolace","karnitol","karnitol's satchel","kreldig ungor","naga","ranazjar isle","reclaimers","roetten stonehammer","satchel","slitherblade"},rel={"quest:1454","zone:desolace","npc:kreldig-ungor","npc:roetten-stonehammer","topic:naga","topic:night-elf"},src={"Wowpedia: Karnitol's Satchel","The Karnitol Shipwreck (3)","The Karnitol Shipwreck (4)"}}
E["item:khan-dez-hepah-s-head"] = {t="item",n="Khan Dez'hepah's Head",z="desolace",s="Khan Dez'hepah's Head is proof that the Kolkar leader has been defeated. Felgur Twocuts wants it as a show of strength against the centaur clans.",h="Khan Dez'hepah's Head is proof that the Kolkar leader has been defeated.",sec={{t="Proof of Strength",b="Across Desolace, the centaur clans fight among themselves. Felgur Twocuts fears they would be a fierce foe if they united, so he sends you to disrupt the Kolkar by defeating their leader, Khan Dez'hepah. His head is the proof Felgur asks you to bring back.",sp=0}},faq={{q="Who wants Khan Dez'hepah's Head?",a="Felgur Twocuts asks you to bring Khan Dez'hepah's Head to him in Desolace.",al={"who wants it","felgur's head request"}},{q="Why does Felgur want the head?",a="Felgur wants to disrupt the Kolkar clan and show strength to the centaur clans of Desolace.",al={"why take the head","what's it for"}},{q="Who was Khan Dez'hepah?",a="Khan Dez'hepah was the leader of the Kolkar clan in Desolace.",al={"dez'hepah who","kolkar leader"}},{q="Where can I find Khan Dez'hepah?",a="Khan Dez'hepah is at Kolkar Village, northeast of Felgur Twocuts.",al={"where is dez'hepah","kolkar village location"}}},kw={"centaur","desolace","dez'hepah's head","felgur twocuts","khan dez'hepah","kolkar","kolkar village"},rel={"quest:1365","npc:felgur-twocuts","topic:kolkar-clan","topic:centaur","zone:desolace"},src={"Wowpedia: Khan Dez'hepah's Head","Khan Dez'hepah (quest)"}}
E["item:khan-jehn-s-head"] = {t="item",n="Khan Jehn's Head",z="desolace",s="Khan Jehn's Head is proof that the Magram Khan has been slain. Uthek the Wise of Gelkis Village demands it as a sign of friendship with the Gelkis clan.",h="Khan Jehn's Head is proof that the Magram Khan has been slain.",sec={{t="A Sign of Friendship",b="In Desolace, Uthek the Wise asks you to bring Khan Jehn's Head to Gelkis Village. Jehn leads the rival Magram centaur, and Uthek says the earth tells him their clan is growing weak. The Gelkis want their enemy's Khan dead, and they look to you to prove you stand with them.",sp=0},{t="The Khan's Fall",b="When you return with Khan Jehn's Head, Uthek calls Jehn strong but foolish. He believes earth magic is stronger than Jehn's might. With the Magram leader gone, Uthek expects the clan to fall, and says the Gelkis will rule Desolace.",sp=1}},faq={{q="Who wants Khan Jehn's Head?",a="Uthek the Wise of Gelkis Village asks you to bring Khan Jehn's Head as proof of friendship with the Gelkis.",al={"who wants the head","Uthek head","Gelkis request"}},{q="Who was Khan Jehn?",a="Khan Jehn was the leader of the Magram centaur, the rivals of the Gelkis clan.",al={"who is Jehn","Magram Khan","Khan Jehn"}},{q="Why do the Gelkis want Jehn dead?",a="Uthek says the Magram are growing weak and asks you to kill their Khan. He believes the Gelkis can rule once Jehn is gone.",al={"why kill Jehn","Gelkis vs Magram","why Jehn"}},{q="Where do I bring Khan Jehn's Head?",a="Bring Khan Jehn's Head to Uthek the Wise in Gelkis Village, in Desolace.",al={"where head go","bring Jehn head","Uthek location"}},{q="What does Uthek say after Jehn falls?",a="Uthek calls Jehn strong but foolish and says the Magram will fall without their leader. He expects the Gelkis to rule.",al={"Uthek completion","what happens after Jehn","Gelkis rule"},sp=1}},kw={"centaur","desolace","earth magic","gelkis","jehn","khan jehn","khan jehn's head","magram","uthek the wise"},rel={"quest:1374","quest:1382","subzone:gelkis-village","topic:centaur","zone:desolace"},src={"Wowpedia: Khan Jehn's Head","Khan Jehn (quest)"}}
E["item:khan-shaka-s-head"] = {t="item",n="Khan Shaka's Head",z="desolace",s="Khan Shaka’s Head is the head of the Gelkis khan, sought by Warug of the Magram in Desolace. It marks the Magram’s strength against their rival clan.",h="Khan Shaka’s Head is the head of the Gelkis khan, sought by Warug of the Magram in Desolace.",sec={{t="A Khan's Head",b="Warug of Magram Village wants Khan Shaka’s head after you have helped the Magram. Shaka leads the Gelkis, and Warug means to keep the head on a pike. He wants Shaka to see the strength of the Magram.",sp=0}},faq={{q="Who is Khan Shaka?",a="Khan Shaka is the khan of the Gelkis centaur in Desolace.",al={"shaka","khan shaka identity","gelkis khan"}},{q="Who wants Khan Shaka’s head?",a="Warug wants it, in Magram Village, once you have proven yourself to the Magram.",al={"who wants shaka head","warug wants head","magram request"}},{q="Why does Warug want the head?",a="Warug wants to keep Khan Shaka’s head on a pike so Shaka can see the strength of the Magram.",al={"why shaka head","warug reason","magram strength"},sp=1},{q="Where is Khan Shaka’s head taken?",a="You are to bring Khan Shaka’s head to Warug in Magram Village, Desolace.",al={"where bring head","head for warug","magram village head"}}},kw={"centaur","desolace","gelkis","khan shaka","magram","magram village","shaka's head","warug"},rel={"quest:1375","subzone:magram-village","topic:centaur","zone:desolace"},src={"Wowpedia: Khan Shaka's Head","Khan Shaka (quest)"}}
E["item:kodo-bone"] = {t="item",n="Kodo Bone",z="desolace",s="Kodo bones from Desolace’s Kodo Graveyard are valuable to Bibbly F'utzbuckle. He sees many uses for them, from furniture and instruments to blasting powder.",h="Kodo bones from Desolace’s Kodo Graveyard are valuable to Bibbly F'utzbuckle.",sec={{t="A Goblin’s Trade",b="Bibbly F'utzbuckle at Kormek's Hut seeks kodo bones from the graveyard south of his home. He says customers make furniture, musical instruments, and blasting powder from them. A caravan carries his bones to Shadowprey Village, and Bibbly hopes the trade will make him rich.",sp=0}},faq={{q="Who wants kodo bones?",a="Bibbly F'utzbuckle at Kormek's Hut wants kodo bones from the Kodo Graveyard.",al={"kodo bone buyer","who wants the bones"}},{q="What are kodo bones used for?",a="Bibbly says his customers make furniture, musical instruments, and blasting powder from kodo bones.",al={"kodo bone uses","what do bones make"}},{q="Where does the caravan take the bones?",a="Bibbly says a caravan sells his kodo bones at Shadowprey Village.",al={"bone caravan","where bones go"}}},kw={"bibbly f'utzbuckle","bone collector","desolace","kodo bone","kodo bones","kodo graveyard","kormek's hut","shadowprey village"},rel={"quest:5501","subzone:kodo-graveyard","subzone:kormek-s-hut","subzone:shadowprey-village","zone:desolace"},src={"Wowpedia: Kodo Bone","Bone Collector"}}
E["item:kodo-kombobulator"] = {t="item",n="Kodo Kombobulator",z="desolace",s="The Kodo Kombobulator lets Smeed Scrabblescrew tame aged kodos in Desolace. He uses it to supply a caravan partnership with beasts for the road.",h="The Kodo Kombobulator lets Smeed Scrabblescrew tame aged kodos in Desolace.",sec={{t="A Goblin's Device",b="At Scrabblescrew's Camp in Desolace, Smeed Scrabblescrew lends the Kodo Kombobulator to tame ancient or aged kodos. It jolts each beast into following him, giving the local caravan a source of fresh mounts. Smeed hopes the partnership will bring him a handsome profit.",sp=0}},faq={{q="What does the Kodo Kombobulator do?",a="The Kodo Kombobulator tames ancient or aged kodos and makes them follow Smeed Scrabblescrew.",al={"kodo device","what's the kombobulator for"}},{q="Who made the Kodo Kombobulator?",a="Smeed Scrabblescrew says he learned to rejuvenate and control aged and dying kodos with his Kodo Kombobulator.",al={"who owns the kodo thing","smeed's device"}},{q="Why does Smeed want tamed kodos?",a="Smeed, the caravan owner Cork, and Rigger formed a partnership around his ability to tame kodos. The caravan relies on his supply.",al={"why tame kodos","kodos for the caravan"}},{q="Where can I find the Kodo Kombobulator?",a="Smeed Scrabblescrew at Scrabblescrew's Camp in Desolace provides the Kodo Kombobulator for his work with aged kodos.",al={"kombobulator location","where is smeed"}}},ang={["profession:Engineering"]="As an engineer, you may recognize the goblin craft behind Smeed Scrabblescrew's device for controlling aged kodos."},kw={"aged kodo","caravan","desolace","kodo","kodo kombobulator","smeed scrabblescrew","taming"},rel={"quest:5561","zone:desolace","topic:goblin"},src={"Wowpedia: Kodo Kombobulator","Kodo Roundup"}}
E["item:leftwitch-s-package"] = {t="item",n="Leftwitch's Package",z="desolace",s="Leftwitch’s Package carries the last piece of Reclaimers Inc.’s business in Desolace back to Ironforge. Roetten Stonehammer receives it and pays for the work.",h="Leftwitch’s Package carries the last piece of Reclaimers Inc.’s business in Desolace back to Ironforge.",sec={{t="Back to Ironforge",b="Roetten Stonehammer waits in Ironforge for Leftwitch’s Package from Desolace. Carry it back to him, and Reclaimers Inc. will pay for this final piece of work. Roetten is glad to have you aboard, even for a small job.",sp=0}},faq={{q="Who is Leftwitch’s Package for?",a="Roetten Stonehammer in Ironforge receives Leftwitch’s Package on Leftwitch’s behalf.",al={"who wants the package","leftwitch package for who"}},{q="Where does the package go?",a="Take Leftwitch’s Package from Desolace to Roetten Stonehammer in Ironforge.",al={"where to take it","package destination"}},{q="What is the package connected to?",a="Leftwitch’s Package is the final delivery in Reagents for Reclaimers Inc.’s business in Desolace.",al={"why package","reclaimers package"}},{q="What does Roetten do when he gets it?",a="Roetten thanks you for the timely work and pays you on behalf of Reclaimers Inc.",al={"what happens after delivery","roetten pays"}}},kw={"desolace","ironforge","leftwitch","leftwitch's package","reclaimers inc","roetten stonehammer"},rel={"quest:1458","zone:desolace","zone:ironforge","npc:roetten-stonehammer"},src={"Wowpedia: Leftwitch's Package","Reagents for Reclaimers Inc. (4)"}}
E["item:letter-of-commendation"] = {t="item",n="Letter of Commendation",z="desolace",s="Brother Anton's Letter of Commendation bears his seal and carries the Scarlet Crusade's regard. It directs its bearer from Desolace to Raleigh the Devout in Southshore.",h="Brother Anton's Letter of Commendation bears his seal and carries the Scarlet Crusade's regard.",sec={{t="A Sealed Letter",b="Raleigh the Devout waits in Southshore for the bearer of Brother Anton's letter. The sealed message praises the Scarlet Crusade's strongholds, from Hearthglen to Tirisfal Glades. It declares that the plague's true threat lies in Lordaeron and asks Raleigh to receive the bearer.",sp=0}},faq={{q="Who gave me the letter?",a="Brother Anton gave the Letter of Commendation and sealed it with his mark.",al={"letter from Anton","Anton letter","who sealed it"}},{q="Who should receive it?",a="Raleigh the Devout in Southshore is named as the recipient.",al={"where take letter","Raleigh letter","who gets this"}},{q="What is the letter for?",a="The letter commends its bearer to Raleigh and asks him to escort them to a place of honor in the Scarlet Monastery.",al={"why this letter","what does it do","letter purpose"},sp=1},{q="What does Brother Anton say about the plague?",a="Brother Anton says the plague's true threat lies in Lordaeron.",al={"plague threat","Anton on Lordaeron","where is plague worst"}},{q="What does the letter say about the Scarlet Crusade?",a="The Scarlet Crusade claims strongholds from Hearthglen to Tirisfal Glades and calls them bastions of cleansing.",al={"crusade strongholds","scarlet bastions","where crusade claims land"}}},ang={["faction:Alliance"]="As an Alliance traveler, Southshore is a familiar town where Raleigh the Devout receives Brother Anton's sealed commendation."},kw={"brother anton","desolace","letter of commendation","lordaeron","raleigh the devout","scarlet crusade","scarlet monastery","southshore"},rel={"quest:261","quest:1053","quest:6141","topic:scarlet-crusade","zone:desolace","subzone:southshore"},src={"Wowpedia: Letter of Commendation","Down the Scarlet Path (2)"}}
E["item:malem-pendant"] = {t="item",n="Malem Pendant",z="desolace",s="The Malem Pendant is found in a wagon in Desolace. Vahlarriel Demonslayer at Nijel’s Point needs it, along with news of tracks leading south.",h="The Malem Pendant is found in a wagon in Desolace.",sec={{t="A Sign in the Wagon",b="Footprints lead south from the wagon where you find the Malem Pendant. Smoke rises from a nearby fort, and its steady fire suggests people are there. Vahlarriel Demonslayer at Nijel’s Point needs to see the pendant and hear what you found.",sp=0}},faq={{q="Where do I take the Malem Pendant?",a="Take the Malem Pendant to Vahlarriel Demonslayer at Nijel’s Point in Desolace.",al={"where to take pendant","pendant turn in","malem pendant where"}},{q="Where was the pendant found?",a="You find the Malem Pendant in a wagon in Desolace.",al={"where is pendant","pendant location","find malem pendant"}},{q="What clues were near the pendant?",a="Footprints lead south from the wagon, and smoke rises from a nearby fort.",al={"tracks and smoke","what clues","wagon clues"}},{q="Why does Vahlarriel need to hear about the fort?",a="Vahlarriel is searching for the Malems, and the tracks and smoke suggest they may have been taken toward the fort.",al={"why tell vahlarriel","fort news","what does vahlarriel need"},sp=1}},kw={"desolace","footprints","fort","malem","malem pendant","nijel's point","vahlarriel demonslayer","wagon"},rel={"quest:1437","zone:desolace","subzone:nijel-s-point","quest:1439","quest:1440"},src={"Wowpedia: Malem Pendant","Vahlarriel's Search (2)"}}
E["item:maraudine-key-fragment"] = {t="item",n="Maraudine Key Fragment",z="desolace",s="The Maraudine Key Fragment is held by Khan Hratha in Desolace. The Gelkis and Magram seek it in their struggle against the Maraudine.",h="The Maraudine Key Fragment is held by Khan Hratha in Desolace.",sec={{t="A Piece of a Key",b="Khan Hratha carries the Maraudine Key Fragment in the Valley of Spears. The Gelkis ask for it after he is slain, and the Magram make the same demand. Each clan seeks the fragment as part of its struggle against the Maraudine.",sp=0}},faq={{q="Who has the Maraudine Key Fragment?",a="Khan Hratha holds the Maraudine Key Fragment in the Valley of Spears.",al={"who has the fragment","hratha key piece","maraudine fragment"}},{q="Who wants the fragment?",a="Uthek the Wise asks for the fragment in Gelkis Village, while Warug asks for it in Magram Village.",al={"who wants the key","gelkis or magram","where take fragment"}},{q="Why do the Gelkis want it?",a="The Gelkis ask you to bring them the fragment after Khan Hratha is slain.",al={"gelkis want fragment","uthek key piece","why gelkis need key"},sp=1},{q="Why do the Magram want it?",a="The Magram ask you to bring the fragment after Khan Hratha is slain.",al={"magram want fragment","warug key piece","why magram need key"},sp=1}},kw={"gelkis","khan hratha","magram","maraudine","maraudine key fragment","uthek the wise","valley of spears","warug"},rel={"quest:1380","zone:desolace","subzone:gelkis-village","subzone:magram-village","subzone:valley-of-spears","topic:centaur"},src={"Wowpedia: Maraudine Key Fragment","Khan Hratha (Gelkis)","Khan Hratha (Magram)"}}
E["item:nether-wing"] = {t="item",n="Nether Wing",z="desolace",s="A Nether Wing is a demon’s wing sought by Reclaimers Inc. in Desolace. Kreldig Ungor needs ten for a mage’s experiments, alongside other dangerous reagents.",h="A Nether Wing is a demon’s wing sought by Reclaimers Inc.",sec={{t="A Demon's Wing",b="Nether Maidens, Nether Sorceresses, and Nether Sisters in Desolace bear the wings Kreldig Ungor seeks. He asks for ten as part of a collection of reagents for a mage’s experiments. The work also calls for Felhound Brains and vials of Doomwarder Blood, making this a perilous gathering.",sp=0}},faq={{q="Who wants Nether Wings?",a="Kreldig Ungor in Desolace seeks ten Nether Wings for a mage’s experiments.",al={"who needs nether wing","nether wings for who"}},{q="What are Nether Wings from?",a="Nether Wings come from Nether Maidens, Nether Sorceresses, and Nether Sisters in Desolace.",al={"where nether wing come from","nether wing source"}},{q="Why does Kreldig Ungor need them?",a="Kreldig Ungor gathers Nether Wings as reagents for a mage’s experiments.",al={"why nether wings","what are wings for"}},{q="What other reagents are needed?",a="The collection also requires Felhound Brains and vials of Doomwarder Blood.",al={"other reagents","what else does kreldig need"}}},kw={"desolace","kreldig ungor","nether maiden","nether sister","nether sorceress","nether wing","nether wings","reagents for reclaimers inc"},rel={"zone:desolace","npc:kreldig-ungor","quest:1458","item:felhound-brain","item:doomwarder-blood"},src={"Wowpedia: Nether Wing","Reagents for Reclaimers Inc. (3)"}}
E["item:oracle-crystal"] = {t="item",n="Oracle Crystal",z="desolace",s="The Oracle Crystal is a crafted naga object used by their oracles along Desolace’s coast. Maurin Bonesplitter seeks one as he turns his attention to a demon lord.",h="The Oracle Crystal is a crafted naga object used by their oracles along Desolace’s coast.",sec={{t="Naga Craft",b="Maurin Bonesplitter wants an Oracle Crystal from the Slitherblade naga along Desolace’s northwest coast. The naga craft these crystals for their oracles, who dwell among the vast coral reef offshore. Maurin prizes the crystal and means to use it as he searches for the demon lord Azrethoc.",sp=0}},faq={{q="What is an Oracle Crystal?",a="An Oracle Crystal is a crafted object the naga make for their oracles to use.",al={"oracle crystal","what's the crystal","naga crystal"}},{q="Who wants the Oracle Crystal?",a="Maurin Bonesplitter asks for an Oracle Crystal as he pursues the demon lord Azrethoc.",al={"who needs the crystal","Maurin crystal","bonesplitter wants"}},{q="Where can I find an Oracle Crystal?",a="Slitherblade oracles dwell along the northwest coast of Desolace, out in the sea.",al={"where crystal","oracle crystal location","find the naga crystal"}},{q="Who uses Oracle Crystals?",a="The naga craft Oracle Crystals for their oracles to use.",al={"who uses it","naga oracles","crystal purpose"}}},kw={"azrethoc","desolace","maurin bonesplitter","naga","oracle","oracle crystal","slitherblade"},rel={"zone:desolace","npc:maurin-bonesplitter","topic:naga","quest:1480"},src={"Wowpedia: Oracle Crystal","The Corrupter (3)"}}
E["item:rackmore-s-golden-key"] = {t="item",n="Rackmore's Golden Key",z="desolace",s="On Ranazjar Isle, Rackmore’s Golden Key helps open the chest where a sailor hid his treasure. The Slitherblade naga hold the key among the scattered remains of his voyage.",h="On Ranazjar Isle, Rackmore’s Golden Key helps open the chest where a sailor hid his treasure.",sec={{t="A Sailor’s Cache",b="Rackmore’s log tells how his ship was bound for Feathermoon Stronghold when seafaring creatures attacked. To keep his treasure from them, he hid a chest on Ranazjar Isle. It takes two keys to open: one silver and one gold. The Slitherblade naga hold the Golden Key, while Rackmore’s Silver Key must also be found.",sp=0}},faq={{q="What does Rackmore’s Golden Key open?",a="Rackmore’s Golden Key opens the chest hidden on Ranazjar Isle, together with Rackmore’s Silver Key.",al={"golden key","rackmore key","what's the gold key for"}},{q="Where is Rackmore’s treasure chest?",a="Rackmore hid his chest on Ranazjar Isle after seafaring creatures attacked his ship.",al={"rackmore chest location","where's the chest","ranazjar treasure"}},{q="Who has the Golden Key?",a="The Slitherblade naga in Desolace hold Rackmore’s Golden Key.",al={"who has rackmore's key","naga key","slitherblade key"}},{q="Why did Rackmore hide his treasure?",a="Rackmore hid the chest to keep his treasure from the seafaring creatures that attacked his ship.",al={"why hide the chest","rackmore treasure story","why is treasure hidden"}}},kw={"desolace","golden key","rackmore","rackmore's golden key","ranazjar isle","slitherblade naga","treasure"},rel={"quest:6161","item:rackmore-s-silver-key","zone:desolace","topic:naga"},src={"Wowpedia: Rackmore's Golden Key","Claim Rackmore's Treasure!"}}
E["item:rackmore-s-silver-key"] = {t="item",n="Rackmore's Silver Key",z="desolace",s="Rackmore’s Silver Key is lost among the makrura of Desolace. It is sought by those looking for Rackmore’s hidden treasure.",h="Rackmore’s Silver Key is lost among the makrura of Desolace.",sec={{t="The Lost Key",b="Rackmore’s log tells how his ship was bound for Feathermoon Stronghold when seafaring creatures attacked. To keep his treasure from enemy hands, he hid the chest on Ranazjar Isle. The silver key was lost, and the chest remains locked until it is found with its golden counterpart.",sp=0}},faq={{q="What does Rackmore’s Silver Key open?",a="Rackmore’s Silver Key is one of two keys needed to open Rackmore’s Chest on Ranazjar Isle. The golden key is the other.",al={"silver key purpose","what key open","rackmore key"}},{q="Where can I find Rackmore’s Silver Key?",a="Drysnap Pincers and Drysnap Crawlers in Desolace carry Rackmore’s Silver Key.",al={"silver key location","where key","find rackmore silver key"}},{q="Who was Rackmore?",a="Rackmore was the owner of a treasure chest hidden on Ranazjar Isle after his ship was attacked.",al={"rackmore backstory","who rackmore","rackmore"}},{q="Why is Rackmore’s treasure hidden?",a="Rackmore hid his chest on Ranazjar Isle to keep its treasure from falling into the hands of the creatures that attacked his ship.",al={"why chest hidden","rackmore treasure why","hidden treasure"}},{q="What happened to Rackmore’s ship?",a="Rackmore’s log says seafaring creatures attacked his ship while it was sailing for Feathermoon Stronghold.",al={"ship attacked","rackmore ship","what happened ship"}}},kw={"desolace","drysnap crawler","drysnap pincer","golden key","rackmore","rackmore's chest","rackmore's silver key","ranazjar isle","silver key"},rel={"quest:6161","item:rackmore-s-golden-key","zone:desolace","subzone:feathermoon-stronghold-classic"},src={"Wowpedia: Rackmore's Silver Key","Claim Rackmore's Treasure!"}}
E["item:rokaro-s-letter"] = {t="item",n="Rokaro's Letter",z="desolace",s="Rokaro’s Letter carries a request from Shadowprey Village to Myranda the Hag in the Western Plaguelands. Rokaro hopes her skill with disguise can help against the Black Dragonflight.",h="Rokaro’s Letter carries a request from Shadowprey Village to Myranda the Hag in the Western Plaguelands.",sec={{t="A Message to Myranda",b="At Shadowprey Village in Desolace, Rokaro sends you with a message for Myranda the Hag at Sorrow Hill. She is a former master illusionist of Lordaeron, and Rokaro believes her skill with disguise may help fool the Black Dragonflight. He asks you to bring the letter to her, so she can judge whether the cause deserves her aid.",sp=0},{t="What It Carries",b="When Myranda reads Rokaro’s Letter at Sorrow Hill, she finds it intentionally blank. The silence is its safeguard: if the bearer were captured or slain, no written plans could be found. Myranda recognizes Rokaro’s caution and agrees to help, remembering a favor she owes the Warchief.",sp=1}},faq={{q="Who wrote Rokaro’s Letter?",a="Rokaro sent the letter from Shadowprey Village in Desolace to Myranda the Hag.",al={"who sent the letter","rokaro note","letter from rokaro"}},{q="Where is the letter meant to go?",a="The letter is meant for Myranda the Hag at Sorrow Hill in the Western Plaguelands.",al={"where to take it","letter destination","myranda location"}},{q="Why does Rokaro need Myranda?",a="Rokaro seeks Myranda’s mastery of illusion and disguise to help fool the Black Dragonflight.",al={"why myranda","need illusionist","disguise help"}},{q="What does the letter say?",a="Rokaro’s Letter is intentionally blank, leaving no written plans to expose if its bearer is captured or slain.",al={"letter contents","is the note blank","what's written"},sp=1},{q="Why is the letter blank?",a="The blank letter protects its purpose by carrying no written information that enemies could discover.",al={"blank letter why","empty note","secret message"},sp=1},{q="Does Myranda agree to help?",a="Yes. Myranda agrees to help, citing a favor she owes the Warchief.",al={"will myranda help","myranda says yes","does she agree"},sp=1}},ang={["faction:Horde"]="As a member of the Horde, you carry Rokaro’s appeal to a former Lordaeron illusionist, seeking aid against the Black Dragonflight."},kw={"black dragonflight","desolace","disguise","illusion","myranda the hag","rokaro","rokaro's letter","shadowprey village","sorrow hill","western plaguelands"},rel={"zone:desolace","subzone:shadowprey-village","subzone:sorrow-hill","topic:black-dragonflight","topic:horde","topic:lordaeron"},src={"Wowpedia: Rokaro's Letter","Mistress of Deception"}}
E["item:roon-s-kodo-horn"] = {t="item",n="Roon's Kodo Horn",z="desolace",s="Roon’s Kodo Horn is a gift from a Tauren hunter in Desolace. It carries an invitation to Hemet Nesingwary Jr. in Stranglethorn, recalling the friendship between Roon and his father.",h="Roon’s Kodo Horn is a gift from a Tauren hunter in Desolace.",sec={{t="A Hunter's Gift",b="Hemet Nesingwary Jr. hunts in Stranglethorn, north of Grom'gol Base Camp. His father once hunted beside Roon Wildmane in Desolace, and the two set aside the enmity between their peoples. Roon gives you his kodo horn to carry to the younger Nesingwary. The gift bears a welcome from an old hunting companion.",sp=0}},faq={{q="Who is Roon?",a="Roon Wildmane is a Tauren hunter from Desolace who once hunted alongside Hemet Nesingwary.",al={"roon","roon wildmane","tauren hunter"}},{q="Why give Hemet Jr. the horn?",a="Roon sends the horn as a gift and a welcome to Hemet Nesingwary Jr., his old companion's son.",al={"why horn","roon's gift","horn for hemet"}},{q="Where can I find Hemet Jr.?",a="Hemet Nesingwary Jr. is in Stranglethorn, north of Grom'gol Base Camp.",al={"where's hemet","hemet location","hemet in stranglethorn"}},{q="Who was Hemet's father?",a="Hemet was the dwarf who hunted great beasts with Roon Wildmane in Desolace.",al={"hemet's dad","hemet sr","old hemet"}},{q="What does the horn mean to Roon?",a="The horn is Roon's gift to Hemet Nesingwary Jr. and carries Roon's welcome.",al={"horn meaning","why kodo horn","roon's kodo horn"}},{q="Did Roon and Hemet get along?",a="Yes. Roon says he and Hemet hunted together for many days and forgot the enmity between their peoples.",al={"roon and hemet","dwarf tauren friendship","were they friends"}}},ang={["race:Dwarf"]="As a dwarf, you carry a gift that recalls Hemet's friendship with Roon Wildmane, despite the enmity between their peoples.",["race:Tauren"]="As a Tauren, you may know the horn as Roon Wildmane's gift and welcome to Hemet Nesingwary Jr."},kw={"desolace","grom'gol base camp","hemet nesingwary","hemet nesingwary jr","kodo horn","roon","roon wildmane","roon's kodo horn","stranglethorn"},rel={"quest:5763","item:kodo-horn","zone:desolace","quest:5762","subzone:grom-gol-base-camp","topic:tauren","topic:dwarf"},src={"Wowpedia: Roon's Kodo Horn","Hunting in Stranglethorn"}}
E["item:sceptre-of-light"] = {t="item",n="Sceptre of Light",z="desolace",s="The Sceptre of Light is a relic said to sink cities beneath the sea. A Burning Blade seer holds it at Thunder Axe Fortress in Desolace.",h="The Sceptre of Light is a relic said to sink cities beneath the sea.",sec={{t="A Seer’s Prize",b="From a watchtower in Thunder Axe Fortress, a Burning Blade seer studies the Sceptre of Light. The Burning Blade is rumored to have taken it from the naga. Legends claim its power can sink entire cities beneath the sea, so Azore Aldamort at Ethel Rethor seeks its return.",sp=0}},faq={{q="What does the Sceptre of Light do?",a="Legend says the Sceptre of Light can sink entire cities beneath the sea.",al={"sceptre power","what can it do","light sceptre"}},{q="Who has the Sceptre of Light?",a="A Burning Blade seer studies the Sceptre of Light from a watchtower at Thunder Axe Fortress.",al={"who holds it","sceptre holder","burning blade sceptre"}},{q="Where is the Sceptre of Light?",a="The Sceptre of Light is held at Thunder Axe Fortress in Desolace.",al={"where's the sceptre","sceptre location","thunder axe sceptre"}},{q="Who wants the sceptre returned?",a="Azore Aldamort at the tower in Ethel Rethor wants the Sceptre of Light returned.",al={"who wants it","azore sceptre","ethel rethor"}},{q="Where did the Burning Blade get it?",a="The Burning Blade is rumored to have acquired the Sceptre of Light from the naga.",al={"naga sceptre","where from","sceptre origin"}}},kw={"azore aldamort","burning blade","desolace","ethel rethor","naga","sceptre of light","seer","thunder axe fortress"},rel={"quest:5741","subzone:thunder-axe-fortress","subzone:ethel-rethor","zone:desolace","topic:naga"},src={"Wowpedia: Sceptre of Light","Sceptre of Light (quest)"}}
E["item:scorpashi-venom"] = {t="item",n="Scorpashi Venom",z="desolace",s="Scorpashi venom is a reagent taken from the scorpions roaming Desolace. Kreldig Ungor needs it for a list of materials requested by Reclaimers Inc.",h="Scorpashi venom is a reagent taken from the scorpions roaming Desolace.",sec={{t="A Mage’s List",b="Kreldig Ungor is gathering materials in Desolace for Reclaimers Inc., following a list prepared by Leftwitch. Scorpashi venom is one of the items the mage requires, alongside hide from aged kodos. Kreldig is eager to finish the list and return to Ironforge.",sp=0}},faq={{q="What is Scorpashi venom used for?",a="Leftwitch requires Scorpashi venom for a list of materials gathered by Kreldig Ungor for Reclaimers Inc.",al={"scorpashi venom use","why collect venom","venom reagent"}},{q="Who needs the venom?",a="Kreldig Ungor is collecting the venom in Desolace for Reclaimers Inc., following Leftwitch’s list.",al={"who wants scorpashi venom","kreldig venom","who needs it"}},{q="Where does Scorpashi venom come from?",a="Scorpashi venom comes from the scorpions found throughout Desolace.",al={"where find venom","scorpashi location","venom source"}},{q="What other material is on Leftwitch’s list?",a="Kreldig also needs hides from aged kodos; Leftwitch’s directions specify aged kodos rather than dying or ancient ones.",al={"other reagent","what else does kreldig need","aged kodo hide"}}},ang={["class:Mage"]="Leftwitch’s list calls for Scorpashi venom, one of the stranger reagents a mage may seek."},kw={"aged kodo hide","desolace","kreldig ungor","leftwitch","reclaimers inc","scorpashi","scorpashi venom"},rel={"quest:1458","npc:kreldig-ungor","zone:desolace","item:aged-kodo-hide"},src={"Wowpedia: Scorpashi Venom","Reagents for Reclaimers Inc. (2)"}}
E["item:shadowstalker-scalp"] = {t="item",n="Shadowstalker Scalp",z="desolace",s="A Shadowstalker Scalp is a reagent taken from a Hatefury shadowstalker in Desolace. Maurin Bonesplitter needs it to break wards against scrying for a spell aimed at finding a demon lord.",h="A Shadowstalker Scalp is a reagent taken from a Hatefury shadowstalker in Desolace.",sec={{t="A Satyr's Scalp",b="Among the ancient ruins near Sargeron in northeastern Desolace, Hatefury shadowstalkers guard the scalp Maurin Bonesplitter seeks. He believes it can break a demon lord's wards against scrying. Bring him the right scalp; he warns that the wrong reagent could bring death to those who attempt the spell.",sp=0}},faq={{q="What is a Shadowstalker Scalp for?",a="Maurin Bonesplitter needs the scalp to break a demon lord's wards against scrying.",al={"shadowstalker scalp use","why scalp","scalp for maurin"}},{q="Where do I find a Shadowstalker Scalp?",a="Hatefury shadowstalkers near the ancient ruins of Sargeron in northeastern Desolace have the scalp Maurin seeks.",al={"shadowstalker scalp location","where scalp","sargeron scalp"}},{q="Who is Maurin Bonesplitter?",a="Maurin Bonesplitter is seeking reagents for a spell to find a demon lord.",al={"maurin bonesplitter scalp","who is maurin","maurin"}},{q="Why does Maurin need this particular scalp?",a="Maurin says the scalp must come from a Hatefury shadowstalker so he can break the demon lord's wards against scrying.",al={"why hatefury scalp","specific satyr scalp","wrong scalp"}}},ang={["faction:Horde"]="Maurin says you act in the Warchief's name as you gather reagents for his search."},kw={"demon lord","desolace","hatefury","maurin bonesplitter","sargeron","satyr","scrying","shadowstalker scalp"},rel={"zone:desolace","subzone:sargeron","npc:maurin-bonesplitter","topic:satyr","quest:1480"},src={"Wowpedia: Shadowstalker Scalp","The Corrupter (2)"}}
E["item:shellfish"] = {t="item",n="Shellfish",z="desolace",s="Shellfish are gathered from traps beneath the docks at Shadowprey Village. Jinar'Zillen wants them collected and offers Bloodbelly fish in return.",h="Shellfish are gathered from traps beneath the docks at Shadowprey Village.",sec={{t="Under the Docks",b="The waters west of Shadowprey Village hold shellfish traps beneath the docks. Jinar'Zillen asks you to collect five shellfish from them, so he can leave the work to someone else. In return, he offers a fine Bloodbelly fish.",sp=0}},faq={{q="Where do I find shellfish?",a="You can gather shellfish from traps in the waters west of Shadowprey Village, beneath its docks.",al={"shellfish location","where shellfish","shellfish traps"}},{q="Who wants the shellfish?",a="Jinar'Zillen at Shadowprey Village asks you to collect shellfish from the traps below the docks.",al={"who needs shellfish","jinar zillen shellfish","shellfish for who"}},{q="How many shellfish does Jinar'Zillen need?",a="Jinar'Zillen asks you to collect five shellfish.",al={"shellfish count","how many shells","five shellfish"}},{q="What does Jinar'Zillen offer for shellfish?",a="For every five shellfish you bring him, Jinar'Zillen offers a Bloodbelly fish.",al={"shellfish reward","bloodbelly fish","what for shellfish"}}},kw={"bloodbelly fish","desolace","docks","jinar'zillen","shadowprey village","shellfish","shellfish traps"},rel={"quest:5421","subzone:shadowprey-village","zone:desolace"},src={"Wowpedia: Shellfish","Fish in a Bucket"}}
E["item:soft-shelled-clam-meat"] = {t="item",n="Soft-Shelled Clam Meat",z="desolace",s="Soft-Shelled Clam Meat makes tempting bait for the fish near Shadowprey Village. Mai'Lahii asks you to bring him some from the wrecked ship to the north.",h="Soft-Shelled Clam Meat makes tempting bait for the fish near Shadowprey Village.",sec={{t="Bait for Mai'Lahii",b="Mai'Lahii at Shadowprey Village favors soft-shelled clam meat for fishing. He says the fish cannot resist it, and asks you to bring him ten pieces from the clams near the wrecked ship north of the village.",sp=0}},faq={{q="What is soft-shelled clam meat for?",a="Mai'Lahii at Shadowprey Village uses soft-shelled clam meat as bait for fishing.",al={"clam meat use","soft shell meat","clam bait"}},{q="Where can I find soft-shelled clams?",a="Soft-shelled clams lie near the wrecked ship off the coast north of Shadowprey Village.",al={"clam location","where clams","north ship clams"}},{q="Who wants the clam meat?",a="Mai'Lahii at Shadowprey Village asks you to bring him ten pieces of soft-shelled clam meat.",al={"clam meat for who","Mai'Lahii bait","who needs clams"}},{q="Why does Mai'Lahii want to go fishing?",a="Mai'Lahii says his witch doctor advised him to go fishing for his headache, and he feels better after you bring the clam meat.",al={"Mai'Lahii headache","why fishing","witch doctor advice"},sp=1}},kw={"clam bait","desolace","fishing","mai'lahii","shadowprey village","soft-shelled clam meat","wrecked ship"},rel={"quest:6142","subzone:shadowprey-village","zone:desolace"},src={"Wowpedia: Soft-Shelled Clam Meat","Clam Bait"}}
E["item:tyranis-pendant"] = {t="item",n="Tyranis' Pendant",z="desolace",s="Tyranis' Pendant is found at Thunder Axe Fortress in Desolace. It helps Vahlarriel learn what became of her brother, Tyranis Malem.",h="Tyranis' Pendant is found at Thunder Axe Fortress in Desolace.",sec={{t="A Brother's Trail",b="Vahlarriel waits at Thunder Axe Fortress, unable to leave before she knows what happened to Tyranis. The pendant is tied to that search. She fears her brother may be drawn to the Burning Blade's arcane secrets, a danger he has long been tempted by.",sp=0}},faq={{q="Where is Tyranis' Pendant?",a="Tyranis' Pendant is found in the left building at Thunder Axe Fortress in northern Desolace.",al={"pendant location","where pendant","find tyranis pendant"}},{q="Who is Tyranis Malem?",a="Tyranis Malem is Vahlarriel's brother, held at Thunder Axe Fortress in Desolace.",al={"tyranis who","tyranis backstory","who's tyranis"}},{q="Why does Vahlarriel want the pendant?",a="The pendant helps Vahlarriel learn what became of her brother, Tyranis.",al={"vahlarriel pendant","why pendant","what's it for"}},{q="What does Vahlarriel fear about Tyranis?",a="Vahlarriel fears Tyranis will try to learn the Burning Blade's secrets and be seduced by their magic.",al={"tyranis burning blade","why worried","tyranis danger"}}},kw={"burning blade","desolace","pendant","thunder axe fortress","tyranis malem","tyranis' pendant","vahlarriel"},rel={"quest:1439","quest:1440","quest:1437","subzone:thunder-axe-fortress","zone:desolace"},src={"Wowpedia: Tyranis' Pendant","Search for Tyranis"}}
E["npc:felgur-twocuts"] = {t="npc",n="Felgur Twocuts",z="desolace",s="At Ghost Walker Post, Felgur Twocuts watches the Horde’s struggle with Desolace’s centaur clans.",h="At Ghost Walker Post, Felgur Twocuts watches the Horde’s struggle with Desolace’s centaur clans.",sec={{t="A Gruff Outpost Scout",b="At Ghost Walker Post in central Desolace, Felgur Twocuts keeps watch and spares little for pleasantries. As a forward scout for the Horde, he weighs the dangers facing travelers and settlers heading west through the mountains. The Kolkar centaur are foremost among them.",sp=0},{t="War on the Centaur",b="Felgur directs Horde champions against the local centaur chieftains. He also sends them to claim bounties on tribes that threaten to overrun the region. Those seeking to secure the Horde’s foothold in Desolace can turn to him.",sp=0}},faq={{q="Who is Felgur Twocuts?",a="Felgur Twocuts scouts for the Horde from its forward encampment at Ghost Walker Post in Desolace.",al={"felgur twocuts who","who is felgur"},it="identity"},{q="Where can I find Felgur Twocuts?",a="Find Felgur Twocuts at Ghost Walker Post, just north of Desolace’s central road.",al={"felgur twocuts location","where is felgur","where is felgur twocuts"},gp=true},{q="What tasks does Felgur Twocuts give?",a="Felgur sends Horde adventurers after the local Kolkar centaur, Khan Dez'hepah, and hostile centaur with bounties on their heads.",al={"felgur quests","what does felgur want"},gp=true},{q="Why is Felgur so curt with visitors?",a="Desolace is a dangerous wasteland ringed by hostile centaur clans. At his isolated post, Felgur has little time for idle chatter and keeps his attention on survival and martial duty.",al={"why is felgur rude","make it quick felgur"}},{q="Whose side is Felgur Twocuts on?",a="Felgur is a proud member of the Horde, stationed far out on the frontier to advance their interests and defend their encampments against regional threats.",al={"felgur twocuts faction","is felgur horde","who does felgur serve"},it="side",add="f5a09a6e"},{q="What does Felgur Twocuts want?",a="Felgur seeks to curb the hostile centaur clans threatening the Horde in Desolace. He enlists capable champions to collect bounties and confront Khan Dez'hepah.",al={"felgur twocuts goal","what is felgur trying to do","what does felgur need"},it="wants",add="8c623583"},{q="Why is Felgur Twocuts stationed here?",a="Felgur is garrisoned at Ghost Walker Post to monitor the local centaur tribes and direct action against threats to the Horde's foothold in Desolace.",al={"why is felgur twocuts at ghost walker post","felgur purpose here","why is felgur out here"},it="why_here",add="a5d710fc"}},ang={["faction:Horde"]="As a member of the Horde, you can turn to Felgur at Ghost Walker Post for help driving back Desolace’s aggressive centaur tribes.",["race:Orc"]="As an orc, you may recognize Felgur’s practical focus in dangerous borderlands. He values strength, speed, and immediate results over idle conversation."},kw={"centaur bounty","desolace","felgur twocuts","ghost walker post","horde","kolkar","orc"},rel={"subzone:ghost-walker-post","zone:desolace","topic:centaur","quest:1362","topic:horde","zone:barrens"},src={"Felgur Twocuts"}}
E["npc:kreldig-ungor"] = {t="npc",n="Kreldig Ungor",z="desolace",s="At Nijel's Point, Kreldig Ungor directs Reclaimers Inc.'s work in dangerous Desolace. He hires Alliance adventurers to recover lost cargo and gather local reagents.",h="At Nijel's Point, Kreldig Ungor directs Reclaimers Inc.'s work in dangerous Desolace.",sec={{t="Field Agent in the Wastes",b="Kreldig works from Nijel's Point, an Alliance refuge among Desolace's blighted canyons. He represents Reclaimers Inc., far from Khaz Modan, where centaur clans, demons, and the Horde contest the wilderness. Others see ruin and ash. Kreldig sees lost goods and assets that can still be reclaimed for profit.",sp=0},{t="The Karnitol Contract",b="Kreldig seeks the lost vessel of Karnitol, wrecked along Desolace's treacherous western coast. Its shipment held prized goods. He directs the search for the wreck and the scattered cargo, before scavengers or coastal sea giants claim it.",sp=0},{t="Harvesting Local Reagents",b="Kreldig also oversees the gathering of Desolace's unusual biological and mineral resources for Reclaimers Inc. The harsh land breeds distinctive fauna and flora, whose parts bring high prices from alchemists and engineers in the Eastern Kingdoms. Adventurers who face the wasteland's predators can earn steady pay through his contracts.",sp=0}},faq={{q="Who is Kreldig Ungor?",a="Kreldig Ungor works for Reclaimers Inc. from Nijel's Point, the Alliance outpost in Desolace. He coordinates salvage and specimen gathering across the zone.",al={"kreldig ungor lore","who is kreldig","kreldig ungor"},it="identity"},{q="What is Reclaimers Inc.?",a="Reclaimers Inc. seeks profit by salvaging lost cargo, recovering wreckage, and gathering rare reagents in dangerous frontiers.",al={"reclaimers inc","who are reclaimers inc","reclaimers business"},it="ties"},{q="Where can Kreldig Ungor be found?",a="Kreldig works at Nijel's Point, high in the rocky mountains of northeastern Desolace.",al={"kreldig ungor location","where is kreldig","find kreldig ungor"},it="why_here",gp=true},{q="What does Kreldig want with the Karnitol shipwreck?",a="A vessel carrying Karnitol's valuable goods wrecked along the Desolace coast. Kreldig hires adventurers to find the wreck and recover its cargo before scavengers claim it or it is destroyed.",al={"karnitol shipwreck","kreldig karnitol","desolace shipwreck"},it="wants"},{q="Why is Kreldig collecting reagents in Desolace?",a="Desolace's harsh conditions foster rare creatures and unusual natural compounds. Kreldig gathers specimens for alchemists, artificers, and buyers in major Alliance cities.",al={"reagents for reclaimers inc","desolace reagents","why collect reagents"},it="motive"},{q="Does Kreldig work for Ironforge or a private enterprise?",a="Kreldig represents Reclaimers Inc., a commercial enterprise pursuing salvage and trade. Though based at an Alliance outpost, he hires Alliance wanderers for the company's work, not official royal military aims.",al={"kreldig alliance or private","reclaimers inc ironforge"},it="side"},{q="Why is Kreldig Ungor stationed at Nijel's Point?",a="Kreldig Ungor has set up shop high in Nijel's Point to pursue business ventures for Reclaimers Inc. across the rugged expanse of Desolace. From this fortified Alliance refuge, he oversees salvage and procurement operations in relative safety, using it as a base to hire hardy adventurers for ventures down in the perilous wastes.",al={"why is kreldig ungor here","kreldig ungor nijels point","why is kreldig in desolace"},it="why_here",add="ad7684ca"}},ang={["race:Dwarf"]="Kreldig carries a dwarven taste for rugged frontier exploration and commercial ambition. He works far from the mountain halls.",["faction:Alliance"]="At Nijel's Point, Kreldig relies on Alliance travelers to carry out his salvage contracts in hostile territory."},kw={"alliance","desolace","dwarf","karnitol shipwreck","kreldig ungor","nijel's point","reclaimers inc","salvage"},rel={"subzone:nijel-s-point","zone:desolace","quest:1453","topic:dwarf"},src={"Kreldig Ungor"}}
E["npc:maurin-bonesplitter"] = {t="npc",n="Maurin Bonesplitter",z="desolace",s="At Ghost Walker Post, Maurin Bonesplitter watches the Burning Blade in Desolace. Keldran sent the Forsaken scholar to watch the cult's demonic activity. Maurin draws on ancient lore to undermine the cult and scorns its members as fools blind to the dark powers directing them.",h="At Ghost Walker Post, Maurin Bonesplitter watches the Burning Blade in Desolace.",sec={{t="A Scholar Among Outcasts",b="At Ghost Walker Post, Maurin Bonesplitter is one of the few undead among the tauren and Horde residents. He is a learned spellcaster rather than a soldier, with deep knowledge of forbidden histories and occult forces. His learning and sharp mind caught Keldran's attention. So Keldran sent Maurin to Desolace to watch the growing demonic presence and direct focused attacks against it.",sp=0},{t="Contempt for the Burning Blade",b="Across Desolace, Maurin reserves much of his scorn for the Burning Blade. He despises their reckless ambition and mocks them for mistaking borrowed power for their own. To him, they are thralls blind to the demonic masters who bind them. Maurin uses scrying spells and ritual knowledge to enlist Horde adventurers in disrupting the cult's summonings and weakening its operations across the barren landscape.",sp=0}},faq={{q="Who is Maurin Bonesplitter?",a="Maurin Bonesplitter is a Forsaken warlock and scholar at Ghost Walker Post in Desolace. Keldran appointed him to turn his knowledge of ancient lore and dark magic against the Burning Blade cult in the region.",al={"maurin bonesplitter lore","who is maurin","maurin desolace"}},{q="Why is an undead staying at a tauren post?",a="Ghost Walker Post is a Horde settlement in Desolace. Keldran stationed Maurin there to watch and fight the Burning Blade cultists in the surrounding wilderness.",al={"why is maurin at ghost walker post","undead in desolace"}},{q="What is Maurin's opinion of the Burning Blade?",a="Maurin holds the Burning Blade in deep contempt. He sees its members as ignorant pawns who mistake borrowed power for their own and cannot see the demonic masters controlling them.",al={"maurin burning blade","why does maurin hate burning blade"}},{q="Who sent Maurin Bonesplitter to Desolace?",a="Keldran appointed Maurin to his post in Desolace. He recognized Maurin's knowledge of cult practices and ancient lore, then tasked him with hindering and eliminating the Burning Blade in the region.",al={"who sent maurin","maurin keldran","maurin boss"}},{q="What kind of tasks does Maurin give adventurers?",a="Maurin asks adventurers to investigate the Burning Blade and bring him a Hatefury Shadowstalker scalp and a naga Oracle Crystal. He uses these reagents to break scrying wards and find the demon lord behind the cult.",al={"maurin quests","what does maurin want"}},{q="Is Maurin affiliated with the Cenarion Circle or the Horde?",a="Maurin is a Forsaken loyal to the Horde. From Ghost Walker Post, he aids Horde champions fighting cult activity in the wastes.",al={"is maurin horde","maurin faction"}}},ang={["race:Undead"]="As Forsaken, you can see how arcane study and an enemy's weaknesses can serve alongside necromantic might.",["class:Warlock"]="As a warlock, you may recognize Maurin's grasp of demonic pacts. His contempt shows the peril of serving greater fiends.",["class:Mage"]="As a mage at Ghost Walker Post, you can appreciate Maurin's careful use of specialized counters to unravel dark rituals.",["faction:Horde"]="As a member of the Horde, you can see how Maurin brings Undercity's specialized support and dark scholarly knowledge to western outposts. There, he aids tauren allies against demonic corruption."},kw={"burning blade","corrupter","desolace","forsaken","ghost walker post","keldran","maurin bonesplitter"},rel={"subzone:ghost-walker-post","zone:desolace","npc:keldran","topic:forsaken","quest:1431"},src={"Maurin Bonesplitter"}}
E["npc:misha"] = {t="npc",n="Misha",z="desolace",s="Beside Rexxar, Misha roams Kalimdor as his loyal bear companion. Rexxar is the half-ogre beastmaster and Champion of the Horde, and she stays close as he travels.",h="Beside Rexxar, Misha roams Kalimdor as his loyal bear companion.",sec={{t="A Boundless Bond",b="Misha walks beside Rexxar, a solitary half-ogre who trusts beasts more than people. The brown bear and the wandering beastmaster have forged a fierce, protective bond through many wildernesses and bloody battles.",sp=0},{t="Defender of Durotar",b="Misha is a seasoned warrior, not merely a tame pet. She fought beside Rexxar against Grand Admiral Daelin Proudmoore at Theramore Isle, helping secure the young Horde's survival. Away from battle, her keen senses and strength extend Rexxar's will.",sp=0},{t="Wilds of Kalimdor",b="Travelers on the long tracks through the Stonetalon Mountains, Desolace, and Feralas may find Misha padding beside Rexxar. She is fierce enough to tear apart any predator that threatens them. In an untrustworthy world, she remains Rexxar's steadfast anchor.",sp=0}},faq={{q="Who is Misha?",a="Misha is Rexxar's lifelong companion, a ferocious brown bear who wanders the wilds beside the Champion of the Horde. They travel together across central Kalimdor.",al={"rexxars bear","who is the bear with rexxar","misha bear"}},{q="Where can Misha be found right now?",a="Misha walks beside Rexxar on the long tracks through the Stonetalon Mountains, Desolace, and Feralas.",al={"misha location","where is misha","find misha"}},{q="Did Misha take part in the founding of Durotar?",a="Yes. After the Third War, Misha joined Rexxar in battle against Grand Admiral Daelin Proudmoore's forces at Theramore Isle to defend the fledgling Horde.",al={"misha theramore","did misha fight daelin","misha third war"}},{q="Is Misha hostile to Alliance players?",a="Yes. Misha is the companion of the Champion of the Horde, and she fiercely defends Rexxar by attacking Alliance trespassers who draw too close.",al={"can alliance attack misha","is misha aggressive"}},{q="Why does Rexxar prefer beasts like Misha to people?",a="Disillusioned by the deceit and warfare of humanoid races, Rexxar chose solitude in the wilderness. He believes beasts are direct and honest, and finds in Misha a companion free of betrayal.",al={"why does rexxar keep beasts","rexxar bear companion"}}},ang={["class:Hunter"]="As a hunter, you can look to Misha as an ideal animal companion. Their lifelong partnership rests on mutual respect, not mere dominance.",["faction:Horde"]="As a member of the Horde, you can remember Misha's fight beside Rexxar to secure the fledgling Horde's freedom at Theramore Isle. Veterans across Durotar quietly respect her."},kw={"bear","beastmaster","desolace","feralas","misha","rexxar","stonetalon"},rel={"zone:desolace","zone:feralas","zone:stonetalon","subzone:theramore-isle","zone:orgrimmar","topic:horde","topic:third-war"},src={"Misha"}}
E["npc:taiga-wisemane"] = {t="npc",n="Taiga Wisemane",z="desolace",s="Along Desolace's western coast, Taiga Wisemane keeps watch. From Shadowprey Village, he looks for dark sorceries stirring across the wastes.",h="Along Desolace's western coast, Taiga Wisemane keeps watch.",sec={{t="A Watchful Eye in Shadowprey",b="Shadowprey Village is a Darkspear troll fishing settlement by the ocean. Taiga Wisemane has taken up station there to watch the dark sorceries stirring across Desolace. He knows spiritual corruption is seeping into the soil, and keeps his attention eastward. Shadow cults and demonic remnants fester among the ancient ruins.",sp=0},{t="Stemming the Demonic Tide",b="The Burning Blade works from Thunder Axe Fortress, where its cult experiments with dark artifacts to widen its influence. Taiga sees the danger to Desolace's inhabitants and sends capable adventurers into the fortress to claim the Demon Box, which holds the Hand of Iruxos.\n\nTaiga hopes this blow will deprive the cult of the focus it uses to tear the veil between worlds.",sp=1},{t="Sealing the Coven's Portals",b="Securing the Hand of Iruxos is only the first step in Taiga's plan. At Mannoroc Coven in southern Desolace, the Burning Blade has already opened demonic rifts.\n\nTaiga directs trusted champions to turn the dark focus against its makers. They channel its energy into the gateways, closing them before the Burning Legion can send reinforcements into Kalimdor's heart.",sp=1}},faq={{q="Who is Taiga Wisemane?",a="Taiga Wisemane is a tauren elder in Shadowprey Village on Desolace's western coast. He advises travelers and offers them work tracking and countering the Burning Blade's demonic rites.",al={"who is taiga","taiga wisemane lore","taiga shadowprey"}},{q="Why is a tauren living in Shadowprey Village?",a="Shadowprey Village is primarily a troll settlement and the Horde's main outpost along Desolace's coast. Taiga stays there to watch the wastes and enlist passing Horde travelers against nearby demonic threats.",al={"why is taiga in shadowprey","taiga troll village","tauren in troll town"}},{q="What is the Burning Blade doing in Desolace?",a="The Burning Blade is a cult whose shadow sorceries and demonic remnants trouble Desolace. Taiga watches for their spread from Shadowprey Village.",al={"burning blade desolace","what are the cultists doing","thunder axe fortress cultists"}},{q="What is the Hand of Iruxos?",a="The Hand of Iruxos is a demonic artifact held inside a Demon Box at Thunder Axe Fortress. The Burning Blade means to use its foul power to open portals to the Nether.",al={"hand of iruxos","what is demon box","demon box relic"}},{q="What happens at Mannoroc Coven?",a="Mannoroc Coven lies in southern Desolace, where demonic corruption has taken hold. Taiga watches for the threats spreading through the region.",al={"mannoroc coven portals","what is mannoroc coven","desolace portals"}},{q="Does Taiga belong to a specific tauren tribe?",a="Taiga carries the Wisemane surname and is an elder concerned with spiritual balance and demonic corruption. He serves the wider Horde under the banner of the united tribes.",al={"taiga tribe","wisemane tribe","is taiga bloodhoof"}}},ang={["faction:Horde"]="Taiga guides Horde champions traveling through Desolace. His counsel helps guard the Horde outpost at Shadowprey Village from demonic encroachment.",["race:Tauren"]="For tauren travelers, Taiga represents the duty to heal and protect Kalimdor from unnatural demonic blight. He stands against the dark legacy that has scarred Desolace.",["class:Warlock"]="Warlocks may note Taiga's understanding of the Hand of Iruxos. He uses the relic's resonance to collapse demonic portals instead of banishing them through holy rites."},kw={"burning blade","demon box","desolace","hand of iruxos","mannoroc coven","shadowprey village","taiga wisemane","thunder axe fortress"},rel={"subzone:shadowprey-village","zone:desolace","subzone:thunder-axe-fortress","subzone:mannoroc-coven","topic:tauren","topic:horde"},src={"Taiga Wisemane"}}
E["npc:takata-steelblade"] = {t="npc",n="Takata Steelblade",z="desolace",s="At Ghost Walker Post, Takata Steelblade leads the Horde's fight against demonic corruption in Desolace. Keldran sent him from Orgrimmar with Maurin Bonesplitter, and Takata now hunts satyrs allied with the Burning Blade.",h="At Ghost Walker Post, Takata Steelblade leads the Horde's fight against demonic corruption in Desolace.",sec={{t="Sent to Desolace",b="Keldran sent Takata Steelblade from Orgrimmar to Desolace to uncover and purge demonic subversion. Takata works from Ghost Walker Post, an isolated Tauren encampment. From there, he coordinates the fight against Legion-aligned forces in the wastes.",sp=0},{t="Scourge of the Satyrs",b="Maurin Bonesplitter tracks and attacks the Burning Blade cultists. Takata turns his forces against their demonic allies, the satyrs. His strikes have devastated Desolace's corrupted satyrs, aiming to break the cult's local power and stop its taint from spreading.",sp=0}},faq={{q="Who is Takata Steelblade?",a="Takata Steelblade is an orc warrior at Ghost Walker Post in Desolace. He directs the fight against demonic forces and satyrs allied with the Burning Blade.",al={"takata","takata lore","who is takata"},it="identity"},{q="Who sent Takata to Desolace?",a="Keldran sent Takata from Orgrimmar to fight the Burning Blade and its demonic allies in Desolace.",al={"who sent takata","keldran connection","takata orders"},it="ties"},{q="What is the relationship between Takata and Maurin Bonesplitter?",a="Keldran sent Takata and Maurin Bonesplitter together. Maurin targets the Burning Blade cultists, while Takata strikes their satyr allies.",al={"takata and maurin","maurin bonesplitter"}},{q="Why is Takata hunting satyrs?",a="Takata hunts the satyrs because they are allied with the Burning Blade. They spread demonic taint and threaten the Horde's foothold in Desolace.",al={"why kill satyrs","takata satyr","befouled by satyr"},it="wants"},{q="Where can Takata Steelblade be found?",a="Takata Steelblade is at Ghost Walker Post, a Horde camp in north-central Desolace.",al={"takata location","where is takata steelblade"},it="why_here",gp=true},{q="Whose side is Takata Steelblade on?",a="Takata Steelblade is loyal to the Horde and answers to Keldran in Orgrimmar. He works to secure the Horde's interests in Desolace by purging the demonic elements threatening Kalimdor, specifically targeting the wicked cults and demons aligned against his people.",al={"takata steelblade faction","takata loyalty","is takata horde"},it="side",add="a8c99361"},{q="Why is Takata Steelblade here?",a="Takata has taken up post at Ghost Walker Post on the orders of Keldran to lead the local offensive against demonic corruption. While his comrade Maurin Bonesplitter focuses strictly on the Burning Blade cult itself, Takata directs his wrath against the region's satyrs, waging a ruthless campaign to eliminate their presence entirely.",al={"why is takata in desolace","takata steelblade purpose","what is takata doing here"},it="why_here",add="683721f0"},{q="Why is Takata Steelblade famous or feared?",a="Takata is infamous among the foul inhabitants of Desolace for his devastating, systematic massacre of the local satyr population. He has earned a fearsome reputation by aggressively cutting down every satyr affiliated with the Burning Blade across the desolate wastes.",al={"takata reputation","why is takata feared","takata fame"},it="fame",add="a7138bd5"}},ang={["faction:Horde"]="As a member of the Horde, you can find Takata coordinating its defense from Ghost Walker Post. He fights demonic infiltrators in Desolace.",["race:Orc"]="As an orc, you can see Takata carrying out orders from Orgrimmor's leadership to root out demonic servitude.",["class:Warrior"]="As a warrior, you can see Takata rely on decisive force to strike down demonic infiltrators."},kw={"bonesplitter","burning blade","desolace","ghost walker post","keldran","maurin","satyr","steelblade","takata"},rel={"subzone:ghost-walker-post","zone:desolace","npc:keldran","npc:maurin-bonesplitter","topic:satyr","quest:1431"},src={"Takata Steelblade"}}
E["quest:1052"] = {t="quest",n="Down the Scarlet Path",z="desolace",s="Brother Anton sends you from Desolace to Southshore with a sealed letter for Raleigh the Devout. Your deeds against the undead are only the beginning; Lordaeron holds the plague's true danger.",h="Brother Anton sends you from Desolace to Southshore with a sealed letter for Raleigh the Devout.",sec={{t="Strongholds of the Crusade",b="Brother Anton takes pride in the Scarlet Crusade's strongholds in Lordaeron. The Crusade claims cleansing bastions from Hearthglen to Tirisfal Glades. Your work against the undead in Desolace has proven you, Anton says. Yet the plague's true danger lies in Lordaeron.",sp=0},{t="A Letter for Southshore",b="Brother Anton sends you to Southshore, a town in the Eastern Kingdoms, to find Raleigh the Devout, a crusader. Anton seals a letter with his mark. He says Raleigh will give you an escort to a place of honor within the Scarlet Monastery.",sp=0},{t="Raleigh's Reaction",b="Raleigh breaks the seal and reads Brother Anton's letter. The news that Anton still spreads word of the Scarlet Crusade troubles Raleigh. He tells you that something here is beyond your understanding.",sp=1}},faq={{q="Who sends you on this journey?",a="Brother Anton gives you a sealed letter of commendation for Raleigh the Devout.",al={"who gives down the scarlet path","quest giver down the scarlet path"}},{q="Where are you being sent?",a="Brother Anton sends you to Southshore, in the Eastern Kingdoms, to find Raleigh the Devout, a crusader.",al={"where to go","where is raleigh","down the scarlet path location"}},{q="What does Brother Anton say the letter will do?",a="Anton says Raleigh will escort you to a place of honor within the Scarlet Monastery after reading his sealed letter.",al={"what does the letter do","letter of commendation purpose"}},{q="What territory does the Scarlet Crusade claim in Lordaeron?",a="Brother Anton says the Scarlet Crusade claims strongholds from Hearthglen to Tirisfal Glades, cleansing bastions he takes pride in.",al={"scarlet crusade lands","where are scarlet crusade strongholds"}}},kw={"brother anton","down the scarlet path","hearthglen","letter of commendation","lordaeron","raleigh the devout","scarlet monastery","southshore","tirisfal glades"},rel={"quest:261","quest:6141","topic:scarlet-crusade","subzone:southshore","zone:scarlet","topic:lordaeron","subzone:hearthglen","zone:tirisfal"},m={start="Brother Anton",["end"]="Raleigh the Devout",level="40",faction="Alliance",id=1052},src={"Down the Scarlet Path (2)"}}
E["quest:1365"] = {t="quest",n="Khan Dez'hepah",z="desolace",s="After The Kolkar of Desolace, Felgur Twocuts turns against Khan Dez'hepah. Many centaur clans fight across Desolace, and Felgur wants the Kolkar weakened before they unite.",h="After The Kolkar of Desolace, Felgur Twocuts turns against Khan Dez'hepah.",sec={{t="Divided Clans",b="Across Desolace, centaur clans fight one another. The Kolkar are one of many, roaming the dry plains and killing their own. Felgur Twocuts does not mourn their losses. Centaur are strong and brutal, and united they would be a fierce foe for the Horde. Felgur wants the Kolkar weakened before that can happen.",sp=0},{t="The Kolkar Leader",b="Felgur Twocuts begins by disrupting the Kolkar. Their village lies northeast of where Felgur stands. Felgur wants Khan Dez'hepah's head brought back.",sp=0}},faq={{q="Why does Felgur Twocuts want Khan Dez'hepah dead?",a="Felgur Twocuts fears the centaur clans may unite against the Horde. Felgur means to disrupt the Kolkar first by killing Khan Dez'hepah.",al={"why kill dezhepah","khan dezhepah purpose","reason for killing dezhepah"}},{q="Where is Khan Dez'hepah located?",a="Khan Dez'hepah is in the Kolkar Village, northeast of Felgur Twocuts in Desolace.",al={"khan dezhepah location","where is dezhepah","kolkar village location"}},{q="What does Felgur want brought back?",a="Felgur Twocuts wants Khan Dez'hepah's head brought back.",al={"khan dezhepah proof","what to bring felgur"}},{q="What comes before Khan Dez'hepah?",a="The Kolkar of Desolace comes first. Afterward, Felgur Twocuts sends you against the Kolkar leader, Khan Dez'hepah.",al={"previous quest dezhepah","prerequisite for khan dezhepah"}}},kw={"centaur","desolace","dez'hepah","felgur twocuts","khan dez'hepah","kolkar","kolkar village"},rel={"npc:felgur-twocuts","topic:kolkar-clan","topic:centaur","quest:1362","zone:desolace"},m={start="Felgur Twocuts",["end"]="Felgur Twocuts",level="35",faction="Horde",id=1365,ri={"Khan Dez'hepah's Head"}},src={"Khan Dez'hepah (quest)"}}
E["quest:1366"] = {t="quest",n="Centaur Bounty",z="desolace",s="In Desolace, Felgur Twocuts calls for blood after Khan Dez'hepah. He wants fifteen ears from centaur of any clan.",h="In Desolace, Felgur Twocuts calls for blood after Khan Dez'hepah.",sec={{t="Time to Bleed Them",b="Felgur Twocuts says the centaur clans have been scared. Now, he says, it is time to bleed them. As you travel across Desolace, hunt centaur from any clan and gather fifteen ears. Felgur wants to thin their numbers and weaken their resolve. He means to end any thoughts of expansion.",sp=0},{t="Felgur's Verdict",b="When you return, Felgur says the centaur must know your name by now. He believes they respect and fear you. They know the banner you ride under as well: the Horde's.",sp=1}},faq={{q="Who orders this bounty on the centaur?",a="Felgur Twocuts orders the bounty in Desolace. He wants fifteen centaur ears brought back to him.",al={"who gives centaur bounty","centaur bounty questgiver"}},{q="Which centaur clans need to be hunted?",a="You can hunt centaur from any clan. Felgur asks only that you gather ears.",al={"which centaur do i kill","what clan for centaur bounty"}},{q="Why does Felgur want so many centaur ears?",a="Felgur wants to weaken the centaur numbers. He believes fewer centaur will weaken their resolve and end any thoughts of expansion.",al={"why kill centaur desolace","reason for centaur bounty"}},{q="What came before this bounty?",a="The bounty follows Khan Dez'hepah. Felgur says the centaur clans have been scared, and now it is time to bleed them.",al={"centaur bounty prereq","previous quest centaur bounty"}}},kw={"centaur","centaur bounty","centaur ears","desolace","felgur twocuts","khan dez'hepah"},rel={"npc:felgur-twocuts","zone:desolace","topic:centaur","topic:horde"},m={start="Felgur Twocuts",["end"]="Felgur Twocuts",level="31",faction="Horde",id=1366,ri={"Centaur Ear"}},src={"Centaur Bounty (Horde)"}}
E["quest:1367"] = {t="quest",n="Magram Alliance",z="desolace",s="In Desolace, Gurda Wildmane urges you to turn the centaur clans' hatred against them. Befriend one clan to learn how all can be beaten. If you side with the Magram, slay the Gelkis, then speak with Warug at the edge of Magram Village in southeast Desolace.",h="In Desolace, Gurda Wildmane urges you to turn the centaur clans' hatred against them.",sec={{t="Hatred as a Weapon",b="Gurda Wildmane urges you to turn the centaur clans' hatred against them. Choose one clan as an ally and learn from it how all can be beaten. If you side with the Magram, slaying their foes, the Gelkis, earns their respect.",sp=0},{t="The Spokesman",b="Warug, the Magram spokesman, waits on the outskirts of Magram Village in southeast Desolace once you have earned enough respect. Before then, he has nothing to say to you. The Magram have no words for the weak. They kill them instead. To prove your strength, Warug sends you to face many Gelkis.",sp=0},{t="Warug's Judgment",b="Warug says the Gelkis weep at the sound of your name. They fear and hate you as they do the Magram. Perhaps, he allows, you are as strong as the Magram. He will judge for himself.",sp=1}},faq={{q="Who proposes an alliance with the Magram?",a="Gurda Wildmane urges you to turn the centaur clans' hatred against them. Side with one clan and learn how all can be beaten.",al={"who gives magram alliance","magram quest giver","gurda wildmane quest"}},{q="How do you earn the respect of the Magram?",a="Slay the Gelkis, the Magram's foes, to earn their respect.",al={"how to get friendly with magram","magram reputation","make magram friendly"}},{q="Where is Warug?",a="Warug, the Magram spokesman, waits on the outskirts of Magram Village in southeast Desolace.",al={"where is warug","find warug","warug location"}},{q="Why does Warug refuse to speak at first?",a="Warug says the Magram have no words for the weak and kill them instead. Prove your strength by slaying many Gelkis.",al={"why won't warug talk","warug angry","warug dialogue"}}},kw={"centaur","desolace","gelkis","gurda wildmane","magram","magram village","warug"},rel={"zone:desolace","subzone:magram-village","topic:centaur"},m={start="Gurda Wildmane",["end"]="Warug",level="33",faction="Horde",id=1367},src={"Magram Alliance"}}
E["quest:1368"] = {t="quest",n="Gelkis Alliance",z="desolace",s="In southwest Desolace, Gurda Wildmane turns the centaur clans' hatred toward their defeat. Befriend one clan to learn how the others may be beaten. The Gelkis demand that you kill their hated enemies, the Magram, before you meet Uthek the Wise at Gelkis Village.",h="In southwest Desolace, Gurda Wildmane turns the centaur clans' hatred toward their defeat.",sec={{t="Hatred as a Weapon",b="Gurda Wildmane means to turn the centaur clans' hatred against them. Befriend one clan, and what you learn may show how to defeat them all. Choose the Gelkis. To earn their respect, kill the Magram, the clan they hate most.",sp=0},{t="The Shaman",b="Once the Gelkis respect you, meet Uthek the Wise, their shaman, on the outskirts of Gelkis Village in southwest Desolace. Until then, you are not welcome there. Uthek says you tread on Gelkis earth. Prove your friendship by killing Magram centaur, then return when their blood has soaked the ground.",sp=0},{t="Uthek's Word",b="Uthek the Wise says the earth tells how many Magram you have killed. He says this is good. As a friend of the Gelkis, you may take on more work from Uthek.",sp=1}},faq={{q="Who proposes an alliance with the Gelkis?",a="Gurda Wildmane proposes turning the centaur clans' hatred against them. Ally with one clan, and you can learn how to defeat them all.",al={"who gives gelkis alliance","gelkis alliance quest giver"}},{q="How do you earn the favor of the Gelkis?",a="Kill the Magram, the clan the Gelkis hate most, to earn their favor.",al={"how to get friendly with gelkis","gelkis rep"}},{q="Who do you speak to among the Gelkis?",a="Speak to Uthek the Wise, a Gelkis shaman, on the outskirts of Gelkis Village in southwest Desolace.",al={"where is uthek","uthek the wise location"}},{q="What does Uthek require before welcoming you?",a="Uthek says you are not welcome on Gelkis earth until you prove your friendship by killing Magram centaur.",al={"why does uthek reject me","gelkis village hostile"}}},kw={"centaur","desolace","gelkis","gelkis village","gurda wildmane","magram","uthek the wise"},rel={"subzone:gelkis-village","topic:centaur","zone:desolace","quest:1370"},m={start="Gurda Wildmane",["end"]="Uthek the Wise",level="33",faction="Horde",id=1368},src={"Gelkis Alliance"}}
E["quest:1369"] = {t="quest",n="Broken Tears",z="desolace",s="In the Gelkis village cave, Warug wants you to break the crystals they call the tears of Theradras. He asks for three broken pieces, claiming the centaur mother cannot protect them.",h="In the Gelkis village cave, Warug wants you to break the crystals they call the tears of Theradras.",sec={{t="Crystals in the Cave",b="Warug mocks the Gelkis for trusting Theradras, mother of the centaur, to protect them. He says no one protects the centaur, while the Magram are strongest and need no protection. In a cave in the Gelkis village, the Gelkis hoard crystals called the tears of Theradras. Warug sends you to smash them and bring him three broken pieces. He trusts you with this only if you are no enemy of the Magram.",sp=0},{t="Warug's Boast",b="Warug welcomes the broken crystals. He says the Gelkis will learn Theradras cannot help them, and no tears of hers will fall when the Magram crush them. The Magram will rule, he declares. You are wise to side with the strongest.",sp=1}},faq={{q="Who is Warug?",a="Warug is a Magram centaur in Magram Village in Desolace. He asks you to destroy the tears of Theradras in the Gelkis cave.",al={"warug","who gives broken tears","broken tears quest giver"}},{q="What are the tears of Theradras?",a="The tears of Theradras are crystals the Gelkis hoard in a cave in their village.",al={"tears of theradras","broken tears lore","gelkis crystals"}},{q="Why does Warug want the tears destroyed?",a="The Gelkis believe Theradras, the centaur mother, protects them. Warug calls them foolish and says the Magram need no protection. He wants to show the Gelkis they are wrong.",al={"why destroy the tears","magram motive","why break crystals"}},{q="Where are the crystals found?",a="The crystals are in a cave in the Gelkis village. Warug asks you to bring him three broken pieces.",al={"where are broken tears","gelkis cave location","where are the tears"}}},kw={"broken tears","centaur","desolace","gelkis","magram","theradras","warug"},rel={"subzone:magram-village","topic:centaur","quest:1371","zone:desolace"},m={start="Warug",["end"]="Warug",level="33",id=1369,ri={"Broken Tears"}},src={"Broken Tears (quest)"}}
E["quest:1370"] = {t="quest",n="Stealing Supplies",z="desolace",s="In Desolace, Uthek the Wise sends you east after the Magram’s stores. The Gelkis believe meat gives them strength, while the Magram keep supplies for the days between hunts.",h="In Desolace, Uthek the Wise sends you east after the Magram’s stores.",sec={{t="Meat and Strength",b="Uthek the Wise says the Gelkis draw strength from meat. A full belly fights harder than an empty one. The Magram keep extra stores for the days between hunts. So you are sent to their village to the east for six bags of crudely dried meat, to bring back to Uthek at the Gelkis Village.",sp=0}},faq={{q="Who sends you to take these supplies?",a="Uthek the Wise of the Gelkis sends you from Desolace.",al={"quest giver","who gives stealing supplies","uthek the wise"}},{q="Why does Uthek want the Magram meat taken?",a="The Gelkis believe meat gives them strength. Uthek says taking the Magram’s reserve would weaken them as they fight between hunts.",al={"why steal meat","magram food","reason for meat raid"}},{q="Where are the Magram supplies kept?",a="The Magram keep their supplies in their village to the east.",al={"where is magram village","where are supplies","magram location"}},{q="How much meat does Uthek want?",a="Uthek the Wise wants six bags of crudely dried meat, brought to her at the Gelkis Village.",al={"how much meat","what do i bring uthek"}}},kw={"centaur","desolace","gelkis","magram","meat","supplies","uthek"},rel={"subzone:gelkis-village","zone:desolace","topic:centaur","quest:1382"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="35",id=1370,ri={"Crudely Dried Meat"}},src={"Stealing Supplies"}}
E["quest:1371"] = {t="quest",n="Gizmo for Warug",z="desolace",s="In Magram Village, Warug now wants a new target dummy to replace the wooden human he broke.",h="In Magram Village, Warug now wants a new target dummy to replace the wooden human he broke.",sec={{t="The Gnome's Cart",b="Warug remembers a gnome who came to Desolace long ago with horses and a cart. Inside were curious things: some burned in different colors, while others moved though they were not alive. Warug killed the gnome, but not before the gnome made him laugh.\n\nWarug kept his favorite thing from the cart, a wooden human that waved at him. He hit it and broke it. Now he wants an advanced target dummy to take its place, and expects one from anyone who is no enemy of the Magram.",sp=0}},faq={{q="Who is Warug?",a="Warug is a Magram centaur in Magram Village. He expects those he deals with to remain in the Magram's good standing.",al={"warug","who gives gizmo for warug"}},{q="What does Warug want?",a="Warug wants an advanced target dummy to replace the wooden human from the gnome's cart that he broke.",al={"what item does warug need","warug gizmo item"}},{q="Why does Warug want a target dummy?",a="Long ago, Warug killed a gnome who came to Desolace with a cart of strange, funny things. The gnome made him laugh, and Warug's favorite was a wooden human that waved at him. Warug hit it and broke it, so now he wants a new one.",al={"why does warug want a dummy","warug dummy reason"}},{q="What comes before this in the Magram story?",a="Broken Tears comes before this in your dealings with the Magram.",al={"gizmo for warug chain","what comes before gizmo for warug"}}},kw={"centaur","desolace","gnome","magram","target dummy","warug"},rel={"subzone:magram-village","zone:desolace","topic:centaur","topic:gnome","topic:human"},m={start="Warug",["end"]="Warug",level="35",id=1371},src={"Gizmo for Warug"}}
E["quest:1373"] = {t="quest",n="Ongeku",z="desolace",s="Uthek sends you from Desolace to find a shard of draenethyst. The earth has whispered of the red crystal to him, and Ongeku holds a shard in the Swamp of Sorrows.",h="Uthek sends you from Desolace to find a shard of draenethyst.",sec={{t="A Crystal from Far Away",b="After Stealing Supplies, Uthek the Wise sends you far from Desolace for a red crystal called draenethyst. He says the earth shares its secrets with those who listen. The crystal has only recently come to this land, carried from a place of flying mountains ruled by demons.\n\nUthek says a shard will make the magic strong. Ongeku, the lost one, holds one in the Swamp of Sorrows in the Eastern Kingdoms. When you return, Uthek will seek proof that the Gelkis can still call you friend.",sp=0}},faq={{q="Who is Uthek the Wise?",a="Uthek the Wise is a Gelkis centaur at Gelkis Village in Desolace. Uthek says the earth whispers its secrets to those who listen.",al={"uthek","gelkis elder","centaur quest giver"}},{q="What is draenethyst?",a="Draenethyst is a red crystal that Uthek says has only recently come to this land. Uthek says it comes from a place of flying mountains ruled by demons.",al={"draenethyst shard","red crystal","what is draenethyst"}},{q="Who is Ongeku?",a="Ongeku is a Lost One who holds a draenethyst shard in the central Swamp of Sorrows in the Eastern Kingdoms.",al={"where is ongeku","ongeku location","find ongeku"}},{q="Why does Uthek want a draenethyst shard?",a="Uthek says a draenethyst shard will make the magic strong.",al={"why get draenethyst","uthek magic"}},{q="What came before this?",a="Stealing Supplies came before this. Uthek gave it to you earlier.",al={"previous quest","prerequisite"}}},kw={"desolace","draenethyst","gelkis","lost one","magram","ongeku","swamp of sorrows","uthek the wise"},rel={"subzone:gelkis-village","quest:1370","zone:desolace","zone:swampofsorrows","topic:centaur"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="37",id=1373,ri={"Draenethyst Shard"}},src={"Ongeku (quest)"}}
E["quest:1374"] = {t="quest",n="Khan Jehn",z="desolace",s="At Gelkis Village, Uthek the Wise says Khan Jehn must fall as the Magram grow weak. He asks you to bring the Khan's head back.",h="At Gelkis Village, Uthek the Wise says Khan Jehn must fall as the Magram grow weak.",sec={{t="The Magram Khan",b="At Gelkis Village, Uthek the Wise listens to what the earth tells him. The Magram are growing weak, and their Khan, Jehn, is the one to strike down. Uthek asks you to bring back the Magram Khan's head. He expects you to return as a friend of the Gelkis.",sp=0}},faq={{q="Who is Khan Jehn?",a="Khan Jehn leads the Magram centaur.",al={"khan jehn","who is jehn","magram leader"}},{q="Why does Uthek the Wise want Khan Jehn dead?",a="Uthek says the earth tells her the Magram are growing weak. So she believes the time has come to kill their Khan.",al={"why kill jehn","uthek motivation","why kill magram khan"}},{q="What came before this?",a="This follows Ongeku.",al={"what comes before khan jehn","chain order","previous quest"}},{q="Where is Uthek the Wise?",a="Uthek the Wise is at Gelkis Village in Desolace.",al={"uthek location","where is uthek"}}},kw={"centaur","desolace","gelkis","gelkis village","head of jehn","khan jehn","magram","uthek the wise"},rel={"subzone:gelkis-village","zone:desolace","topic:centaur","quest:1373","quest:1380"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="37",id=1374,ri={"Khan Jehn's Head"}},src={"Khan Jehn (quest)"}}
E["quest:1375"] = {t="quest",n="Khan Shaka",z="desolace",s="Warug of the Magram now sends you after Khan Shaka, the Gelkis Khan. Bring him Shaka’s head so he can stare at it and laugh at his enemy.",h="Warug of the Magram now sends you after Khan Shaka, the Gelkis Khan.",sec={{t="A Rival Khan",b="In Magram Village, Warug says your help has pleased him and served the Magram well. Now he wants Khan Shaka, the Gelkis Khan, killed, and his head brought back. Warug means to stare at it and laugh at his enemy. He expects you to stay on good terms with the Magram.",sp=0}},faq={{q="Who is Khan Shaka?",a="Khan Shaka leads the Gelkis centaur clan in Desolace. Warug of the Magram wants his head.",al={"khan shaka lore","who is shaka","shaka centaur"}},{q="Why does Warug want Khan Shaka dead?",a="Warug wants Khan Shaka’s head so he can stare at it and laugh at his enemy.",al={"why kill shaka","warug shaka grudge"}},{q="Where is Warug?",a="Warug is in Magram Village in Desolace.",al={"khan shaka location","where is warug"}},{q="What led up to this?",a="After Gizmo for Warug, Warug says he likes you for helping the Magram.",al={"khan shaka prerequisites","previous quest shaka"}}},kw={"centaur","desolace","gelkis","head of khan shaka","khan shaka","magram","warug"},rel={"zone:desolace","subzone:magram-village","topic:centaur","quest:1371"},m={start="Warug",["end"]="Warug",level="37",id=1375,ri={"Khan Shaka's Head"}},src={"Khan Shaka (quest)"}}
E["quest:1380"] = {t="quest",n="Khan Hratha",z="desolace",s="At Gelkis Village, Uthek the Wise sends you against the Maraudine after your help against the Magram. Their leader, Khan Hratha, carries a piece of a key Uthek wants returned to him.",h="At Gelkis Village, Uthek the Wise sends you against the Maraudine after your help against the Magram.",sec={{t="Challenging the Maraudine",b="The Gelkis need your help against the Maraudine, Uthek the Wise tells you. Their War Horn stands on a tall bluff in the Valley of Spears. Sound it, and Khan Hratha will answer. But first, you need a warhorn mouthpiece. Only trusted Maraudine centaur carry one, and they are rare. More centaur arrive when the horn sounds. Hratha comes last.",sp=0},{t="A Piece of a Key",b="Khan Hratha holds a piece of a key. Uthek wants you to bring it to Gelkis Village.",sp=0},{t="On Your Return",b="When you return, Uthek exults that Khan Hratha is dead and the Maraudine are doomed. He vows the Gelkis will remember you when they rule this land. The earth's spirits, he says, will sing your name forever.",sp=1}},faq={{q="Who sends you to fight Khan Hratha?",a="Uthek the Wise sends you to fight Khan Hratha from Gelkis Village, after you have helped the Gelkis against the Magram.",al={"who gives khan hratha","khan hratha quest giver","where to get khan hratha"}},{q="How is Khan Hratha brought out to fight?",a="Sound the Maraudine War Horn on a tall bluff in the Valley of Spears. Centaur answer first, and Khan Hratha follows.",al={"khan hratha location","where is khan hratha","find khan hratha"}},{q="How do you blow the Maraudine War Horn?",a="The horn needs a warhorn mouthpiece, rare and carried only by trusted Maraudine centaur.",al={"warhorn mouthpiece","how to use maraudine war horn","blow maraudine war horn"}},{q="What comes before this?",a="This follows Khan Jehn. Uthek reminds you that you helped the Gelkis against the Magram.",al={"khan hratha prerequisites","what quest before khan hratha","khan hratha chain"}},{q="What does Khan Hratha hold?",a="Khan Hratha holds a piece of a key. Uthek asks you to bring it to her in Gelkis Village.",al={"khan hratha item","maraudine key fragment","what does hratha drop"}}},kw={"centaur","desolace","gelkis village","khan hratha","maraudine","maraudine war horn","uthek the wise","valley of spears"},rel={"subzone:gelkis-village","subzone:valley-of-spears","topic:centaur","zone:desolace"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="42",id=1380,ri={"Maraudine Key Fragment"}},src={"Khan Hratha (Gelkis)"}}
E["quest:1381"] = {t="quest",n="Khan Hratha",z="desolace",s="In Desolace, Warug sets his sights on Khan Hratha after the Gelkis Khan's death. He sends you to face the Maraudine Khan and return with the piece of a key he carries.",h="In Desolace, Warug sets his sights on Khan Hratha after the Gelkis Khan's death.",sec={{t="A Horn on the Bluff",b="Warug wants Khan Hratha, the Maraudine Khan, dead. A horn on a bluff in the Valley of Spears will draw him out, but first you need its mouthpiece from a Maraudine centaur. Sound the horn and Maraudine centaur gather at the tower. Hratha appears after them.",sp=0},{t="A Piece of a Key",b="Khan Hratha carries part of a key, and Warug wants you to bring it to him in Magram Village. He expects you to prove yourself an ally of the Magram.",sp=0},{t="Masters of the Centaur",b="With Khan Hratha dead, Warug declares the Magram the mightiest of the centaur. He says they are destined to crush their rivals and rule Desolace. Warug promises you will be remembered and spared when the rest are trampled.",sp=1}},faq={{q="Who sends you to defeat Khan Hratha?",a="Warug sends you from Magram Village in Desolace after the Gelkis Khan's death.",al={"who gives khan hratha","khan hratha quest giver"}},{q="How do you reach Khan Hratha?",a="To face Hratha, sound the horn on the bluff in the Valley of Spears. First, take its mouthpiece from a Maraudine centaur. The centaur gather at the tower, and Hratha appears after them.",al={"how to summon hratha","find khan hratha","blow horn valley of spears"}},{q="Where does Khan Hratha appear?",a="Hratha appears at the tower in the Valley of Spears after the horn sounds and the Maraudine centaur gather there.",al={"khan hratha location","where is hratha"}},{q="What does Khan Hratha hold?",a="Hratha carries part of a key, which Warug asks you to bring to him.",al={"what does hratha drop","maraudine key fragment"}}},kw={"desolace","key fragment","khan hratha","magram","maraudine","valley of spears","war horn","warug"},rel={"subzone:magram-village","subzone:valley-of-spears","zone:desolace","topic:centaur","quest:1375"},m={start="Warug",["end"]="Warug",level="42",id=1381,ri={"Maraudine Key Fragment"}},src={"Khan Hratha (Magram)"}}
E["quest:1382"] = {t="quest",n="Strange Alliance",z="desolace",s="Captain Pentigast seeks an alliance with the Gelkis in Desolace. They are at war with the Magram, and he sends you southwest to Uthek the Wise.",h="Captain Pentigast seeks an alliance with the Gelkis in Desolace.",sec={{t="Divided Clans",b="Captain Pentigast sees a chance in the centaur clans’ quarrels. Joined together, they could not be stopped. He hopes their division will serve the Alliance. The Gelkis and Magram are locked in a brutal war, so striking at the Magram might persuade the Gelkis to join the Alliance.",sp=0},{t="Seeking Uthek",b="Uthek the Wise is where the Gelkis camps begin in southwestern Desolace. Pentigast hopes she can help secure an alliance. At first, she sends you away. She tells you to return after killing many Magram.",sp=0},{t="Uthek's Answer",b="Uthek the Wise tells you the Gelkis now whisper your name after you have killed many Magram. She approves, and is willing to discuss what you can offer the clan and what it can offer you.",sp=1}},faq={{q="Who sends you to contact the Gelkis?",a="Captain Pentigast sends you to contact the Gelkis, hoping to make an alliance with the clan.",al={"who gives strange alliance","strange alliance quest giver","who starts strange alliance"}},{q="Where is Uthek the Wise located?",a="In southwestern Desolace, at the edge where the Gelkis camps begin.",al={"uthek location","find uthek the wise","where is uthek"}},{q="Why will Uthek the Wise not talk to newcomers right away?",a="Uthek the Wise tells you to leave and return after killing many Magram.",al={"why uthek hostile","uthek won't speak","how to talk to uthek"}},{q="Why does the Alliance want a pact with the Gelkis?",a="Captain Pentigast sees the centaur clans’ quarrels as a chance, since they could not be stopped if united. The Gelkis are at war with the Magram, and striking at the Magram might win the Gelkis’ friendship.",al={"why ally with gelkis","alliance centaur reason","why gelkis clan"}}},kw={"centaur","desolace","gelkis","magram","pentigast","strange alliance","uthek"},rel={"quest:1384","zone:desolace","topic:centaur","topic:alliance"},m={start="Captain Pentigast",["end"]="Uthek the Wise",level="35",faction="Alliance",id=1382},src={"Strange Alliance"}}
E["quest:1384"] = {t="quest",n="Raid on the Kolkar",z="desolace",s="In Desolace, Uthek the Wise sends you northeast against the Kolkar centaurs. After Strange Alliance, he wants ten of their charms brought back.",h="In Desolace, Uthek the Wise sends you northeast against the Kolkar centaurs.",sec={{t="Contempt for Kolkar Magic",b="Uthek scorns the Kolkar centaurs for trusting in their magic. To him, they know nothing of such things. So you head northeast, kill Kolkar, and take their charms. Uthek wants ten Crude Charms to cast into the fire and laugh as they burn.",sp=0},{t="Uthek's Verdict",b="Uthek calls your deed good for the Gelkis. He says the Kolkar are feeble and doomed, and their magic cannot save them. They have seen your work and will fear the Gelkis all the more. Fear weakens them, and in Gelkis lands, the feeble soon die.",sp=1}},faq={{q="Who is Uthek the Wise?",a="Uthek the Wise waits in Gelkis Village in Desolace and wants the Kolkar's charms.",al={"who gives raid on the kolkar","uthek","uthek the wise lore"}},{q="Where are the Kolkar located?",a="Uthek says the Kolkar are northeast.",al={"where to find kolkar","kolkar location desolace"}},{q="What are the Crude Charms?",a="Crude Charms are taken from the Kolkar. Uthek wants ten cast into the fire so she can laugh as they burn.",al={"crude charm","kolkar charms"}},{q="How does this fit into the Gelkis chain?",a="Raid on the Kolkar follows Strange Alliance.",al={"gelkis chain","what comes before raid on the kolkar"}}},kw={"centaur","crude charms","desolace","gelkis","kolkar","uthek"},rel={"quest:1382","quest:1370","subzone:gelkis-village","topic:centaur","zone:desolace"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="32",faction="Alliance",id=1384,ri={"Crude Charm"}},src={"Raid on the Kolkar"}}
E["quest:1385"] = {t="quest",n="Brutal Politics",z="desolace",s="Captain Pentigast fears Desolace’s victorious centaur clan will threaten Alliance strongholds. He seeks a clan’s friendship so the Alliance can learn how to defeat the centaurs.",h="Captain Pentigast fears Desolace’s victorious centaur clan will threaten Alliance strongholds.",sec={{t="A Land at War",b="Centaur clans wage war across Desolace. Captain Pentigast fears the victor will turn against Alliance strongholds, so he seeks a way to prevent that danger. The Alliance needs a centaur clan as a friend to learn how to defeat the others.",sp=0},{t="The Magram",b="The Magram fight the Gelkis, so attacking the Gelkis may win the Magram’s favor. Earn that favor, then find Warug in the Magram village in southeastern Desolace. Warug says killing Gelkis is how you become a friend to the Magram.",sp=0}},faq={{q="Why does the Alliance want an alliance with a centaur clan?",a="Captain Pentigast fears the victorious centaur clan will threaten Alliance strongholds. The Alliance needs a clan as a friend so it can learn how to defeat the centaurs.",al={"why ally with magram","pentigast plan","centaur alliance reason"}},{q="How do you earn the favor of the Magram?",a="The Magram fight the Gelkis, so attacking the Gelkis may persuade them to consider an alliance. Warug says killing Gelkis is how you become a friend to the Magram.",al={"how to get magram rep","magram friendly","killing gelkis"}},{q="Where is Warug?",a="Warug is in the Magram village in southeastern Desolace.",al={"warug location","where is warug","magram contact"}}},kw={"brutal politics","centaur","desolace","gelkis","magram","pentigast","warug"},rel={"quest:1386","subzone:magram-village","topic:centaur","zone:desolace","topic:alliance"},m={start="Captain Pentigast",["end"]="Warug",level="35",faction="Alliance",id=1385},src={"Brutal Politics"}}
E["quest:1386"] = {t="quest",n="Assault on the Kolkar",z="desolace",s="In Magram Village, Warug wants you to prove you can kill Kolkar as the Magram do. After Brutal Politics, you head north to face Kolkar centaurs, scouts and maulers.",h="In Magram Village, Warug wants you to prove you can kill Kolkar as the Magram do.",sec={{t="We Laugh and We Kill",b="Warug mocks the Kolkar and their belief that they are strong. The Magram laugh as they kill them, and Warug wants you to prove you can do the same. Head north and slay twelve Kolkar centaurs, twelve scouts and six maulers.",sp=0},{t="Warug's Approval",b="When you return, Warug says the Kolkar fear you now. He hopes you laughed as you killed them, so the enemy could see its own weakness.",sp=1}},faq={{q="Who sends you to attack the Kolkar?",a="Warug of the Magram sends you from Magram Village in Desolace.",al={"who gives assault on the kolkar","quest giver assault on the kolkar","where to get assault on the kolkar"}},{q="What came before this step?",a="This follows Brutal Politics.",al={"previous quest","prereq assault on the kolkar","assault on the kolkar prerequisite"}},{q="Where are the Kolkar located?",a="Warug tells you to head north to find the Kolkar.",al={"kolkar location","where are kolkar centaur","where to find kolkar"}},{q="Why does Warug want the Kolkar killed?",a="Warug mocks the Kolkar for thinking themselves strong. He wants you to show you can kill them as the Magram do.",al={"why kill kolkar","magram kolkar rivalry","why does warug hate kolkar"}}},kw={"brutal politics","centaur","desolace","kolkar","magram","magram village","warug"},rel={"quest:1385","subzone:magram-village","topic:centaur","zone:desolace"},m={start="Warug",["end"]="Warug",level="32",faction="Alliance",id=1386},src={"Assault on the Kolkar"}}
E["quest:1387"] = {t="quest",n="Centaur Bounty",z="desolace",s="At Nijel's Point, Corporal Melkins sends you after Desolace's centaur clans. He asks for fifteen ears, believing peace cannot come while they remain.",h="At Nijel's Point, Corporal Melkins sends you after Desolace's centaur clans.",sec={{t="One Thing in Common",b="At Nijel's Point, Corporal Melkins speaks of Desolace's centaur clans. Each has its own leader and plans. Yet all share the same cruelty. Melkins says peace can come only when the centaur are gone.",sp=0},{t="Ears for the Alliance",b="As you wander Desolace, you hunt centaur and take their ears. Melkins asks you to bring fifteen. He calls this service to the Alliance, bringing the war's end nearer.",sp=0}},faq={{q="Who issues the bounty on the centaur?",a="Corporal Melkins issues the bounty from Nijel's Point in Desolace.",al={"centaur bounty questgiver","who gives centaur bounty","melkins bounty"}},{q="Why does Corporal Melkins want the centaur killed?",a="Melkins says the clans differ in their leaders and aims, but all are cruel. He believes peace is impossible while the centaur remain.",al={"why kill centaur","melkins motive","why centaur ears"}},{q="What does Corporal Melkins ask you to bring?",a="Melkins asks you to bring fifteen centaur ears, taken from those you hunt while wandering Desolace.",al={"what to collect","centaur bounty items","centaur bounty trophy"}},{q="Which centaur clans need to be hunted?",a="Melkins names no single clan. He says all the clans share cruelty and asks you to hunt centaur in Desolace.",al={"which centaurs","centaur clan target","what clan for ears"}}},kw={"alliance","bounty","centaur","centaur ear","corporal melkins","desolace","ears","nijel's point"},rel={"subzone:nijel-s-point","topic:centaur","zone:desolace","topic:alliance"},m={start="Corporal Melkins",["end"]="Corporal Melkins",level="31",faction="Alliance",id=1387,ri={"Centaur Ear"}},src={"Centaur Bounty (Alliance)"}}
E["quest:1434"] = {t="quest",n="Befouled by Satyr",z="desolace",s="Takata Steelblade in Desolace asks you to confront several kinds of Hatefury satyr. Their presence is the problem he needs you to address.",h="Takata Steelblade in Desolace asks you to confront several kinds of Hatefury satyr.",sec={{t="Takata's Request",b="Takata Steelblade asks for your help in Desolace. Hatefury Rogues, Felsworn, Betrayers, and Hellcallers are the satyr he names. He needs you to slay seven of each, then return to him.",sp=0}},faq={{q="Who asks for help with the Hatefury satyr?",a="Takata Steelblade asks you to confront the Hatefury satyr in Desolace.",al={"who is Takata","Takata Steelblade"}},{q="Which Hatefury satyr does Takata name?",a="Takata names Hatefury Rogues, Felsworn, Betrayers, and Hellcallers.",al={"Hatefury types","satyrs list"}},{q="How many of each kind does Takata ask you to slay?",a="Takata asks you to slay seven of each kind he names.",al={"how many satyrs","number of each"}},{q="Where do you return after dealing with the satyr?",a="Takata asks you to return to him in Desolace.",al={"where to go back","return to Takata"}}},kw={"befouled by satyr","betrayer","desolace","felsworn","hatefury","hellcaller","rogue","satyr","takata steelblade"},rel={"npc:takata-steelblade","zone:desolace"},m={faction="Horde",id=1434},src={"In-game quest text: Befouled by Satyr"},fv=true}
E["quest:1435"] = {t="quest",n="The Burning of Spirits",z="desolace",s="Maurin Bonesplitter in Desolace asks you to return the Burning Gem and fifteen Infused Burning Gems.",h="Maurin Bonesplitter in Desolace asks you to return the Burning Gem and fifteen Infused Burning Gems.",sec={},faq={{q="Who wants the gems?",a="Maurin Bonesplitter asks you to return the Burning Gem and fifteen Infused Burning Gems.",al={"who asked for gems","Maurin gems"}},{q="Where do I return the gems?",a="Return the Burning Gem and fifteen Infused Burning Gems to Maurin Bonesplitter in Desolace.",al={"where to bring gems","gems location"}},{q="Which gems does Maurin ask for?",a="Maurin asks for the Burning Gem and fifteen Infused Burning Gems.",al={"what gems","burning gem quest"}}},kw={"burning gem","desolace","gems","infused burning gems","maurin bonesplitter"},rel={"npc:maurin-bonesplitter","zone:desolace"},m={faction="Horde",id=1435},src={"In-game quest text: The Burning of Spirits"},fv=true}
E["quest:1436"] = {t="quest",n="Alliance Relations",z="desolace",s="Takata Steelblade in Desolace sends you back to Keldran in Orgrimmar to report your efforts. Keldran hopes the Horde and Alliance can find peace.",h="Takata Steelblade in Desolace sends you back to Keldran in Orgrimmar to report your efforts.",sec={{t="Keldran's Appeal",b="Takata Steelblade hopes the fight against the demons and their followers may let them go home before the seasons change. He says Keldran will take pride in knowing the Warchief respects his concerns.",sp=0},{t="A Plea for Peace",b="Keldran thanks you for returning from Desolace and says Thrall understands his plea. The Warchief wants peace between the Horde and Alliance. Keldran believes making their appearance acceptable can prevent further threats of needless violence, and he is grateful for your help.",sp=1}},faq={{q="Who is asking me to return?",a="Takata Steelblade in Desolace sends you back to tell Keldran in Orgrimmar what you have done.",al={"who sent me back","who is Keldran"}},{q="Where do I report back?",a="You are asked to speak with Keldran in Orgrimmar.",al={"where is Keldran","report back where"}},{q="What was I doing in Desolace?",a="The work in Desolace involved fighting demons and their followers.",al={"Desolace work","what did I do there"}},{q="What does Keldran hope will happen?",a="Keldran hopes the Horde and Alliance can find peace. It is Takata Steelblade who hopes the Warchief will let them go home before the seasons change.",al={"Keldran's hope","home before seasons change"}},{q="What does Thrall want?",a="Keldran says Thrall understands his plea and desires peace between the Horde and Alliance.",al={"Thrall peace","Horde Alliance peace"}}},ang={["faction:Alliance"]="As an Alliance traveler, Keldran's plea concerns peace between your people and the Horde.",["faction:Horde"]="As a member of the Horde, Keldran hopes Thrall's desire for peace will ease tensions with the Alliance."},kw={"alliance","alliance relations","demons","desolace","horde","keldran","orgrimmar","peace","thrall"},rel={"npc:keldran","npc:thrall","zone:desolace","zone:orgrimmar","topic:alliance","topic:horde"},m={faction="Horde",id=1436},src={"In-game quest text: Alliance Relations"},fv=true}
E["quest:1437"] = {t="quest",n="Vahlarriel's Search",z="desolace",s="In Desolace, Vahlarriel Demonslayer searches for two missing nobles of House Malem. Their father fears the worst, and the siblings were last reported crossing the Stonetalon Mountains some weeks ago. Vahlarriel asks you to find their wagon.",h="In Desolace, Vahlarriel Demonslayer searches for two missing nobles of House Malem.",sec={{t="Two Missing Nobles",b="Vahlarriel Demonslayer seeks Tyranis and Dalinda Malem. Their father has charged Vahlarriel with doing everything possible to find them. The search has only begun, and Vahlarriel hopes it will not keep them in Desolace long. The siblings were last reported crossing the Stonetalon Mountains some weeks ago. You are asked to find their wagon in Desolace and return at once. Its charred remains lie there, with a chest among them.",sp=0},{t="Among the Wreckage",b="The wreck bears marks left by spells and weapons. The fight seems brief and one-sided, yet no blood or bodies remain. Whoever struck was swift and efficient.",sp=1}},faq={{q="Who is Vahlarriel looking for?",a="Vahlarriel seeks Tyranis and Dalinda Malem, two nobles of House Malem, a Darnassian merchant family.",al={"who is missing","who are the nobles","house malem missing children"}},{q="Where were the siblings last heard from?",a="Crossing the Stonetalon Mountains, some weeks ago, by the last report.",al={"malem siblings last seen","where did they go","wagon route"}},{q="Why is Vahlarriel searching?",a="Their father fears the worst. He has charged Vahlarriel with doing everything possible to find his missing children.",al={"who hired vahlarriel","who wants the siblings found"}},{q="What does Vahlarriel want you to find?",a="Vahlarriel asks you to find Tyranis and Dalinda Malem's wagon in Desolace and return at once if you find it.",al={"how does vahlarriel search start","what is the first step"}}},kw={"chest","dalinda","darnassus","desolace","malem","stonetalon","tyranis","vahlarriel"},rel={"zone:desolace","zone:stonetalon","quest:1439","quest:1440"},m={start="Vahlarriel Demonslayer",["end"]="Malem Chest",level="33",faction="Alliance",id=1437},src={"Vahlarriel's Search"}}
E["quest:1438"] = {t="quest",n="Vahlarriel's Search",z="desolace",s="At the fortress, Vahlarriel Demonslayer sends you to find Dalinda and Tyranis Malem. Their search begins there as Vahlarriel alerts superiors in Darnassus. They put Dalinda’s safe return first and question Tyranis’s motives.",h="At the fortress, Vahlarriel Demonslayer sends you to find Dalinda and Tyranis Malem.",sec={{t="A Search at the Fortress",b="Vahlarriel Demonslayer asks you to seek Dalinda and Tyranis at the fortress and bring back what you learn. Vahlarriel will contact superiors in Darnassus at once. In private, they share their concern about why Tyranis came to Desolace. Above all, they want Dalinda brought home safe. Tyranis’s return can wait until they know more about him.",sp=0},{t="A Captive's Account",b="Dalinda is held in the large building facing the entrance. She says the Burning Blade seized her and Tyranis and brought them here. She believes the cult plans to sacrifice her to its demon masters. Dalinda says the journey was a mistake from the start.\n\nTyranis had grown hungry for arcane lore, against his people’s wishes, and set out despite warnings of demons in Desolace. Dalinda fears what has become of him.",sp=1}},faq={{q="Where is Dalinda Malem?",a="Dalinda is in the Thunder Axe Fortress area of Desolace, in the large building facing the entrance.",al={"dalinda malem location","where to find dalinda","find dalinda desolace"}},{q="Who sends you to look for Dalinda and Tyranis?",a="Vahlarriel Demonslayer asks you to find Dalinda and Tyranis at the fortress while Vahlarriel informs superiors in Darnassus.",al={"who gives vahlarriel's search","quest giver vahlarriel","vahlarriel demonslayer quest"}},{q="Why does Darnassus care more about Dalinda than Tyranis?",a="Vahlarriel’s superiors doubt Tyranis’s reasons for coming to Desolace, and they value Dalinda’s safe return above all.",al={"why is tyranis suspected","tyranis motives","why prioritize dalinda"}},{q="What came before this part of the search?",a="It follows the second part of Vahlarriel’s Search.",al={"previous quest","prerequisite vahlarriel","vahlarriel search chain"}}},kw={"burning blade","dalinda","darnassus","demonslayer","desolace","malem","thunder axe fortress","tyranis","vahlarriel"},rel={"subzone:thunder-axe-fortress","zone:desolace","zone:darnassus","quest:1439","quest:1440","quest:1437","topic:elune"},m={start="Vahlarriel Demonslayer",["end"]="Dalinda Malem",level="33",faction="Alliance",id=1438},src={"Vahlarriel's Search (3)"}}
E["quest:1439"] = {t="quest",n="Search for Tyranis",z="desolace",s="At Thunder Axe Fortress, Dalinda Malem waits to learn what became of Tyranis. Orcs killed their guards and servants before bringing the siblings there. Tyranis tried to speak with his captors, and Dalinda asks you to find him and return once you know his fate.",h="At Thunder Axe Fortress, Dalinda Malem waits to learn what became of Tyranis.",sec={{t="A Brother Taken",b="Orcs killed every guard and servant before dragging Dalinda and Tyranis to Thunder Axe Fortress. She expected them to die at once, but their captors had other designs. Tyranis tried speaking with the orcs, perhaps hoping his arcane learning would impress them. Dalinda cannot say why. She will not escape until she knows his fate, so she asks you to find him and return. He is in the building left of the fortress entrance.",sp=0},{t="Dalinda's Fear",b="Dalinda fears Tyranis will seek the Burning Blade's secrets and join them if he can. Power has always drawn him, as magic draws those it seduces. To Dalinda's people, even studying such things is a grave crime. She doubts she could face her family knowing her brother had toyed with that danger.",sp=0},{t="What Dalinda Learns",b="When you return, Dalinda calls what happened terrible but necessary. If your hand had not done it, someone from her own people would have. She asks you to pardon her if her thanks sounds hollow. Now that she knows Tyranis's fate, she is ready to escape and will accept your help if you are still willing.",sp=1}},faq={{q="Who is Tyranis Malem?",a="Tyranis Malem is Dalinda's brother. He spoke to their captors, perhaps hoping his arcane learning would impress them. Dalinda says magic's power has always drawn him.",al={"who is tyranis","tyranis backstory","tyranis malem"}},{q="Why does Dalinda refuse to leave yet?",a="Dalinda refuses to leave until she knows what happened to her brother. She asks you to find him and return once his fate is known.",al={"why wont dalinda leave","why does dalinda stay","why wait to escape"}},{q="What happened to the guards and servants?",a="The orcs killed all the guards and servants, then took Dalinda and Tyranis alive with other designs.",al={"what happened to their guards","who was killed","guards and servants"}},{q="Where is Tyranis?",a="Tyranis is at Thunder Axe Fortress in Desolace, in the building on the left as you enter.",al={"where is tyranis","tyranis location"}},{q="What came before this step?",a="This follows the third part of Vahlarriel's Search, where Vahlarriel sent you to find Dalinda.",al={"what quest is before this","quest progression","vahlarriel quest chain"}}},kw={"burning blade","dalinda","desolace","malem","pendant","thunder axe fortress","tyranis","vahlarriel"},rel={"quest:1437","quest:1440","subzone:thunder-axe-fortress","zone:desolace"},m={start="Dalinda Malem",["end"]="Dalinda Malem",level="33",faction="Alliance",id=1439,ri={"Tyranis' Pendant"}},src={"Search for Tyranis"}}
E["quest:1440"] = {t="quest",n="Return to Vahlarriel",z="desolace",s="At Thunder Axe Fortress, Dalinda Malem is ready to leave when you choose. She thanks you for helping her and her family. Escort her out, then find Vahlarriel Demonslayer.",h="At Thunder Axe Fortress, Dalinda Malem is ready to leave when you choose.",sec={{t="Leaving the Fortress",b="Dalinda Malem is ready to leave Thunder Axe Fortress when you judge the moment right. She thanks you for all you have done for her and her family, in case things do not go as hoped. Nothing else keeps her there. She will leave when you choose the time. Escort her out of the fortress, then find Vahlarriel Demonslayer in Desolace.",sp=0},{t="Word from Vahlarriel",b="Vahlarriel Demonslayer thanks you. Dalinda reached Nijel's Point in far better shape than Vahlarriel could have asked for. Her arrival through her own strength was a good sign. Neither sibling returned, which pains Vahlarriel. Tyranis's choices leave her with an embarrassment to endure when she returns to Darnassus.",sp=1}},faq={{q="Who asks you to escort her?",a="Dalinda Malem, who is ready to leave Thunder Axe Fortress once you judge the moment right.",al={"who gives return to vahlarriel","quest giver return to vahlarriel","who is dalinda malem"}},{q="Where does this begin?",a="You begin at Thunder Axe Fortress in Desolace, where Dalinda Malem is waiting.",al={"dalinda malem location","where is dalinda malem","where does return to vahlarriel start"}},{q="Who do you go to after Dalinda is out?",a="After Dalinda is out, you go to Vahlarriel Demonslayer in Desolace.",al={"where to turn in return to vahlarriel","who finishes return to vahlarriel","return to vahlarriel end"}},{q="What came before this step?",a="This follows Search for Tyranis, part of the longer Vahlarriel's Search.",al={"prereq return to vahlarriel","return to vahlarriel previous","what quest comes before return to vahlarriel"}}},kw={"dalinda malem","darnassus","desolace","escort","nijel's point","thunder axe fortress","tyranis","vahlarriel"},rel={"quest:1439","quest:1437","subzone:thunder-axe-fortress","subzone:nijel-s-point","zone:desolace","zone:darnassus"},m={start="Dalinda Malem",["end"]="Vahlarriel Demonslayer",level="33",faction="Alliance",id=1440},src={"Return to Vahlarriel"}}
E["quest:1454"] = {t="quest",n="The Karnitol Shipwreck",z="desolace",s="After sea giants strike his ship in Desolace, Karnitol flees with his servants by teleporting away. Kreldig Ungor sends you to find the noble's chest.",h="After sea giants strike his ship in Desolace, Karnitol flees with his servants by teleporting away.",sec={{t="A Noble's Flight",b="After Reclaimers' Business in Desolace, Kreldig Ungor sends you to find Karnitol's lost chest. Karnitol is a mage and some kind of noble in Stormwind. Sea giants struck his ship in the northwest waters of Desolace.\n\nHe and his servants tried to bring one of his costlier chests ashore, but the giants swarmed them. Karnitol left the chest behind and teleported away with his servants. Find the chest and its contents, then return them to Karnitol in Stormwind. It lies along the northern coastline, in the Ethel Rethor stretch.",sp=0},{t="What the Chest Shows",b="Karnitol's chest has no water damage, but someone forced its lid open. Burn marks around the edges show that its magical traps were sprung long ago.",sp=1}},faq={{q="Who is Karnitol?",a="Karnitol is a mage and some kind of noble in Stormwind. Sea giants struck his ship in Desolace's northwest waters.",al={"karnitol","who is karnitol","who wants the chest"}},{q="What happened to Karnitol's ship?",a="Sea giants struck Karnitol's ship in Desolace's northwest waters. Karnitol and his servants tried to bring a valuable chest ashore, but the giants swarmed them. He left it behind and teleported away with his servants.",al={"shipwreck story","why did ship sink","sea giant attack"}},{q="Who is looking for the chest?",a="Kreldig Ungor is looking for the chest. He says Karnitol wants it and its contents found and returned to him in Stormwind.",al={"who gives quest","kreldig ungor role"}},{q="Where does the chest lie?",a="The chest lies along Desolace's northern coastline, in the Ethel Rethor stretch.",al={"karnitol chest location","where is karnitol's chest","ethel rethor chest"}}},kw={"desolace","ethel rethor","karnitol","kreldig ungor","reclaimers","sea giants","shipwreck","stormwind"},rel={"npc:kreldig-ungor","subzone:ethel-rethor","zone:desolace","topic:stormwind-kingdom","topic:mage","quest:1453"},m={start="Kreldig Ungor",["end"]="Karnitol's Chest",level="39",faction="Alliance",id=1454},src={"The Karnitol Shipwreck"}}
E["quest:1455"] = {t="quest",n="The Karnitol Shipwreck",z="desolace",s="At Karnitol's wreck, you find the chest open and empty. Deep scratches score its sides and top, so you return to Kreldig Ungor at Nijel's Point.",h="At Karnitol's wreck, you find the chest open and empty.",sec={{t="An Empty Chest",b="The chest lies empty, its sides and top scored with long, deep scratches. The marks suggest neither man nor giant forced it open. They look unlike cuts from a dagger or sword. With nothing more to learn, you close the chest and prepare to leave. Kreldig Ungor will be disappointed.",sp=0}},faq={{q="What is inside Karnitol's chest?",a="Nothing remains in Karnitol's chest. It is completely empty.",al={"what was in karnitol chest","is karnitol chest empty","chest contents"}},{q="What made the marks on the chest?",a="Long, deep scratches score the chest's sides and top. They suggest neither man nor giant made them, and do not look like dagger or sword cuts.",al={"what opened the chest","who took the cargo","chest claw marks"}},{q="Who do you report to?",a="You report to Kreldig Ungor at Nijel's Point in Desolace.",al={"who do i turn this in to","where is kreldig ungor","where to go next"}},{q="What came before this?",a="Before this, Kreldig Ungor asked you to search for Karnitol's chest.",al={"previous quest","karnitol shipwreck chain"}}},kw={"desolace","karnitol","karnitol's chest","kreldig ungor","nijel's point","shipwreck"},rel={"npc:kreldig-ungor","subzone:nijel-s-point","zone:desolace","quest:1454"},m={start="Karnitol's Chest",["end"]="Kreldig Ungor",level="39",faction="Alliance",id=1455},src={"The Karnitol Shipwreck (2)"}}
E["quest:1456"] = {t="quest",n="The Karnitol Shipwreck",z="desolace",s="Near Ranazjar Isle, Kreldig Ungor still hopes Karnitol's belongings can be found. The Slitherblade naga live among night elf ruins beneath the sea, where Kreldig thinks the satchel is most likely to be.",h="Near Ranazjar Isle, Kreldig Ungor still hopes Karnitol's belongings can be found.",sec={{t="Ruins in the Deep",b="Kreldig Ungor says there is still hope of finding Karnitol's belongings. Farther north along the coast, sunken night elf ruins lie on the ocean floor near Ranazjar Isle. The Slitherblade naga live there, and Kreldig believes it is the likeliest place to find Karnitol's satchel. He gives you a Recovery Diver's Potion.",sp=0},{t="The Stronger Naga",b="Kreldig believes the scouting party that traveled so far south must have been strong. He would search the mightier naga first: the tidehunters and sea witches.",sp=0}},faq={{q="Who asks you to find Karnitol's satchel?",a="Kreldig Ungor asks you to find Karnitol's satchel in Desolace.",al={"who gives this quest","quest giver karnitol satchel","who is kreldig ungor"}},{q="Where does Kreldig think the belongings are?",a="Kreldig thinks Karnitol's belongings lie among the sunken night elf ruins north along the coast near Ranazjar Isle. The Slitherblade naga make their home there.",al={"where is karnitol satchel","satchel location","where are the slitherblade naga"}},{q="Which naga does Kreldig suggest searching first?",a="Kreldig suggests searching the tidehunters and sea witches first. He reasons that a scouting party that traveled so far south must have been powerful.",al={"who has the satchel","which naga have it","tidehunter or sea witch"}},{q="What came before this?",a="The second part of the Karnitol shipwreck search came before this.",al={"karnitol shipwreck quest chain","what quest comes before this"}}},kw={"desolace","karnitol","kreldig ungor","ranazjar isle","reclaimers","satchel","sea witch","slitherblade","tidehunter"},rel={"npc:kreldig-ungor","zone:desolace","topic:naga","topic:night-elf"},m={start="Kreldig Ungor",["end"]="Kreldig Ungor",level="39",faction="Alliance",id=1456,ri={"Karnitol's Satchel"}},src={"The Karnitol Shipwreck (3)"}}
E["quest:1457"] = {t="quest",n="The Karnitol Shipwreck",z="desolace",s="Karnitol's satchel waits in Ironforge for Roetten Stonehammer, who will pay you to carry it there.",h="Karnitol's satchel waits in Ironforge for Roetten Stonehammer, who will pay you to carry it there.",sec={{t="Back to Ironforge",b="Kreldig Ungor sends you to take Karnitol's things to Roetten Stonehammer in Ironforge. Roetten will pay you for the work. With a laugh, Kreldig says Roetten may be so pleased that he asks you to join the Reclaimers full time. Travel carefully and without delay. Karnitol has little patience, though he is generous.",sp=0},{t="In Ironforge",b="In Ironforge, Roetten Stonehammer approves of the Karnitol business in Desolace. The chest was wrecked, but everything it held is here. Roetten leaves it to Karnitol to judge. The Reclaimers are relied on to find what was lost, not return it in fine shape. Then Roetten sets about paying you.",sp=1}},faq={{q="Who do I deliver Karnitol's satchel to?",a="Deliver Karnitol's satchel to Roetten Stonehammer in Ironforge.",al={"where do i take the satchel","turn in karnitol shipwreck","who gets karnitol's satchel"}},{q="Who sends me back to Ironforge?",a="Kreldig Ungor sends you back to Ironforge and praises your work.",al={"who gives the quest","quest giver karnitol shipwreck part 4"}},{q="Why is it important to deliver the satchel quickly?",a="Kreldig says Karnitol has little patience, though he is very generous.",al={"why rush to ironforge","is karnitol patient"}},{q="Who is Roetten Stonehammer?",a="Roetten Stonehammer is the Reclaimers' man in Ironforge. Business is booming for him, and he leaves smaller matters to his underlings.",al={"roetten stonehammer lore","who is roetten"}}},kw={"desolace","ironforge","karnitol","karnitol's satchel","kreldig ungor","reclaimers","roetten stonehammer"},rel={"npc:roetten-stonehammer","npc:kreldig-ungor","zone:ironforge","zone:desolace","quest:1456"},m={start="Kreldig Ungor",["end"]="Roetten Stonehammer",level="39",faction="Alliance",id=1457,ri={"Karnitol's Satchel"}},src={"The Karnitol Shipwreck (4)"}}
E["quest:1458"] = {t="quest",n="Reagents for Reclaimers Inc.",z="desolace",s="In Desolace, Kreldig Ungor gathers reagents for Leftwitch, a gnome mage in Kharanos. The Reclaimers are short-handed, so he begins with claws and horns from the Hatefury satyrs to the east.",h="In Desolace, Kreldig Ungor gathers reagents for Leftwitch, a gnome mage in Kharanos.",sec={{t="Leftwitch's List",b="After Reclaimers' Business in Desolace, Kreldig Ungor takes on another job. He gathers reagents for Leftwitch, a gnome mage who lives in Kharanos. Roetten calls it easy coin because the Reclaimers are already in Desolace. The crew is short-handed, but Kreldig says he does not care.",sp=0},{t="Horns and Claws",b="Kreldig begins with ten claws and ten horns from the Hatefury satyrs to the east. They dwell in the Sargeron ruins, due east of Nijel's Point. Once you have the claws and horns, the rest of Leftwitch's list can begin.",sp=0}},faq={{q="Who is requesting these reagents?",a="Kreldig Ungor gathers reagents for Leftwitch, a gnome mage who lives in Kharanos. Roetten calls it easy coin because the Reclaimers are already in Desolace.",al={"who is leftwitch","reagents for reclaimers inc quest giver","who wants the reagents"}},{q="Where are the Hatefury satyrs located?",a="The Hatefury satyrs are in the Sargeron ruins, due east of Nijel's Point.",al={"hatefury satyr location","where are hatefury claws","hatefury horns location"}},{q="What does Kreldig want from the satyrs?",a="Kreldig wants ten Hatefury claws and ten Hatefury horns. With them, you and Kreldig can move on to the next items on Leftwitch's list.",al={"what do i need to collect","reagents for reclaimers inc items","satyr parts needed"}},{q="What does Kreldig think about satyrs?",a="Kreldig calls the satyrs despicable creatures. He has heard they are linked somehow to the night elves, though he doubts it. He believes the story comes from the one elf who brought them into the war a few years ago. Since then, he thinks the world has grown more dangerous and frightening.",al={"kreldig satyr lore","are satyrs night elves"}}},kw={"desolace","hatefury","kharanos","kreldig ungor","leftwitch","reclaimers","roetten","sargeron","satyr"},rel={"quest:1453","npc:kreldig-ungor","subzone:sargeron","subzone:nijel-s-point","subzone:kharanos","topic:satyr","topic:gnome","zone:desolace"},m={start="Kreldig Ungor",["end"]="Kreldig Ungor",level="33",faction="Alliance",id=1458,ri={"Hatefury Claw","Hatefury Horn"}},src={"Reagents for Reclaimers Inc. (quest)"}}
E["quest:1459"] = {t="quest",n="Reagents for Reclaimers Inc.",z="desolace",s="In Desolace, Leftwitch's list sends Kreldig Ungor after scorpashi venom and aged kodo hides. He barely knows the land and cannot point you toward either creature.",h="In Desolace, Leftwitch's list sends Kreldig Ungor after scorpashi venom and aged kodo hides.",sec={{t="The Next Items",b="Kreldig Ungor reaches the next items on Leftwitch's list. She asks for seven vials of venom from any scorpashi and three hides from aged kodo. Dying and ancient kodo will not do. The instructions are plain, though Kreldig muses that mages ask for odd things.",sp=0},{t="Unfamiliar Ground",b="Kreldig cannot tell you where the kodo or scorpashi roam. He barely knows Desolace and has had no time to explore it.",sp=0}},faq={{q="Who is requesting these reagents?",a="Leftwitch, a mage, made the list Kreldig Ungor is working through.",al={"who wants reagents","who is leftwitch","kreldig boss"}},{q="Why does Kreldig need help finding these creatures?",a="Kreldig barely knows Desolace and has had no time to explore it, so he cannot say where the kodo or scorpashi roam.",al={"why cant kreldig get them","kreldig territory knowledge"}},{q="Can hides from any kodo be used?",a="No. Leftwitch asks for aged kodo hides. Dying and ancient kodo do not count.",al={"any kodo hide","ancient kodo hide","dying kodo hide"}},{q="What are the scorpashi?",a="Scorpashi are scorpions found throughout Desolace. Leftwitch says venom from any of them will do.",al={"scorpashi venom","where are scorpashi"}},{q="Where do the aged kodo roam?",a="Aged kodo follow the trails, chiefly in the south and west. Many end up near the Kodo Graveyard.",al={"aged kodo location","where are aged kodo"}}},kw={"aged kodo hide","desolace","ironforge","kreldig ungor","leftwitch","reclaimers inc","scorpashi venom"},rel={"quest:1458","npc:kreldig-ungor","zone:desolace","zone:ironforge","subzone:kodo-graveyard","topic:mage"},m={start="Kreldig Ungor",["end"]="Kreldig Ungor",level="35",faction="Alliance",id=1459,ri={"Aged Kodo Hide","Scorpashi Venom"}},src={"Reagents for Reclaimers Inc. (2)"}}
E["quest:1465"] = {t="quest",n="Vahlarriel's Search",z="desolace",s="In Desolace, Vahlarriel's Search follows a trail south from the Malems' wagon. A pendant lies there, and smoke rises from a large fort in the distance. At Nijel's Point, Vahlarriel Demonslayer needs the pendant and word that the Malems may still be alive.",h="In Desolace, Vahlarriel's Search follows a trail south from the Malems' wagon.",sec={{t="Signs of Life",b="You find a pendant in the Malems' wagon and footprints leading south. Smoke rises from a large fort in the distance. A tended fire feeds it, rather than burning buildings. If the Malems are alive, the tracks suggest they were taken toward the fort.",sp=0},{t="Word for Vahlarriel",b="At Nijel's Point, Vahlarriel Demonslayer needs to see the Malem Pendant. Tell her about the footprints leading south.",sp=0},{t="What the Locals Say",b="Vahlarriel is furious. The Malems were warned how dangerous Desolace is, and now both are missing or worse. Tracks toward the nearby fort offer the best lead. Locals say the fortress is overrun by the Burning Blade, orcs devoted to demonic causes. They do not speak for most of the Horde, yet they are evil. Anyone caught spying on them will be killed on sight.",sp=1}},faq={{q="What did you find in the wagon?",a="You find a pendant in the wagon and footprints leading south. Smoke rises from a large fort in the distance.",al={"what is in the chest","wagon clues","malem pendant"}},{q="Where do the tracks lead?",a="The tracks lead south toward a large fort. Smoke above it comes from a tended fire, not burning buildings. If the Malems are alive, they may have been taken that way.",al={"where did the footprints go","where is the fort","tracks direction"}},{q="Where is Vahlarriel Demonslayer located?",a="Vahlarriel Demonslayer is at Nijel's Point in Desolace. Bring the pendant and news of the tracks there.",al={"vahlarriel location","where to turn in malem pendant","vahlarriel demonslayer spot"}}},kw={"burning blade","demonslayer","desolace","fortress","malem","nijel's point","pendant","vahlarriel"},rel={"quest:1437","subzone:nijel-s-point","zone:desolace","topic:horde"},m={start="Malem Chest",["end"]="Vahlarriel Demonslayer",level="33",faction="Alliance",id=1465},src={"Vahlarriel's Search (2)"}}
E["quest:1466"] = {t="quest",n="Reagents for Reclaimers Inc.",z="desolace",s="In Desolace, Kreldig Ungor has the last items Leftwitch requested. They all come from demons: brains, wings, and blood.",h="In Desolace, Kreldig Ungor has the last items Leftwitch requested.",sec={{t="The Last of the List",b="Kreldig Ungor warns you that the final set is grim and slower to gather than any before. Leftwitch wants ten of each of three kinds of parts. You can take felhound brains from mana eaters, mage hunters, or ley hunters. The wings come from nether maidens, sisters, or sorceresses, while doomwarder captains and lords carry the blood. Kreldig would understand if you passed on this one.",sp=0},{t="Demons in Desolace",b="Kreldig Ungor had not known these demons lived in Desolace. His reading said the centaur held most of the land after the night elves departed years ago. So he wonders how the demons came here and why they settled. They dwell near Mannoroc Coven in southern Desolace, beyond the Kodo Graveyard.",sp=0}},faq={{q="Who is asking for these demon parts?",a="Kreldig Ungor passes along Leftwitch's list, and the demon parts are the final items Leftwitch requested.",al={"who gave this quest","who wants the demon parts","who is kreldig ungor"}},{q="What creatures hold the required items?",a="Mana eaters, mage hunters, and ley hunters have felhound brains. Nether maidens, sisters, and sorceresses have wings. Doomwarder captains and lords have blood.",al={"what drops felhound brains","where to get nether wings","which doomwarders have blood"}},{q="Where can these demons be found?",a="The demons gather near Mannoroc Coven in southern Desolace, beyond the Kodo Graveyard.",al={"demon location","where is mannoroc coven","where do the demons roam"}},{q="Why does Kreldig find the demons surprising?",a="Kreldig had read that the centaur held Desolace after the night elves left years ago, so the demons' presence puzzles him.",al={"why are demons in desolace","centaur lore desolace"}}},kw={"desolace","doomwarder blood","felhound brain","kreldig ungor","leftwitch","mannoroc coven","nether wing","reclaimers inc"},rel={"npc:kreldig-ungor","zone:desolace","subzone:mannoroc-coven","subzone:kodo-graveyard","zone:ironforge","topic:centaur"},m={start="Kreldig Ungor",["end"]="Kreldig Ungor",level="40",faction="Alliance",id=1466,ri={"Doomwarder Blood","Felhound Brain","Nether Wing"}},src={"Reagents for Reclaimers Inc. (3)"}}
E["quest:1467"] = {t="quest",n="Reagents for Reclaimers Inc.",z="desolace",s="In Desolace, Kreldig Ungor sends you to Ironforge with Leftwitch's package. Roetten Stonehammer has your pay, and Kreldig plans to speak well of you when he returns home.",h="In Desolace, Kreldig Ungor sends you to Ironforge with Leftwitch's package.",sec={{t="Payment in Ironforge",b="Kreldig says Roetten Stonehammer has your pay in Ironforge. Roetten will be glad to receive Leftwitch's package, and handing it over should be enough to collect what you are owed. Kreldig expects to stay in Desolace only a little longer. Once he is home, he still means to speak well of you.",sp=0},{t="Roetten's Thanks",b="Roetten Stonehammer welcomes Leftwitch's package from Desolace and thanks you for your work and for doing it quickly. Your payment is ready. Roetten says Reclaimers Inc. always pays well for a hard week's work.",sp=1}},faq={{q="Who sends you back to Ironforge?",a="After the reagents are gathered, Kreldig Ungor sends you to Ironforge with Leftwitch's package.",al={"quest giver","who gives the quest","who starts this"}},{q="Where does Leftwitch's package need to go?",a="Leftwitch's package goes to Roetten Stonehammer in Ironforge.",al={"where do i take the package","package destination","who gets the package"}},{q="Why do you carry the package to Roetten?",a="Kreldig says Roetten Stonehammer has your pay, so you carry him the package in Ironforge.",al={"why carry package","why visit roetten"}},{q="Is Kreldig Ungor remaining in Desolace?",a="Kreldig expects to leave Desolace soon. Once he is home, he still plans to speak well of you.",al={"does kreldig leave desolace","where is kreldig going"}}},kw={"desolace","ironforge","kreldig ungor","leftwitch's package","reagents for reclaimers inc","roetten stonehammer"},rel={"npc:roetten-stonehammer","npc:kreldig-ungor","zone:ironforge","zone:desolace","quest:1466"},m={start="Kreldig Ungor",["end"]="Roetten Stonehammer",level="40",faction="Alliance",id=1467},src={"Reagents for Reclaimers Inc. (4)"}}
E["quest:1480"] = {t="quest",n="The Corrupter",z="desolace",s="At Thunder Axe Fortress, a flayed strip from the Burning Blade bears red markings and a signature-like symbol. It smells rotten, yet bends easily. Maurin Bonesplitter at Ghost Walker Post may know more.",h="At Thunder Axe Fortress, a flayed strip from the Burning Blade bears red markings and a signature-like symbol.",sec={{t="A Strip of Skin",b="The flayed skin smells of rot, yet bends easily despite its dry, fragile feel. Unrolled, it shows red markings on one side, written in some kind of language. A plain symbol at the bottom looks like a signature.",sp=0},{t="Maurin's View",b="Maurin Bonesplitter at Ghost Walker Post may know more about the skin. Maurin believes the Burning Blade are coming to see how weak they are. Their magic is poor and their strength slight. Whatever power they hold comes from those they serve, not from any grasp of true power or knowledge.",sp=0},{t="What the Markings Mean",b="Maurin recognises the runes as an old language, somewhat like Eredun but very different in its details. If Maurin is right, the skin is a kind of contract. At the bottom, the symbol is the signature of a demon named Lord Azrethoc.",sp=1}},faq={{q="What is written on the flayed skin?",a="Red markings in some kind of written language cover one side of the flayed skin. At the bottom, a clear symbol looks like a signature. Maurin Bonesplitter at Ghost Walker Post may know more.",al={"flayed skin runes","what does the skin say","red markings on skin"}},{q="Where does the skin come from?",a="The skin was taken from the Burning Blade at Thunder Axe Fortress in Desolace.",al={"skin location","where to get demon skin","how to start the corrupter"}},{q="Who is Maurin Bonesplitter?",a="Maurin Bonesplitter is at Ghost Walker Post in Desolace, where the skin is brought.",al={"where is maurin","maurin bonesplitter location","who is maurin"}},{q="What does Maurin think of the Burning Blade?",a="Maurin sees the Burning Blade as weak, with poor magic and little strength. Maurin believes whatever power they have comes from those they serve.",al={"maurin burning blade","burning blade power"}}},kw={"burning blade","eredun","flayed demon skin","ghost walker post","lord azrethoc","maurin bonesplitter","the corrupter","thunder axe fortress"},rel={"npc:maurin-bonesplitter","subzone:ghost-walker-post","subzone:thunder-axe-fortress","zone:desolace"},m={start="Flayed Demon Skin",["end"]="Maurin Bonesplitter",level="33",faction="Horde",id=1480},src={"The Corrupter"}}
E["quest:1481"] = {t="quest",n="The Corrupter",z="desolace",s="Maurin Bonesplitter searches for a way to find The Corrupter, though its wards may foil scrying. He needs a Hatefury shadowstalker scalp from the old ruins in northeast Desolace, near Sargeron.",h="Maurin Bonesplitter searches for a way to find The Corrupter, though its wards may foil scrying.",sec={{t="Breaking the Wards",b="Maurin Bonesplitter believes the right reagents can reveal the demon lord. If Maurin is right about its power, those reagents must come from deadly creatures. He trusts you to face that danger in the Warchief's name.\n\nFirst, the demon lord's wards against scrying must be broken. Maurin asks you for a satyr's scalp, and only a Hatefury shadowstalker's will serve. Search the old ruins in northeast Desolace, near Sargeron.",sp=0},{t="The Right Scalp",b="Maurin warns you to bring back the right scalp. Wrong reagents could get people killed, for the demon lord may have contingency spells meant to slay anyone who tries to scry on him. Fate has already dealt out enough pain, he says.",sp=0},{t="When You Return",b="Maurin judges the scalp fit for his spell. While you were away, he gathered some of the other reagents it needs and is nearly ready. Only a focus remains, an object that will cast the demon lord's image and reveal where he is.",sp=1}},faq={{q="Who sends you to gather the scalp?",a="Maurin Bonesplitter asks you to bring him the scalp for a spell to find the demon lord.",al={"quest giver","who starts this","maurin bonesplitter"}},{q="Why does Maurin specifically need a Hatefury shadowstalker scalp?",a="The demon lord may have wards against scrying, and Maurin needs a satyr's scalp to break them. Only a Hatefury shadowstalker's scalp will do.",al={"why shadowstalker scalp","satyr scalp reason","why a satyr"}},{q="Where can the Hatefury shadowstalkers be found?",a="Hatefury shadowstalkers can be found in the old ruins of northeast Desolace, near Sargeron.",al={"where are shadowstalkers","shadowstalker location","satyr location"}},{q="What are the dangers of using the wrong reagents?",a="Maurin warns that the wrong reagents could cause deaths. The demon lord may have contingency spells meant to slay anyone who tries to scry on him.",al={"why the right scalp","wrong reagents risk","contingency spells"}},{q="Where does this step fit into the search for the demon lord?",a="This follows the first part of The Corrupter, when you brought the flayed demon skin to Maurin.",al={"chain progression","quest order","what comes before this"}}},kw={"desolace","hatefury shadowstalker","maurin bonesplitter","sargeron","satyr","scrying","shadowstalker scalp","the corrupter"},rel={"quest:1480","npc:maurin-bonesplitter","subzone:sargeron","zone:desolace","topic:satyr"},m={start="Maurin Bonesplitter",["end"]="Maurin Bonesplitter",level="33",faction="Horde",id=1481,ri={"Shadowstalker Scalp"}},src={"The Corrupter (2)"}}
E["quest:1482"] = {t="quest",n="The Corrupter",z="desolace",s="Maurin Bonesplitter seeks an oracle crystal to find the demon lord Azrethoc. Northwest along the coast, the Slitherblade naga dwell in a vast coral reef, and they will take your intrusion badly.",h="Maurin Bonesplitter seeks an oracle crystal to find the demon lord Azrethoc.",sec={{t="An Oracle Crystal",b="Maurin Bonesplitter needs an oracle crystal to find the demon lord Azrethoc. The skin you brought him bore Azrethoc's signature. Naga craft these crystals for their oracles, who dwell in a vast coral reef northwest along the coast. The Slitherblade naga live there near the shore. They are deadly and will take your intrusion badly, so Maurin urges you to move carefully and quickly.",sp=0},{t="A Shared Prize",b="Maurin says finding and destroying Lord Azrethoc would earn you both much favor with the Warchief. Working together and moving swiftly serves each of your aims.",sp=0}},faq={{q="Why does Maurin Bonesplitter need an oracle crystal?",a="So that Maurin Bonesplitter can find the demon lord Azrethoc.",al={"why oracle crystal","what is the crystal for","maurin crystal purpose"}},{q="Where are the oracle crystals found?",a="The naga craft oracle crystals for their oracles, who dwell in a vast coral reef northwest along the coast from Maurin.",al={"where to find crystal","oracle crystal location","where are slitherblade oracles"}},{q="Who are the Slitherblade?",a="The Slitherblade are naga who call a vast coral reef near the shore home. Maurin calls them deadly and says they will take intruders badly.",al={"what are slitherblade","slitherblade naga","who lives in the reef"}},{q="Who is Azrethoc?",a="Azrethoc is the demon lord whose signature was on the skin you brought Maurin. Maurin wants to find and destroy him.",al={"who is azrethoc","demon lord azrethoc","what demon is maurin hunting"}},{q="What motivates Maurin to hunt this demon?",a="The Warchief's favor: Maurin says finding and destroying Lord Azrethoc would earn you both a great deal of it.",al={"maurin motivation","why hunt azrethoc","warchief favor"}}},kw={"azrethoc","corrupter","desolace","maurin bonesplitter","naga","oracle crystal","slitherblade","warchief"},rel={"npc:maurin-bonesplitter","zone:desolace","topic:naga"},m={start="Maurin Bonesplitter",["end"]="Maurin Bonesplitter",level="35",faction="Horde",id=1482,ri={"Oracle Crystal"}},src={"The Corrupter (3)"}}
E["quest:1484"] = {t="quest",n="The Corrupter",z="desolace",s="Near Maurin Bonesplitter, the demon lord has proved more dangerous than he expected. Maurin believes Takata Steelblade doubts his skill, and that withholding what happened would dishonor Takata. So he sends you to speak with the swordsman nearby.",h="Near Maurin Bonesplitter, the demon lord has proved more dangerous than he expected.",sec={{t="A Matter of Honor",b="The demon lord has proved more dangerous than Maurin Bonesplitter expected. Maurin believes Takata Steelblade doubts he can handle the creature, and keeping Takata uninformed would insult the swordsman's honor.\n\nMaurin asks you to speak with Takata and offer to slay the demon, if Takata allows it. He cautions you not to press too hard, for he thinks Takata should believe the idea is his own.",sp=0},{t="Across the Path",b="Takata Steelblade is nearby, across the path from Maurin. He stands on a cliff overlooking the Kodo Graveyard.",sp=0},{t="Takata's Answer",b="Takata Steelblade witnessed what passed between Maurin and the demon lord. Though the creature was only an apparition, it seemed more powerful than Maurin, his warlock companion. Takata wonders whether Maurin can defeat it.\n\nTakata could better serve the Warchief by facing the demon himself. Yet his duties here keep him from leaving to fight for personal honor without disgracing his clan.",sp=1}},faq={{q="Why does Maurin Bonesplitter want Takata Steelblade told?",a="The demon lord has proved far more dangerous than Maurin Bonesplitter expected. Maurin believes Takata Steelblade doubts his abilities, and keeping the swordsman uninformed would insult Takata's honor.",al={"why talk to takata","maurin bonesplitter reason","why tell takata"}},{q="Where is Takata Steelblade located?",a="Takata Steelblade is nearby, across the path from Maurin, on a cliff overlooking the Kodo Graveyard in Desolace.",al={"takata location","where is takata","find takata steelblade"}},{q="Why does Maurin advise against pressing Takata too hard?",a="Maurin asks you to offer to slay the demon if Takata allows it, without pressing too hard. He thinks Takata should believe the idea is his own.",al={"why not press takata","handling takata","takata pride"}}},kw={"demon lord","desolace","kodo graveyard","maurin bonesplitter","swordsman","takata steelblade","the corrupter"},rel={"npc:maurin-bonesplitter","npc:takata-steelblade","subzone:kodo-graveyard","zone:desolace","topic:warlock"},m={start="Maurin Bonesplitter",["end"]="Takata Steelblade",level="33",faction="Horde",id=1484},src={"The Corrupter (4)"}}
E["quest:1488"] = {t="quest",n="The Corrupter",z="desolace",s="Takata Steelblade sides with Maurin: Lord Azrethoc must be stopped, especially if he seeks influence over the Burning Blade. Takata trusts you to gather a party against the demon lord and his warlock servant, Jugkar Grim'rod.",h="Takata Steelblade sides with Maurin: Lord Azrethoc must be stopped, especially if he seeks influence over the...",sec={{t="A Party to the South",b="Takata has never heard of Lord Azrethoc, but agrees with Maurin that the demon lord must be stopped. The danger grows if Azrethoc is trying to sway the Burning Blade. You have already shown that you want to aid the Warchief, so Takata trusts you to gather a party and slay Azrethoc and his warlock servant, Jugkar Grim'rod. Head directly south to Mannoroc Coven, where both are found.",sp=0},{t="Takata's Worry",b="Takata calls the demons in Desolace a greater threat than ever. Each newly arrived foul creature dims the prospect of returning to the Warchief. At times, Takata wishes the centaur were the only enemy.",sp=0},{t="Takata's Verdict",b="Once the threat is ended, Takata calls it a mighty victory for all. The outlook here is less bleak than Takata once feared. The demons are slain, the Burning Blade has failed in its efforts, and a place to call home is safe again.",sp=1}},faq={{q="Who is sending adventurers against Lord Azrethoc?",a="Takata Steelblade sides with Maurin and trusts you to gather a party against the demon lord.",al={"who gives the corrupter","quest giver the corrupter","takata steelblade quest"}},{q="Who must be defeated?",a="Lord Azrethoc, a demon lord, and Jugkar Grim'rod, his warlock servant, must be defeated.",al={"who do i kill","corrupter targets","azrethoc and jugkar"}},{q="Where are the targets located?",a="Takata says to head directly south to Mannoroc Coven in southern Desolace, where both are found.",al={"where is azrethoc","jugkar grimrod location","where to go the corrupter"}},{q="Why does Lord Azrethoc pose such a danger?",a="Takata has never heard of Azrethoc, but agrees that the demon lord must be stopped, especially if he is trying to sway the Burning Blade.",al={"why kill azrethoc","what is azrethoc doing","burning blade connection"}},{q="What comes before this in the chain?",a="This step follows the fourth part of The Corrupter chain.",al={"prerequisite quest","previous quest the corrupter","corrupter chain"}},{q="What does Takata fear about the demons in Desolace?",a="Takata calls the demons a greater threat than ever. Each newly arrived foul creature dims the prospect of returning to the Warchief, and Takata sometimes wishes the centaur were the only enemy.",al={"takata lore","why is takata here","takata steelblade role"}}},kw={"burning blade","demon","desolace","jugkar grim'rod","lord azrethoc","maurin","takata steelblade","warlock"},rel={"npc:takata-steelblade","zone:desolace","topic:horde","topic:warlock","topic:centaur","subzone:mannoroc-coven"},m={start="Takata Steelblade",["end"]="Takata Steelblade",level="40",faction="Horde",id=1488},src={"The Corrupter (5)"}}
E["quest:261"] = {t="quest",n="Down the Scarlet Path",z="desolace",s="At Nijel's Point, Brother Anton calls on you to prove your allegiance to the Scarlet Crusade.",h="At Nijel's Point, Brother Anton calls on you to prove your allegiance to the Scarlet Crusade.",sec={{t="Proof of Allegiance",b="Brother Anton says the Scourge must be stopped before it swallows the land and casts the world into darkness. The Scarlet Crusade has pledged itself to that fight. To prove your courage and allegiance, destroy thirty undead ravagers in the Valley of Bones, south of Anton. Succeed, and the Crusade will welcome you.",sp=0}},faq={{q="Who asks you to destroy the undead ravagers?",a="Brother Anton of the Scarlet Crusade asks you at Nijel's Point.",al={"who gives down the scarlet path","brother anton quest","scarlet crusade desolace npc"}},{q="Where are the undead ravagers found?",a="The undead ravagers are in the Valley of Bones, south of Nijel's Point in Desolace.",al={"undead ravager location","where is valley of bones","ravagers in desolace"}},{q="Why does Brother Anton want the ravagers destroyed?",a="Brother Anton says the Crusade fights the Scourge, which corrupts people and infects the land. He asks you to prove your allegiance.",al={"why kill undead ravagers","brother anton motive","scarlet crusade reason"}},{q="How many ravagers must be destroyed?",a="You must destroy thirty ravagers.",al={"how many ravagers","ravager count"}},{q="What comes before this?",a="You meet Brother Anton first.",al={"previous quest","prerequisite for down the scarlet path"}}},kw={"brother anton","desolace","down the scarlet path","nijel's point","scarlet crusade","scourge","undead ravager","valley of bones"},rel={"quest:6141","topic:scarlet-crusade","subzone:nijel-s-point","subzone:valley-of-bones","zone:desolace","topic:scourge"},m={start="Brother Anton",["end"]="Brother Anton",level="39",faction="Alliance",id=261},src={"Down the Scarlet Path"}}
E["quest:5381"] = {t="quest",n="Hand of Iruxos",z="desolace",s="At Shadowprey Village, Taiga Wisemane sends you to Thunder Axe Fortress for a Demon Box. The Burning Blade uses the Hand of Iruxos inside it to open portals for demons at Mannoroc Coven.",h="At Shadowprey Village, Taiga Wisemane sends you to Thunder Axe Fortress for a Demon Box.",sec={{t="The Box in the Fortress",b="Taiga Wisemane wants the demons' passage into our world stopped. She gives you a demon pick for the red crystal inside Thunder Axe Fortress. Use it to reach the Demon Box, then bring the box and pick back to Taiga in Shadowprey Village.",sp=0}},faq={{q="Who asks for the Demon Box?",a="Taiga Wisemane asks you for the Demon Box in Shadowprey Village.",al={"quest giver","who starts hand of iruxos","where to get quest"}},{q="What is the Hand of Iruxos?",a="The Hand of Iruxos is a powerful thing kept inside the Demon Box. At Mannoroc Coven, the Burning Blade uses it to open portals for demons.",al={"what is hand of iruxos","hand of iruxos artifact","what does the hand do"}},{q="Where is the Demon Box?",a="The Demon Box lies in Thunder Axe Fortress, beyond a red crystal.",al={"where is demon box","demon box location","find demon box"}},{q="How do you get to the Demon Box?",a="Taiga gives you a demon pick to use on the red crystal inside Thunder Axe Fortress.",al={"how to get demon box","demon pick use","red crystal thunder axe"}}},kw={"burning blade","demon box","demon pick","hand of iruxos","mannoroc coven","red crystal","shadowprey village","taiga wisemane","thunder axe fortress"},rel={"npc:taiga-wisemane","quest:5581","subzone:thunder-axe-fortress","subzone:shadowprey-village","subzone:mannoroc-coven","zone:desolace"},m={start="Taiga Wisemane",["end"]="Taiga Wisemane",level="38",faction="Horde",id=5381,ri={"Demon Box"}},src={"Hand of Iruxos (quest)"}}
E["quest:5386"] = {t="quest",n="Catch of the Day",z="desolace",s="At Ghost Walker Post, Nataka Longhorn is longing for cooked fish. She praises the trolls of Shadowprey Village as the finest fish-catchers, but centaur activity keeps her from making the journey. She asks you to bring her two Bloodbelly fish.",h="At Ghost Walker Post, Nataka Longhorn is longing for cooked fish.",sec={{t="A Taste of the Coast",b="At Ghost Walker Post, Nataka Longhorn has gone a long while without cooked fish. She trusts the trolls of Shadowprey Village to catch the finest fish, but centaur activity leaves her little time to travel. So she asks you to speak with Jinar'Zillen, the village's local fisherman, and bring back two Bloodbelly fish. They are Nataka's favorite. The road south of the post bends west toward the troll village.",sp=0}},faq={{q="Who is looking for Bloodbelly fish?",a="Nataka Longhorn at Ghost Walker Post in Desolace is looking for Bloodbelly fish. They are his favorite.",al={"who gives catch of the day","nataka longhorn quest"}},{q="Why can't Nataka Longhorn get the fish himself?",a="Centaur activity leaves Nataka little time to make the journey to the trolls.",al={"why can't nataka leave","why does nataka need help"}},{q="Where can the Bloodbelly fish be found?",a="Nataka sends you to Shadowprey Village to speak with its local fisherman, Jinar'Zillen.",al={"where to get bloodbelly fish","jinar'zillen location"}},{q="How do you reach Shadowprey Village from Ghost Walker Post?",a="The road south from Ghost Walker Post bends west and leads to the troll village.",al={"path to shadowprey village","how to get to troll village"}},{q="How many Bloodbelly fish does Nataka want?",a="Nataka wants two Bloodbelly fish.",al={"how many fish","bloodbelly fish count"}}},kw={"bloodbelly fish","catch of the day","centaur","desolace","ghost walker post","jinar'zillen","nataka longhorn","shadowprey village"},rel={"subzone:ghost-walker-post","subzone:shadowprey-village","quest:5421","zone:desolace","topic:troll","topic:centaur"},m={start="Nataka Longhorn",["end"]="Nataka Longhorn",level="37",faction="Horde",id=5386},src={"Catch of the Day"}}
E["quest:5421"] = {t="quest",n="Fish in a Bucket",z="desolace",s="In Shadowprey Village, Jinar'Zillen leaves the shellfish gathering to others. The traps lie below the docks, and he offers a Bloodbelly fish for every five shellfish.",h="In Shadowprey Village, Jinar'Zillen leaves the shellfish gathering to others.",sec={{t="Work Done by Someone Else",b="Jinar'Zillen keeps many shellfish traps below the docks of Shadowprey Village. He would rather someone else gather from them, and offers a fine Bloodbelly fish for every five shellfish brought in.",sp=0}},faq={{q="Who offers this trade?",a="Jinar'Zillen offers the trade in Shadowprey Village, in Desolace.",al={"who gives fish in a bucket","jinar'zillen","quest giver"}},{q="Where are the shellfish traps?",a="The shellfish traps lie below the docks of Shadowprey Village.",al={"trap location","where to find shellfish","shellfish traps"}},{q="Why does Jinar'Zillen want someone else to gather the shellfish?",a="Jinar'Zillen likes to do as little as possible, so he promises a return to anyone who gathers from the traps.",al={"why does he need shellfish","jinar'zillen motive"}},{q="What does Jinar'Zillen give in return for the shellfish?",a="Jinar'Zillen gives one fine Bloodbelly fish for every five shellfish.",al={"fish in a bucket reward","what do i get"}}},kw={"bloodbelly fish","desolace","fish in a bucket","jinar'zillen","shadowprey village","shellfish"},rel={"subzone:shadowprey-village","zone:desolace"},m={start="Jinar'Zillen",["end"]="Jinar'Zillen",level="25",faction="Horde",id=5421,ri={"Shellfish"}},src={"Fish in a Bucket"}}
E["quest:5501"] = {t="quest",n="Bone Collector",z="desolace",s="At Kormek's Hut in Desolace, Bibbly F'utzbuckle is waiting on ten more kodo bones. A caravan is due any moment, and the goblin expects the bones to change the world.",h="At Kormek's Hut in Desolace, Bibbly F'utzbuckle is waiting on ten more kodo bones.",sec={{t="Fortune in Old Bones",b="Bibbly F'utzbuckle sees a fortune in the kodo bones around the hut. Customers turn them into furniture, musical instruments, and even blasting powder. So Bibbly sends you south to the Kodo Graveyard for ten bones, promising something in return.",sp=0},{t="A Caravan on the Way",b="A caravan comes by Kormek's Hut to collect Bibbly's kodo bones. It sells them at Shadowprey Village, and it is due any moment. Bibbly is ten bones short of a career high.",sp=0},{t="Bibbly's Big Dreams",b="When the bones arrive, Bibbly imagines the chaps back home seeing Bibbly's face across Goblin'preneur. Then they will know Bibbly has become the richest goblin in the world. A physical education teacher once said Bibbly would never amount to anything.",sp=1}},faq={{q="Who is Bibbly F'utzbuckle?",a="Bibbly F'utzbuckle is a goblin at Kormek's Hut in Desolace who sees a fortune in kodo bones and seeks ten more.",al={"who gives bone collector","bibbly futzbuckle","kormek hut goblin"}},{q="Why does Bibbly need kodo bones?",a="Bibbly's customers make furniture, musical instruments, and even blasting powder from kodo bones.",al={"what are kodo bones used for","why kodo bones"}},{q="Where do the kodo bones go after Bibbly gets them?",a="A caravan collects Bibbly's kodo bones and sells them at Shadowprey Village.",al={"where do the bones go","caravan destination"}},{q="Where can the kodo bones be found?",a="The Kodo Graveyard lies south of Kormek's Hut in Desolace. Bibbly sends you there to gather bones.",al={"kodo bone location","where to find kodo bones"}},{q="Where is Kormek's Hut?",a="Kormek's Hut is in Desolace, north of the Kodo Graveyard.",al={"kormeks hut location","where is bibbly"}}},kw={"bibbly f'utzbuckle","bone collector","desolace","goblin'preneur","kodo bone","kodo graveyard","kormek's hut","shadowprey village"},rel={"subzone:kodo-graveyard","subzone:kormek-s-hut","subzone:shadowprey-village","zone:desolace","topic:goblin"},m={start="Bibbly F'utzbuckle",["end"]="Bibbly F'utzbuckle",level="39",faction="Neutral",id=5501,ri={"Kodo Bone"}},src={"Bone Collector"}}
E["quest:5561"] = {t="quest",n="Kodo Roundup",z="desolace",s="At Scrabblescrew's Camp, five tamed kodos are needed for a caravan due soon. You take Smeed Scrabblescrew's kodo kombobulator among Desolace's ancient, aged and dying kodos, then lead each tamed beast back to camp.",h="At Scrabblescrew's Camp, five tamed kodos are needed for a caravan due soon.",sec={{t="A Caravan on Its Way",b="A caravan is due at Scrabblescrew's Camp shortly, and Smeed Scrabblescrew says it depends on him. Bibbly thinks no other goblin in Desolace knows how to make a profit. Smeed disagrees. He has formed a partnership with Cork and Rigger, and the caravan is willing to brave this land.",sp=0},{t="The Kodo Kombobulator",b="Smeed built the kodo kombobulator to revive aged and dying kodos and bring them under control. Aim it at an ancient, aged or dying kodo, and the device jolts the beast into a tamed kodo that follows you. Bring five kodos and the device back to Scrabblescrew's Camp.",sp=0}},faq={{q="Who is Smeed Scrabblescrew?",a="Smeed Scrabblescrew is at Scrabblescrew's Camp in Desolace. He invented the kodo kombobulator and partnered with Cork and Rigger. Bibbly thinks no other goblin in Desolace knows how to make money, but Smeed disagrees.",al={"who is smeed","smeed scrabblescrew lore","scrabblescrew"}},{q="Why does Smeed need tamed kodos?",a="Smeed is waiting for five newly tamed kodos. The caravan that depends on him is due at Scrabblescrew's Camp shortly.",al={"why tame kodos","kodo roundup purpose","why does smeed want kodos"}},{q="What is the Kodo Kombobulator?",a="Smeed built the kodo kombobulator to revive aged or dying kodos and bring them under control. It jolts a targeted beast into a tamed kodo that follows you.",al={"what does kombobulator do","kodo kombobulator lore"}},{q="Which kodos can you use the kombobulator on?",a="You can use the kodo kombobulator on ancient, aged and dying kodos. Once tamed, each kodo follows you back to Scrabblescrew's Camp.",al={"which kodos to tame","kodo roundup kodos"}},{q="Who is Bibbly?",a="Bibbly is a goblin in Desolace who thinks no other goblin there knows how to make money. Smeed Scrabblescrew disagrees.",al={"bibbly rival","who is bibbly"}}},kw={"bibbly","cork","desolace","kodo","kodo kombobulator","rigger","scrabblescrew's camp","smeed scrabblescrew"},rel={"zone:desolace","topic:goblin"},m={start="Smeed Scrabblescrew",["end"]="Smeed Scrabblescrew",level="34",id=5561},src={"Kodo Roundup"}}
E["quest:5581"] = {t="quest",n="Portals of the Legion",z="desolace",s="At Mannoroc Coven, six demon portals threaten to widen the flow of demons into this world. Taiga Wisemane asks you to close them from Shadowprey Village.",h="At Mannoroc Coven, six demon portals threaten to widen the flow of demons into this world.",sec={{t="Closing the Gates",b="From Shadowprey Village, Taiga Wisemane gives you the Hand of Iruxos. She says you need to carry it to Mannoroc Coven and banish the portals there. The demon threat is growing, and each portal you close limits how many demons cross into this world. She wants all six banished. Beware their guardians.",sp=0}},faq={{q="Where are the demon portals?",a="The demon portals are at Mannoroc Coven in Desolace.",al={"portal location","where is mannoroc coven","where are the legion portals"}},{q="What is needed to banish the portals?",a="You need the Hand of Iruxos to banish the portals. Taiga Wisemane says you must possess it.",al={"how to banish portals","what item closes portals","hand of iruxos use"}},{q="Who asks you to banish the portals?",a="Taiga Wisemane asks you to banish the portals from Shadowprey Village.",al={"quest giver","who gives portals of the legion","taiga wisemane location"}},{q="How many portals must be banished?",a="You must banish six portals at Mannoroc Coven.",al={"how many portals","portal count"}},{q="What came before this?",a="Before this, Taiga Wisemane sent you to Thunder Axe Fortress for the Demon Box in Hand of Iruxos.",al={"previous quest","prereq","prerequisite"}}},kw={"demon portals","desolace","hand of iruxos","legion","mannoroc coven","shadowprey village","taiga wisemane"},rel={"quest:5381","npc:taiga-wisemane","subzone:mannoroc-coven","subzone:shadowprey-village","zone:desolace"},m={start="Taiga Wisemane",["end"]="Taiga Wisemane",level="38",faction="Horde",id=5581},src={"Portals of the Legion (Classic)"}}
E["quest:5741"] = {t="quest",n="Sceptre of Light",z="desolace",s="At Thunder Axe Fortress, the Burning Blade has the Sceptre of Light, said to have come from the naga. Azore Aldamort fears it can sink whole cities beneath the great seas, so he asks you to bring it to Ethel Rethor.",h="At Thunder Axe Fortress, the Burning Blade has the Sceptre of Light, said to have come from the naga.",sec={{t="A Sceptre of the Naga",b="Word has spread that the Burning Blade at Thunder Axe Fortress holds the naga's Sceptre of Light. Legend says the sceptre can sink whole cities beneath the great seas. Azore Aldamort will not let the Burning Blade keep such power.",sp=0},{t="The Seer's Tower",b="A Burning Blade seer keeps the sceptre in a watchtower atop the fortress and studies it there. Azore asks you to take the sceptre from the seer and carry it back to the tower at Ethel Rethor.",sp=0}},faq={{q="What power does the Sceptre of Light possess?",a="Legend says the Sceptre of Light can sink whole cities beneath the great seas. Word is that the Burning Blade obtained it from the naga.",al={"what does sceptre of light do","sceptre of light lore","how powerful is sceptre of light"}},{q="Who currently holds the Sceptre of Light?",a="A Burning Blade seer keeps the Sceptre of Light in a watchtower at Thunder Axe Fortress and studies it there.",al={"who has the sceptre of light","where is sceptre of light","who drops sceptre of light"}},{q="Who asks for the Sceptre of Light?",a="Azore Aldamort, who is at the tower at Ethel Rethor, asks for the Sceptre of Light.",al={"who gives sceptre of light","where to pick up sceptre of light"}},{q="How did the Burning Blade get the sceptre?",a="Word is that the Burning Blade obtained the sceptre from the naga.",al={"how did burning blade get the sceptre","burning blade naga connection"}}},kw={"azore aldamort","burning blade","desolace","ethel rethor","naga","sceptre of light","seer","thunder axe fortress"},rel={"subzone:ethel-rethor","subzone:thunder-axe-fortress","quest:6027","topic:naga","zone:desolace"},m={start="Azore Aldamort",["end"]="Azore Aldamort",level="33",faction="Neutral",id=5741,ri={"Sceptre of Light"}},src={"Sceptre of Light (quest)"}}
E["quest:5763"] = {t="quest",n="Hunting in Stranglethorn",z="desolace",s="You carry Roon Wildmane's token north of Grom'gol Base Camp to Hemet Nesingwary in Stranglethorn. The tauren and dwarf once hunted together in Desolace.",h="You carry Roon Wildmane's token north of Grom'gol Base Camp to Hemet Nesingwary in Stranglethorn.",sec={{t="A Token Between Hunters",b="Roon Wildmane remembers hunting beside Hemet, a dwarf who came to Desolace to hunt great beasts. Hemet wielded a rifle with uncanny skill. For many days, the two hunted together and set aside the old enmity between their peoples.\n\nWhen Hemet left for Stranglethorn, Roon vowed to welcome him back for another hunt. Now Roon sends you with his kodo horn, a token Hemet will recognize. Find Hemet in Stranglethorn, north of Grom'gol Base Camp.",sp=0},{t="Hemet's Answer",b="Hemet recognizes Roon Wildmane's kodo horn at once. He remembers the good hunting they shared among the beasts of Desolace and thanks you, though he is neck deep in the jungle for now. Hemet thinks his next expedition may lead back to Desolace, where the centaurs live.",sp=1}},faq={{q="Who is Hemet?",a="Hemet is a dwarf who came to Desolace to hunt great beasts. His rifle skill was uncanny, and he and Roon Wildmane hunted together for many days before Hemet left for Stranglethorn.",al={"hemet nesingwary","who is hemet"}},{q="Why does Roon Wildmane care about a dwarf?",a="Roon Wildmane and Hemet hunted together for many days, setting aside the enmity between their peoples. Roon vowed to welcome Hemet back so they could hunt again.",al={"why help dwarf","roon wildmane dwarf friend"}},{q="Where is Hemet located?",a="Hemet is in Stranglethorn, north of Grom'gol Base Camp.",al={"where is hemet","hemet location","stranglethorn hunting camp"}},{q="What is the purpose of the kodo horn?",a="Roon Wildmane sends the kodo horn to Hemet, who will recognize it as Roon's.",al={"kodo horn purpose","why deliver kodo horn"}}},kw={"desolace","grom'gol","hemet nesingwary","kodo horn","roon wildmane","stranglethorn"},rel={"zone:desolace","subzone:grom-gol-base-camp","topic:tauren","topic:dwarf","topic:centaur"},m={start="Roon Wildmane",["end"]="Hemet Nesingwary",level="31",faction="Horde",id=5763},src={"Hunting in Stranglethorn"}}
E["quest:5821"] = {t="quest",n="Bodyguard for Hire",z="desolace",s="In Desolace, Cork Gizelton and Rigger stop their kodo caravan at the sound of centaur war drums. Cork asks you to guard it past the Kolkar village, with payment waiting down the road.",h="In Desolace, Cork Gizelton and Rigger stop their kodo caravan at the sound of centaur war drums.",sec={{t="War Drums",b="Cork Gizelton and Rigger lead their kodo caravan past the Kolkar centaur. Then the war drums sound, and the caravan stops. Dead traders bring no profit, so Cork asks you to guard it a short distance past the Kolkar village and keep it safe. The caravan waits north of the Kolkar Village and southeast of Thunder Axe Fortress.",sp=0},{t="Smeed Scrabblescrew",b="Smeed Scrabblescrew waits with payment at Scrabblescrew's Camp, a little way down the road. Smeed does a little business with the Gizelton caravan.",sp=0}},faq={{q="Who is Cork Gizelton?",a="Cork Gizelton leads a kodo caravan through Desolace with Rigger. They stop whenever the centaur war drums sound.",al={"cork gizelton","who gives bodyguard for hire","who starts this"}},{q="Why does the caravan need protection?",a="The caravan needs protection because Cork and Rigger stop whenever the centaur war drums sound. Dead traders bring no profit.",al={"why need bodyguard","why caravan stopped","why are they waiting"}},{q="Where does this escort start?",a="The escort starts north of the Kolkar Village and southeast of Thunder Axe Fortress.",al={"bodyguard for hire location","where does caravan start","escort start point"}},{q="Where is the payment waiting?",a="Payment waits with Smeed Scrabblescrew at Scrabblescrew's Camp, a little way down the road. Smeed does a little business with Cork.",al={"who gives the reward","where do i turn in","who is smeed"}}},kw={"bodyguard","centaur","cork gizelton","desolace","gizelton caravan","kolkar","rigger","smeed scrabblescrew"},rel={"zone:desolace","topic:centaur","subzone:thunder-axe-fortress"},m={start="Cork Gizelton",["end"]="Smeed Scrabblescrew",level="35",faction="Neutral",id=5821},src={"Bodyguard for Hire"}}
E["quest:5943"] = {t="quest",n="Gizelton Caravan",z="desolace",s="At Mannoroc Coven, Rigger Gizelton asks you to guard his caravan. He and Cork set out to make a fortune, but trade has proved more dangerous than they expected.",h="At Mannoroc Coven, Rigger Gizelton asks you to guard his caravan.",sec={{t="Past Mannoroc Coven",b="Rigger Gizelton and Cork began their caravan hoping to make a fortune. They did not know how risky turning a profit could be. Mannoroc Coven lies ahead, where demons usually leave the caravan alone. This time, the kodos are spooked. Rigger offers payment if you guard the caravan past the coven. Once it is safely through, Smeed will pay you at Scrabblescrew's Camp.",sp=0},{t="Smeed's Misgivings",b="At Scrabblescrew's Camp, Smeed wipes his brow and says the caravan's disappearance would ruin him. He is glad to hear it is not lost. Yet he questions paying so much to protect a caravan whose owners earn only one gold piece a week. Still, Cork and Rigger keep paying him for his kodos. He does not care how they run their business.",sp=1}},faq={{q="Who is Rigger Gizelton?",a="Rigger Gizelton owns a caravan he started with Cork, hoping they would make a fortune.",al={"who is rigger","gizelton background","rigger gizelton"}},{q="Why does the caravan need protection past Mannoroc Coven?",a="Rigger says the demons at Mannoroc Coven usually leave the caravan alone, but something has the kodos spooked this time.",al={"why escort caravan","mannoroc coven danger","why protect caravan"}},{q="Who pays you for protecting the caravan?",a="Smeed, the Gizeltons' business associate at Scrabblescrew's Camp, pays you once the caravan is safely past the coven.",al={"who pays me","where to turn in gizelton caravan","smeed reward"}},{q="Who is Cork?",a="Cork is Rigger Gizelton's partner in the caravan.",al={"cork gizelton","who is cork"}}},kw={"caravan","cork","coven","desolace","gizelton","kodo","mannoroc","rigger","scrabblescrew","smeed"},rel={"subzone:mannoroc-coven","quest:5821","zone:desolace"},m={start="Rigger Gizelton",["end"]="Smeed Scrabblescrew",level="38",faction="Neutral",id=5943},src={"Gizelton Caravan (quest)"}}
E["quest:6027"] = {t="quest",n="Book of the Ancients",z="desolace",s="At the Ethel Rethor tower, Azore Aldamort entrusts you with the Gem of the Serpent. Set it on the Serpent Statue on Ranazjar Isle, northwest of the tower, and the guardian of the Book of the Ancients will appear.",h="At the Ethel Rethor tower, Azore Aldamort entrusts you with the Gem of the Serpent.",sec={{t="The Serpent Statue",b="After Sceptre of Light, Azore Aldamort gives you the Gem of the Serpent. Ranazjar Isle lies northwest of the Ethel Rethor tower, and there the Serpent Statue waits. Set the gem on its hand to call forth the Book of the Ancients’ guardian. The naga have kept the book’s secrets for centuries, and Azore hopes it will teach much about their scaled foes.",sp=0}},faq={{q="Who is Azore Aldamort?",a="Azore Aldamort keeps the tower at Ethel Rethor. Azore hopes to learn much about the naga, whom Azore calls scaled foes.",al={"azore aldamort","who gives book of the ancients","tower in ethel rethor guy"}},{q="What is the Book of the Ancients?",a="The Book of the Ancients holds secrets the naga have kept for centuries. Someone guards it.",al={"what is the book of the ancients","book lore","naga book desolace"}},{q="Where is Ranazjar Isle?",a="Ranazjar Isle is a small island northwest of the Ethel Rethor tower.",al={"ranazjar isle location","where is ranazjar isle","where do i go with the gem"}},{q="What is the Gem of the Serpent for?",a="Set the Gem of the Serpent on the hand of the Serpent Statue on Ranazjar Isle to bring forth the guardian of the Book of the Ancients.",al={"gem of the serpent","serpent statue hand","how to summon guardian"}},{q="What came before this?",a="Sceptre of Light comes before this step.",al={"previous quest","sceptre of light chain","prerequisite"}}},kw={"azore aldamort","book of the ancients","ethel rethor","gem of the serpent","naga","ranazjar isle","serpent statue"},rel={"quest:5741","subzone:ethel-rethor","topic:naga","zone:desolace"},m={start="Azore Aldamort",["end"]="Azore Aldamort",level="38",id=6027,ri={"Book of the Ancients"}},src={"Book of the Ancients (quest)"}}
E["quest:6132"] = {t="quest",n="Get Me Out of Here!",z="desolace",s="In the Valley of Spears, Melizza Brimbuzzle fears the Maraudines mean to eat her. She asks you to get her out, and her brother Hornizz promises good pay.",h="In the Valley of Spears, Melizza Brimbuzzle fears the Maraudines mean to eat her.",sec={{t="Trouble in the Valley",b="Melizza Brimbuzzle came to the Valley of Spears hoping to strike a deal with the Maraudines. They would not talk, and now she fears they mean to eat her. Minutes ago, she overheard centaurs discussing wood for their cookpot. She wants to leave quickly.",sp=0},{t="Her Brother's Camp",b="Hornizz Brimbuzzle waits at the family camp east of Melizza's present position. It lies beside the kodo graveyard. Melizza promises her brother will pay you well if you bring her out of the valley.",sp=0},{t="Back at the Camp",b="Hornizz says Melizza told him you were coming. He thanks you for getting her out of trouble, then guesses she has already found herself another. Melizza hurries ahead and says the Maraudines are too hard to work with. She heads for the Gelkis, whom she calls more reasonable.",sp=1}},faq={{q="Why is Melizza Brimbuzzle in trouble?",a="Melizza went to the Valley of Spears hoping to do business with the Maraudines. They would not talk, and she fears they mean to eat her.",al={"why is melizza captured","melizza brimbuzzle story","what happened to melizza"}},{q="Who are the Maraudines?",a="The Maraudines are centaurs of Desolace. Melizza went to the Valley of Spears hoping to do business with them.",al={"maraudine centaur","who are maraudines","maraudine clan"}},{q="Where is Hornizz Brimbuzzle located?",a="Hornizz Brimbuzzle waits at the Brimbuzzles' camp in Desolace, beside the Kodo Graveyard and east of Melizza's present position.",al={"hornizz location","where is hornizz","hornizz brimbuzzle camp"}},{q="Why does Melizza say her brother will pay you?",a="Melizza promises her brother Hornizz will pay you well if you get her out of the valley.",al={"melizza reward","what does hornizz pay"}}},kw={"centaur","desolace","hornizz brimbuzzle","kodo graveyard","maraudine","melizza brimbuzzle","valley of spears"},rel={"subzone:valley-of-spears","subzone:kodo-graveyard","topic:centaur","zone:desolace"},m={start="Melizza Brimbuzzle",["end"]="Hornizz Brimbuzzle",level="39",id=6132},src={"Get Me Out of Here!"}}
E["quest:6134"] = {t="quest",n="Ghost-o-plasm Round Up",z="desolace",s="Hornizz Brimbuzzle sends you into the Valley of Bones for ghost energy, hoping the Magram will pay well for it.",h="Hornizz Brimbuzzle sends you into the Valley of Bones for ghost energy, hoping the Magram will pay well for...",sec={{t="A Haunted Valley",b="Hornizz Brimbuzzle sends you southeast to the Valley of Bones, where Magram ghosts walk. The valley sounds frightening to him. Yet he thinks the spirits must frighten the Magram even more, and he is sure the centaurs would pay well for ghost energy captured there.",sp=0},{t="Between the Dead Goliaths",b="Hornizz Brimbuzzle gives you a crate of ghost magnets. Set one between the two huge skeletons called the Dead Goliaths, and it draws the ghosts toward it. The spirits yield ghost-o-plasm, which Hornizz plans to sell to the Magram. He asks you to bring him eight ghost-o-plasms and the crate.",sp=0},{t="Back with the Haul",b="Hornizz Brimbuzzle sees ghost-o-plasm rubbed onto you when you return and calls it slimy. He reckons it could make a fortune if the centaurs can be persuaded of what it is.",sp=1}},faq={{q="Who is Hornizz Brimbuzzle?",a="Hornizz Brimbuzzle keeps a camp southwest of the Kodo Graveyard in Desolace. He wants to sell ghost energy to the Magram centaurs.",al={"hornizz","brimbuzzle","who gives ghost-o-plasm round up"}},{q="Where is the Valley of Bones?",a="The Valley of Bones lies southeast of Hornizz Brimbuzzle. The two Dead Goliaths stand at the valley's southern end. They are the great skeletons where you set the magnet.",al={"valley of bones location","where do i find the ghosts","dead goliaths location"}},{q="Why does Hornizz want ghost-o-plasm?",a="Hornizz Brimbuzzle believes the Magram centaurs will pay well for ghost energy captured in the haunted Valley of Bones. He plans to sell them ghost-o-plasm.",al={"why collect ghost energy","who buys ghost-o-plasm","centaur ghost plasma"}},{q="How does the ghost magnet work?",a="Set a ghost magnet between the two Dead Goliaths, and it draws the valley's ghosts toward it. The spirits yield ghost-o-plasm.",al={"how to use ghost magnet","where to place ghost magnet","attracting magram ghosts"}}},kw={"dead goliaths","desolace","ghost magnet","ghost-o-plasm","hornizz brimbuzzle","magram","spectres","valley of bones"},rel={"zone:desolace","subzone:valley-of-bones","subzone:kodo-graveyard","subzone:mannoroc-coven","topic:centaur"},m={start="Hornizz Brimbuzzle",["end"]="Hornizz Brimbuzzle",level="39",faction="Neutral",id=6134,ri={"Ghost-o-Plasm"}},src={"Ghost-o-plasm Round Up"}}
E["quest:6142"] = {t="quest",n="Clam Bait",z="desolace",s="At Shadowprey Village, Mai'Lahii trusts one bait above all others. He asks for ten pieces of soft-shelled clam meat from the wrecked ship north along the coast.",h="At Shadowprey Village, Mai'Lahii trusts one bait above all others.",sec={{t="The Best Bait",b="Mai'Lahii asks you for bait fish cannot resist. He has fished all his life and trusts soft-shelled clam meat above all else. North of Shadowprey Village, a wrecked ship lies off the coast, and soft-shelled clams are scattered throughout the area. He wants ten pieces of the meat.",sp=0},{t="What Mai'Lahii Says",b="Mai'Lahii says the witch doctor told him to go fishing for his headache and that he would feel better. He feels better already.",sp=1}},faq={{q="Who is Mai'Lahii?",a="Mai'Lahii is a fisherman in Shadowprey Village on the Desolace coast. She has fished all her life.",al={"mailahii","who asks for clam bait","fisherman in shadowprey"}},{q="Where can the soft-shelled clams be found?",a="Soft-shelled clams are scattered around a wrecked ship north of Shadowprey Village, off the coast.",al={"clam bait location","where is the shipwreck","soft-shelled clam meat location"}},{q="Why does Mai'Lahii want clam meat?",a="Mai'Lahii says soft-shelled clam meat is the best bait, and fish cannot resist it.",al={"why clam bait","why clam meat"}},{q="How much clam meat does Mai'Lahii want?",a="Mai'Lahii wants ten pieces of soft-shelled clam meat.",al={"how many clams","clam meat amount"}}},kw={"clam bait","desolace","fishing bait","mai'lahii","shadowprey village","shipwreck","soft-shelled clam"},rel={"subzone:shadowprey-village","zone:desolace"},m={start="Mai'Lahii",["end"]="Mai'Lahii",level="35",faction="Horde",id=6142,ri={"Soft-Shelled Clam Meat"}},src={"Clam Bait"}}
E["quest:6143"] = {t="quest",n="Other Fish to Fry",z="desolace",s="At Shadowprey Village, Drulzegar Skraghook asks you to strike back at the Slitherblade. Naga took the fishing crew near Ranazjar Isle, and Drulzegar alone returned.",h="At Shadowprey Village, Drulzegar Skraghook asks you to strike back at the Slitherblade.",sec={{t="A Crew Lost",b="Drulzegar Skraghook and the crew often fished near Ranazjar Isle. The isle lies north of a wreck on the coast. One morning, the naga attacked and killed everyone but Drulzegar. Now revenge fills Drulzegar's thoughts, and guilt is too much to bear.",sp=0},{t="Fry the Naga",b="Drulzegar asks you to slay seven Slitherblade Myrmidons, seven Slitherblade Naga and five Slitherblade Sorceresses. A bad knee keeps Drulzegar from joining you. The naga usually lurk far down among coral reefs beneath the waves, Drulzegar says. Your effort will be rewarded.",sp=0}},faq={{q="Who is Drulzegar Skraghook?",a="Drulzegar Skraghook is a fisherman at Shadowprey Village in Desolace. The naga killed the whole crew near Ranazjar Isle, leaving Drulzegar as the only survivor.",al={"drulzegar","drulzegar skraghook","who gives other fish to fry"}},{q="Where did the attack on Drulzegar's crew happen?",a="The naga attacked beside Ranazjar Isle, north of a wreck on the coast. The crew often fished there, and the attack came one morning.",al={"where were the fishermen attacked","crew attack location","ranazjar isle ambush"}},{q="Why doesn't Drulzegar fight the naga himself?",a="A bad knee keeps Drulzegar from fighting the naga. Drulzegar says they would help you kill them if not for the injury. Guilt over the crew weighs heavily on Drulzegar's conscience.",al={"why cant drulzegar fight","drulzegar bad knee"}},{q="Where do the Slitherblade naga lurk?",a="Drulzegar says the Slitherblade naga usually lurk far down among coral reefs beneath the waves. The crew was attacked near Ranazjar Isle.",al={"slitherblade location","where to find slitherblade naga","naga location desolace"}},{q="Which naga does Drulzegar want eliminated?",a="Drulzegar wants seven Slitherblade Myrmidons, seven Slitherblade Naga and five Slitherblade Sorceresses slain.",al={"what naga need to be killed","other fish to fry targets","slitherblade requirements"}}},kw={"desolace","drulzegar","myrmidon","naga","other fish to fry","ranazjar isle","shadowprey village","skraghook","slitherblade","sorceress"},rel={"zone:desolace","topic:naga"},m={start="Drulzegar Skraghook",["end"]="Drulzegar Skraghook",level="36",faction="Horde",id=6143},src={"Other Fish to Fry"}}
E["quest:6161"] = {t="quest",n="Claim Rackmore's Treasure!",z="desolace",s="During Claim Rackmore's Treasure!, Rackmore's log tells of a ship attacked on its way to Feathermoon Stronghold. He hid his treasure chest on Ranazjar Isle to keep it from his enemies, but both keys to open it were lost.",h="During Claim Rackmore's Treasure!, Rackmore's log tells of a ship attacked on its way to Feathermoon...",sec={{t="A Hidden Chest",b="Rackmore's log tells of seafaring creatures attacking his ship on its way to Feathermoon Stronghold. He hid his treasure chest on Ranazjar Isle to keep it from his enemies. Both keys needed to open it were lost, one silver and one gold. Whoever finds the keys and the chest will find a treasure.",sp=0}},faq={{q="Where was Rackmore's ship sailing when it was attacked?",a="Rackmore's ship was on its way to Feathermoon Stronghold when seafaring creatures attacked it.",al={"rackmore destination","where was rackmore going","rackmore ship route"}},{q="Where is Rackmore's chest hidden?",a="Rackmore hid the chest on Ranazjar Isle.",al={"where is rackmore's chest","rackmore chest location","ranazjar isle chest"}},{q="What is needed to unlock the chest?",a="Two keys are needed to open the chest, one silver and one gold. Both were lost.",al={"rackmore chest keys","how to open rackmore's chest","what opens rackmore chest"}},{q="Why did Rackmore hide his treasure?",a="Rackmore hid the chest on Ranazjar Isle to keep his treasure from his enemies after seafaring creatures attacked his ship.",al={"why hide rackmore treasure","rackmore treasure motive"}}},kw={"chest","desolace","feathermoon stronghold","golden key","rackmore","ranazjar isle","silver key"},rel={"zone:desolace","subzone:feathermoon-stronghold-classic"},m={start="Rackmore's Log",["end"]="Rackmore's Chest",level="36",faction="Neutral",id=6161,ri={"Rackmore's Golden Key","Rackmore's Silver Key"}},src={"Claim Rackmore's Treasure!"}}
E["quest:6568"] = {t="quest",n="The Testament of Rexxar",z="desolace",s="Rexxar sends you to the Western Plaguelands with a message for Myranda the Hag. He needs her skill with illusions to pass the Black Flight's defenses.",h="Rexxar sends you to the Western Plaguelands with a message for Myranda the Hag.",sec={{t="The Art of Illusion",b="Rexxar needs an illusion to pass the Black Flight's defenses. So he sends you to Myranda the Hag, a master illusionist who lives in the Western Plaguelands. The Lordaeron alliance drove her out. She has helped Rexxar's kind before, when a cause seemed worthy. Now you carry his message to her.",sp=0},{t="A Visitor in Lordaeron",b="A member of the Horde is a rare sight in these parts of Lordaeron, Myranda says. Then she asks what you have brought her.",sp=0},{t="Myranda's Answer",b="Myranda holds the note, pauses, then smiles. She asks after Rexxar and explains that the page was blank on purpose. It held its writer's thoughts and intentions. She sees why Rexxar kept them from ink. The message would have been dangerous if you were captured or killed.\n\nMyranda agrees to help. She owes the Warchief a favor or two.",sp=1}},faq={{q="Who is Myranda the Hag?",a="Myranda the Hag is a master illusionist from Lordaeron, driven out by its alliance. She lives at Sorrow Hill in the Western Plaguelands.",al={"who is myranda","myranda the hag lore","where is myranda"}},{q="Why must you seek out an illusionist?",a="Rexxar needs an illusion to pass the Black Flight's defenses. He knows a master illusionist who may help.",al={"why disguise","why seek an illusionist","fooling the black dragonflight"}},{q="Where does Rexxar send you?",a="Rexxar sends you to the Western Plaguelands to find Myranda the Hag at Sorrow Hill.",al={"where do I go","where is sorrow hill","mistress of deception destination"}},{q="Has Myranda helped the Horde before?",a="Rexxar says Myranda has helped his kind before, whenever she found a cause worthy.",al={"does myranda like the horde","myranda alliance or horde","myranda favor warchief"}}},kw={"black dragonflight","desolace","illusion","mistress of deception","myranda the hag","rexxar","sorrow hill","testament of rexxar","western plaguelands"},rel={"subzone:sorrow-hill","zone:westernplaguelands","zone:desolace","topic:black-dragonflight","topic:lordaeron","topic:horde"},m={start="Rexxar",["end"]="Myranda the Hag",level="60",faction="Horde",id=6568},src={"Mistress of Deception"}}
E["quest:7029"] = {t="quest",n="Vyletongue Corruption",z="desolace",s="Vark Battlescar asks you to tend the corrupted plants in Maraudon. The orange crystal pool and Vylestem Vines are tied to the work.",h="Vark Battlescar asks you to tend the corrupted plants in Maraudon.",sec={{t="Vark’s Request",b="In Shadowprey Village, Vark Battlescar asks you to heal plants afflicted by corruption. He gives you a Coated Cerulean Vial to fill at the orange crystal pool in Maraudon. The vial is meant for the Vylestem Vines, where corrupted Noxxious Scions emerge.",sp=0},{t="The Plants",b="The Noxxious Scions are tied to healing the plants. After eight plants are healed, you can return to Vark Battlescar in Shadowprey Village.",sp=0}},faq={{q="What does Vark Battlescar ask me to do?",a="Vark Battlescar asks you to heal eight plants afflicted by corruption in Maraudon, then return to him in Shadowprey Village.",al={"Vark's plant task","Vark request","what do I do for Vark"}},{q="Where do I get the Cerulean Vial?",a="Vark Battlescar hands you the Coated Cerulean Vial, and you fill it at the orange crystal pool in Maraudon.",al={"cerulean vial location","where vial","orange pool"}},{q="What are the Vylestem Vines for?",a="Using the Filled Cerulean Vial on the Vylestem Vines brings out a corrupted Noxxious Scion.",al={"vylestem vines","vines purpose","vine vial"}},{q="How are the plants healed?",a="The plants are healed by killing the corrupted Noxxious Scions that emerge from the Vylestem Vines.",al={"heal plants","plant corruption","noxxious scion plants"}},{q="How many plants need healing?",a="Eight plants need healing before you return to Vark Battlescar.",al={"plant count","how many plants","eight plants"}},{q="Where is Vark Battlescar?",a="Vark Battlescar is in Shadowprey Village.",al={"Vark location","where is Vark","Shadowprey Vark"}}},kw={"cerulean vial","corrupted plants","maraudon","noxxious scion","orange crystal pool","shadowprey village","vark battlescar","vylestem vines","vyletongue corruption"},rel={"subzone:shadowprey-village"},m={faction="Horde",id=7029},src={"In-game quest text: Vyletongue Corruption"},fv=true}
E["quest:79229"] = {t="quest",n="Highway Robbery",z="desolace",s="In Desolace, a pillaged campsite holds clues to a violent attack. You seek someone who can make sense of what happened.",h="In Desolace, a pillaged campsite holds clues to a violent attack.",sec={{t="A Ransacked Camp",b="Two humans and a dwarf lie among the remains at a campsite in Desolace. The marks on their bones point to a savage attack, while the stolen supplies show that an animal was not responsible. Their wounds do not match centaur weapons either. You are asked to find someone in Desolace who knows these lands and can explain the signs.",sp=0}},faq={{q="Who was attacked at the campsite?",a="The remains indicate that two humans and a dwarf were attacked.",al={"who died at camp","campsite victims","humans and dwarf"}},{q="What happened at the campsite?",a="The campsite was pillaged, and the remains show signs of a savage attack.",al={"what happened here","pillaged camp","camp attack"}},{q="Was an animal responsible?",a="The looted supplies suggest the attack was not done by an animal.",al={"animal attack","beast did it","who attacked them"}},{q="Were the wounds made by centaurs?",a="The wounds do not match centaur weaponry.",al={"centaur attack","centaur weapons","did centaurs do it"}},{q="Who can explain the attack?",a="You are asked to find someone in Desolace experienced in scavenging these lands.",al={"who knows about camp","ask scavenger","who to find"}}},kw={"attack","campsite","centaur","desolace","dwarf","highway robbery","human","pillaged camp","scavenger"},rel={"zone:desolace","topic:centaur","topic:dwarf","topic:human"},m={id=79229},src={"In-game quest text: Highway Robbery"},fv=true}
E["quest:79235"] = {t="quest",n="On the Lam",z="desolace",s="A caravan rumor points to Horde marauders who fled Desolace after attacks on human and dwarf camps. You are sent toward Booty Bay to find one of them.",h="A caravan rumor points to Horde marauders who fled Desolace after attacks on human and dwarf camps.",sec={{t="A Trail to Booty Bay",b="A caravan contact describes attacks on human and dwarf camps in Desolace, then points you toward Booty Bay. The victims and the violence have led caravans to suspect Horde marauders. An Alliance marshal pursued the bandits, and they left Desolace. Now you are asked to find one of them.",sp=0}},faq={{q="Who attacked the camps?",a="Caravan rumor blames a group of Horde marauders for attacks on human and dwarf camps in Desolace.",al={"who did it","camp attackers"}},{q="Where did the marauders go?",a="The bandits fled Desolace after an Alliance marshal pursued them. Booty Bay is suggested as a place to look for one.",al={"where they flee","marauders location"}},{q="Why look in Booty Bay?",a="The contact suggests Booty Bay because people of doubtful character pass through its port, and a marauder might be seeking a boat.",al={"why booty bay","find marauder where"}},{q="What am I looking for?",a="You are looking for one of the marauders from Desolace.",al={"on the lam objective","find one"}}},kw={"alliance marshal","booty bay","caravans","desolace","horde","marauders","on the lam"},rel={"zone:desolace","subzone:booty-bay","topic:horde","topic:alliance","topic:human"},m={id=79235},src={"In-game quest text: On the Lam"},fv=true}
E["quest:92754"] = {t="quest",n="A New Need for Shadow Protection",z="desolace",s="Mirda needs Greater Shadow Protection Potions for Magram clanmates venturing south toward the Valley of Bones. Bring them to her in Magram Village while keeping the clan’s trust.",h="Mirda needs Greater Shadow Protection Potions for Magram clanmates venturing south toward the Valley of Bones.",sec={{t="Mirda's Request",b="Mirda in Magram Village needs you to bring her Greater Shadow Protection Potions. Magram clanmates are traveling farther south, toward and beyond the Valley of Bones. Mirda says the potions are needed to help keep them alive, and asks you to bring three while maintaining your standing with the clan.",sp=0}},faq={{q="Who is asking for the potions?",a="Mirda in Magram Village asks you to bring her Greater Shadow Protection Potions.",al={"who wants potions","Mirda request"}},{q="Why does Mirda need the potions?",a="Magram clanmates are venturing south toward and beyond the Valley of Bones, and Mirda says the potions are needed for their continued survival.",al={"why potions","shadow protection"}},{q="Where do I bring the potions?",a="Bring the potions to Mirda in Magram Village in Desolace.",al={"where Mirda","potions location"}},{q="How many potions does Mirda need?",a="Mirda asks for three Greater Shadow Protection Potions.",al={"number of potions","how many"}},{q="What does Mirda say about the clanmates' ventures?",a="Mirda does not trust you enough to share details about the clanmates' ventures.",al={"clanmates ventures","what are they doing"}},{q="What must I maintain with the Magram?",a="You need to maintain your reputation with the Magram while bringing the potions to Mirda.",al={"Magram standing","clan reputation"}}},kw={"clanmates","desolace","greater shadow protection potion","magram","magram village","mirda","shadow protection","valley of bones"},rel={"subzone:magram-village","subzone:valley-of-bones","zone:desolace"},m={id=92754},src={"In-game quest text: A New Need for Shadow Protection"},fv=true}
E["quest:92841"] = {t="quest",n="Valley of Bones",z="desolace",s="Warug sends you toward Orgrul, a centaur near the Valley of Bones south of Magram Village. The Magram’s discovery is at stake, and Warug says Orgrul will decide whether you learn of it.",h="Warug sends you toward Orgrul, a centaur near the Valley of Bones south of Magram Village.",sec={{t="Warug’s Direction",b="Warug sends you to the far end of Magram Village, where you are to seek Orgrul. He describes Orgrul as a large, foul-smelling centaur near the Valley of Bones, south of the village. You need the Magram to trust you before you can learn of their discovery.",sp=0}},faq={{q="Who is asking me to find Orgrul?",a="Warug asks you to seek Orgrul, a centaur near the Valley of Bones south of Magram Village.",al={"who sent me","warug request"}},{q="Where is Orgrul?",a="Orgrul is near the Valley of Bones south of Magram Village.",al={"orgrul location","where find orgrul"}},{q="What does Warug want me to learn?",a="Warug says the Magram have made a great discovery, but Orgrul will decide whether you learn what it is.",al={"magram discovery","what did they find"}},{q="Why do I need the Magram to trust me?",a="Warug says you need to earn the Magram’s regard before you can learn about their discovery.",al={"improve magram reputation","magram trust"}},{q="What happens if Orgrul refuses to tell me?",a="Warug says you can take comfort in knowing he has a new crown.",al={"warug crown","if orgrul says no"}}},kw={"centaur","discovery","magram","magram village","orgrul","valley of bones","warug"},rel={"subzone:valley-of-bones","subzone:magram-village","topic:centaur"},m={id=92841},src={"In-game quest text: Valley of Bones"},fv=true}
E["quest:93224"] = {t="quest",n="Carved Centaur Totems",z="desolace",s="Captain Pentigast at Nijel's Point seeks carved centaur totems to imitate their designs. He hopes the copies can help buy an advantage with the centaur clans.",h="Captain Pentigast at Nijel's Point seeks carved centaur totems to imitate their designs.",sec={{t="A Bargain in Wood",b="Captain Pentigast at Nijel's Point looks to the centaur clans' carved wood for a way to gain an advantage. Both clans hesitate to accept aid from outsiders, especially non-centaurs. He asks you to bring him samples of their designs so he can arrange similar carvings.",sp=0}},faq={{q="Why does Captain Pentigast want the totems?",a="He hopes to arrange similar carvings and buy an advantage with the centaur clans.",al={"why totems","pentigast's plan"}},{q="Why are the centaur clans hesitant to accept help?",a="Both clans hesitate to accept aid from outside their clan, especially from non-centaurs.",al={"why won't centaur accept aid","centaur distrust outsiders"}},{q="What are the centaur totems made of?",a="The local centaur barter with carved wood.",al={"totems material","carved wood"}},{q="Where does Captain Pentigast wait?",a="Captain Pentigast is at Nijel's Point.",al={"where is pentigast","nijel's point captain"}}},kw={"captain pentigast","carved centaur totems","carved wood","centaur","centaur clans","desolace","nijel's point","totems"},rel={"zone:desolace","subzone:nijel-s-point","topic:centaur"},m={faction="Alliance",id=93224},src={"In-game quest text: Carved Centaur Totems"},fv=true}
E["quest:93225"] = {t="quest",n="Carved Centaur Totems",z="desolace",s="Gurda Wildmane believes carved totems could help win the favor of the Gelkis or Magram. She needs authentic ones gathered from centaur clans across Desolace.",h="Gurda Wildmane believes carved totems could help win the favor of the Gelkis or Magram.",sec={{t="A Centaur Currency",b="Gurda Wildmane at Ghost Walker Post has watched centaur clans meet away from their settlements to trade. She has seen them use carved totems as currency. Now she thinks a large bundle might sway the Gelkis or Magram, but the totems she has carved may not pass as genuine. So she asks you to bring her authentic examples.",sp=0}},faq={{q="What does Gurda want?",a="Gurda Wildmane asks you to bring her authentic carved centaur totems.",al={"gurda request","what does wildmane need"}},{q="Why does she need carved totems?",a="Gurda believes a large bundle could help win the favor of the Gelkis or Magram.",al={"totems for what","why totems"}},{q="Where do centaur use the totems?",a="Gurda has seen centaur from different clans meet away from their settlements and trade with carved totems as currency.",al={"centaur trade","where totems"}},{q="Where can I find Gurda Wildmane?",a="Gurda Wildmane is at Ghost Walker Post.",al={"gurda location","wildmane at ghost walker"}},{q="Which centaur clans are involved?",a="Gurda hopes a bundle of totems could win favor with either the Gelkis or the Magram.",al={"gelkis magram","which clans"}}},kw={"carved centaur totems","centaur currency","desolace","gelkis","ghost walker post","gurda wildmane","magram"},rel={"zone:desolace","subzone:ghost-walker-post","topic:centaur","quest:93224"},m={faction="Horde",id=93225},src={"In-game quest text: Carved Centaur Totems"},fv=true}
E["quest:96222"] = {t="quest",n="Khan Hratha",z="desolace",s="Umarak wants a Maraudine Key Fragment from Khan Hratha as leverage for a negotiation. You are asked to challenge Hratha at the highest peak in the Valley of Spears.",h="Umarak wants a Maraudine Key Fragment from Khan Hratha as leverage for a negotiation.",sec={{t="Umarak’s Concern",b="War grips Desolace, yet the Maraudine centaur remain unchallenged in the Valley of Spears. Umarak fears that the other clans’ inaction may leave them bolder and stir more unrest. He wants the fragment Khan Hratha carries as a bargaining piece, and asks you to bring it back.",sp=0}},faq={{q="Who is asking for the Maraudine Key Fragment?",a="Umarak wants Khan Hratha’s Maraudine Key Fragment as a negotiation tactic.",al={"who wants the key fragment","umarak fragment"}},{q="Where are the Maraudine centaur?",a="The Maraudine centaur stand unchallenged in the Valley of Spears, in Desolace.",al={"where maraudine","centaur valley"}},{q="Why does Umarak want the fragment?",a="Umarak wants the Maraudine Key Fragment as leverage for a negotiation.",al={"why key fragment","what's it for"}},{q="What does Umarak fear?",a="Umarak fears the Maraudine may grow callous and stir further unrest if the other clans keep ignoring their presence.",al={"why worry about maraudine","what unrest"}},{q="What is Khan Hratha carrying?",a="Khan Hratha possesses a Maraudine Key Fragment.",al={"hratha item","what does khan have"}},{q="What does Umarak ask you to bring back?",a="Umarak asks you to bring him the Maraudine Key Fragment.",al={"what to bring umarak","fragment request"}}},kw={"centaur","desolace","key fragment","khan hratha","maraudine","umarak","valley of spears","war horn"},rel={"quest:1380","subzone:valley-of-spears","zone:desolace","topic:centaur"},m={id=96222},src={"In-game quest text: Khan Hratha"},fv=true}
E["quest:97265"] = {t="quest",n="Hate the Hatefury",z="desolace",s="Aka'rai in Shadowprey Village asks you to strike at the Hatefury satyr in Sargeron. His grievance comes from a bargain that left him seeking revenge.",h="Aka'rai in Shadowprey Village asks you to strike at the Hatefury satyr in Sargeron.",sec={{t="Aka'rai's Grievance",b="Aka'rai speaks of a bargain with a satyr that promised him power and knowledge. He says the Hatefury cast him aside, leaving him with less than before. Now he asks you to attack their camp northeast of Shadowprey Village, in Sargeron. Their blood is the price he seeks for his revenge.",sp=0},{t="The Blood Bargain",b="After the fighting, Aka'rai says one Hatefury escaped your assault. He names that satyr as the one who joined him in a ritual marked by spilled blood. The satyr holds Aka'rai's soulstone, so Aka'rai fears leaving Shadowprey Village while it remains in his hands. For now, he says your work is done.",sp=1}},faq={{q="Who is asking for help?",a="Aka'rai in Shadowprey Village asks you to attack the Hatefury satyr at Sargeron.",al={"who is aka'rai","aka rai","hatefury giver"}},{q="Why does Aka'rai want the Hatefury attacked?",a="Aka'rai says the Hatefury cast him aside after a bargain that promised power and knowledge.",al={"why hatefury","aka'rai revenge","satyr grudge"}},{q="Where are the Hatefury?",a="The Hatefury camp is at Sargeron in Desolace, northeast of Shadowprey Village.",al={"hatefury location","sargeron satyr","where camp"}},{q="What did Aka'rai bargain for?",a="Aka'rai says the bargain promised power, knowledge beyond ordinary tomes, and an eager minion.",al={"aka'rai deal","satyr bargain","power deal"}}},kw={"aka'rai","desolace","hate the hatefury","hatefury","sargeron","satyr","shadowprey village","soulstone"},rel={"subzone:sargeron","subzone:shadowprey-village","zone:desolace","topic:satyr"},m={faction="Horde",id=97265},src={"In-game quest text: Hate the Hatefury"},fv=true}
E["quest:97284"] = {t="quest",n="Vahlarriel's Vengeance",z="desolace",s="Vahlarriel asks you to strike the Burning Blade orcs at Thunder Axe Fortress. He fears they are ready for a fight and wants them to pay for their threat to Malem.",h="Vahlarriel asks you to strike the Burning Blade orcs at Thunder Axe Fortress.",sec={{t="A Score to Settle",b="Vahlarriel Demonslayer at Nijel's Point expects the Burning Blade orcs to be ready for you. He would rather you keep out of their way, but suspects they will seek a fight. So he asks you to kill as many as you can at Thunder Axe Fortress, then return to him.",sp=0},{t="After the Attack",b="When you return, Vahlarriel believes your attack may make the Burning Blade think twice before ransacking another caravan. He hopes they will stay behind their gates long enough to die out on their own.",sp=0}},faq={{q="Who is asking me to attack the Burning Blade?",a="Vahlarriel Demonslayer at Nijel's Point asks you to attack the Burning Blade at Thunder Axe Fortress.",al={"who is vahlarriel","vahlarriel vengeance","who wants the orcs dead"}},{q="Why does Vahlarriel want the Burning Blade attacked?",a="Vahlarriel suspects the orcs are ready to fight over Malem and wants them to pay for their threat.",al={"why kill burning blade","why is vahlarriel angry","burning blade reason"}},{q="Where are the Burning Blade orcs?",a="The Burning Blade orcs are at Thunder Axe Fortress in Desolace.",al={"where is thunder axe","burning blade location","orc fortress"}},{q="What does Vahlarriel fear the orcs will do?",a="Vahlarriel suspects the orcs expect someone to search for Malem and will be ready for a fight.",al={"malem danger","will orcs fight","burning blade threat"}},{q="What does Vahlarriel hope the attack will accomplish?",a="Vahlarriel hopes the Burning Blade will think twice before ransacking another passing caravan.",al={"why attack thunder axe","stop caravan raids","what does vahlarriel want"}}},kw={"burning blade","caravan","desolace","malem","nijel's point","thunder axe fortress","vahlarriel","vahlarriel demonslayer"},rel={"subzone:thunder-axe-fortress","subzone:nijel-s-point","zone:desolace","quest:1440"},m={faction="Alliance",id=97284},src={"In-game quest text: Vahlarriel's Vengeance"},fv=true}
E["subzone:bolgan-s-hole"] = {t="subzone",n="Bolgan's Hole",z="desolace",s="In southern Desolace, the Gelkis keep their power and sacred crystals within Bolgan's Hole. Their khan and shamans guard the cavern.",h="In southern Desolace, the Gelkis keep their power and sacred crystals within Bolgan's Hole.",sec={{t="The Gelkis Seat of Power",b="Above the Gelkis encampment, the khan holds court in a cavern cut into the bluffs. Veteran guards and influential shamans gather around their ruler. The cliffs defend the clan from its rivals, especially the Magram centaur to the east.",sp=0},{t="Tears of the Earth Princess",b="Blue crystals gleam in the damp stone walls of Bolgan's Hole. The Gelkis call them the tears of Theradras and honor them as sacred blessings. Their shamans harvest and guard the crystals. They believe the stones bring protection from Princess Theradras, the primal earth elemental mother of the centaur race.",sp=0}},faq={{q="Where is Bolgan's Hole located?",a="Bolgan's Hole lies in the southern cliffs of Gelkis Village, in southern Desolace.",al={"bolgans hole location","where is bolgan's hole","bolgan cave entrance"}},{q="Who lives inside Bolgan's Hole?",a="The cavern shelters the Gelkis clan's high leaders, including its khan, along with their protectors and shamans.",al={"who is in bolgan's hole","bolgans hole boss","gelkis khan location"}},{q="What are the glowing blue crystals inside the cave?",a="The glowing blue crystals are called the tears of Theradras. The Gelkis revere them as signs of their earth mother's favor and believe they protect whoever possesses them.",al={"blue crystals in bolgan's hole","tears of theradras","bolgan's hole rocks"}},{q="Can players enter Bolgan's Hole safely?",a="The Gelkis centaur inside are hostile to outsiders. Travelers who slaughter the Gelkis' hated rivals, the Magram clan, can earn enough standing to walk through the cavern in peace.",al={"is bolgan's hole hostile","friendly to gelkis","can i go inside bolgans hole"}}},ang={["class:Shaman"]="As a shaman, you can see how the Gelkis bind their worship of earth to Princess Theradras and the centaur race's violent legacy."},kw={"bolgan's hole","centaur","desolace","gelkis","khan shaka","tears of theradras"},rel={"subzone:gelkis-village","topic:centaur","zone:desolace"},src={"Bolgan's Hole"}}
E["subzone:ethel-rethor"] = {t="subzone",n="Ethel Rethor",z="desolace",s="Along Desolace's northwestern coast, Ethel Rethor's drowned halls lie beneath the sea. A sealed tower rises above the waves, while naga hold the sunken settlement.",h="Along Desolace's northwestern coast, Ethel Rethor's drowned halls lie beneath the sea.",sec={{t="A Drowned Relic",b="Ethel Rethor's broken stones line the coast of western Kalimdor. Before the Great Sundering, a night elven settlement stood here, but much of it has since fallen beneath the sea. Shattered foundations lie under the waves, and one weathered tower rises from the surf. A small bridge reaches its sealed portal, still closed against the elements and intruders. Naga now hold the drowned chambers and nearby shallows, making these waters dangerous to approach.",sp=0},{t="Watchers on the Shore",b="Travelers come to Ethel Rethor to study Kalimdor's forgotten history and watch its dangers today. Near the ruins, Azore Aldamort serves the Argent Dawn. He watches the naga and offers aid to those willing to dive into the sunken passages. The waters offshore are dangerous, and barren wastes stretch inland. So the ruins remain a lonely meeting place on the coast.",sp=0}},faq={{q="What is Ethel Rethor?",a="Ethel Rethor's ruined night elven settlement lies on Desolace's northwestern coast. Most of its former structures have sunk beneath the sea, leaving a solitary tower offshore and drowned stonework.",al={"ethel rethor lore","what is this place desolace","ethel rethor ruin"}},{q="Who controls Ethel Rethor now?",a="Naga occupy Ethel Rethor's sunken ruins and nearby reefs. They have claimed the drowned halls and patrol the surrounding shallows aggressively.",al={"who lives in ethel rethor","ethel rethor monsters","naga at ethel rethor"}},{q="Can you go inside the tower?",a="A small bridge leads to the tower's entrance, but the doorway is sealed shut. Travelers can explore its exterior and dive into the ruins beneath it.",al={"open ethel rethor tower","ethel rethor door","inside ethel rethor"}},{q="Why is the Argent Dawn here?",a="Azore Aldamort, an Argent Dawn representative, keeps watch near Ethel Rethor. Though the Dawn focuses on the Scourge in the east, its agents across Kalimdor monitor unusual magical disturbances, ancient ruins, and threats such as the naga.",al={"argent dawn in desolace","azore aldamor ethel rethor","argent dawn npc desolace"}}},ang={["race:NightElf"]="For night elves, Ethel Rethor is a somber monument to their lost empire and the cataclysmic Sundering. Mutated brethren now prowl its sunken halls.",["faction:Alliance"]="As an Alliance traveler crossing Desolace's hostile barrens, you can find a rare friendly face near the ruins: Azore Aldamort, an Argent Dawn observer."},kw={"argent dawn","azore aldamor","desolace","desolace coast","ethel rethor","kaldorei ruins","naga","sunken ruins"},rel={"zone:desolace","topic:naga","topic:argent-dawn","subzone:shadowprey-village"},src={"Ethel Rethor"}}
E["subzone:gelkis-village"] = {t="subzone",n="Gelkis Village",z="desolace",s="In southwestern Desolace, the earth-aligned Gelkis centaur clan holds its village and guards the southern route. Their ravine overlooks the north-south road, making passage perilous for travelers without the clan’s favor.",h="In southwestern Desolace, the earth-aligned Gelkis centaur clan holds its village and guards the southern...",sec={{t="A Fortress in the Ravine",b="Gelkis Village fills a deep gorge between steep bluffs and rope bridges. The Gelkis have made their ancestral grounds a lasting fortress, with outposts reaching toward the Feralas border. Khan Shaka leads the warriors from Bolgan's Hole, a cavern in the southern cliff face.\n\nTravelers heading south through Desolace must fight through the gorge or tread carefully. The Gelkis consider uninvited wanderers fair game in their endless war with rival centaur clans.",sp=0}},faq={{q="Who lives in Gelkis Village?",a="The Gelkis clan lives in the village, one of Desolace’s warring centaur tribes. They worship the earth and follow Khan Shaka, who resides in Bolgan's Hole, a cavern in the cliff.",al={"gelkis residents","who controls gelkis village","centaur village south"}},{q="Why are the Gelkis centaur hostile to outsiders?",a="The Gelkis are territorial and hostile toward outsiders, and they hate the rival Magram clan above all. Hunting Magram warriors can earn their trust and safe passage into the village.",al={"why are gelkis attacking","gelkis hostile","can i be friendly with gelkis"}},{q="Where is Gelkis Village located?",a="Gelkis Village lies in southwestern Desolace, just east and slightly south of Shadowprey Village, a troll settlement. Its ravines border the southern mountain face and overlook the trail leading south into Feralas.",al={"gelkis location","how to find gelkis village","where is gelkis"}},{q="What is Bolgan's Hole?",a="Bolgan's Hole is a large cavern in the ravine’s southern rock wall, linked to the village by elevated bridges and bluffs. It is the Gelkis Khan’s inner sanctuary and seat of power.",al={"bolgans hole","cave in gelkis village","where is gelkis khan"}}},ang={["race:Tauren"]="As a tauren, you know the centaurs have driven your people from their ancestral lands for generations. The Gelkis fortifications are a bitter reminder of their lasting threat to Kalimdor.",["faction:Horde"]="As a member of the Horde, you face the Gelkis’ fortified presence near Shadowprey Village, a Darkspear settlement on the coast directly to the west. The Gelkis remain a threat to nearby Horde operations."},kw={"bolgan's hole","centaur","desolace","feralas","gelkis","khan shaka","magram","shadowprey"},rel={"subzone:bolgan-s-hole","zone:desolace","topic:centaur","subzone:shadowprey-village","zone:feralas"},src={"Gelkis Village"}}
E["subzone:ghost-walker-post"] = {t="subzone",n="Ghost Walker Post",z="desolace",s="In central Desolace, Ghost Walker Post holds its ground beside the Kodo Graveyard. Tauren and orcs defend the Horde outpost from centaur clans and the Burning Blade, while its shamans tend dying kodos and their spirits.",h="In central Desolace, Ghost Walker Post holds its ground beside the Kodo Graveyard.",sec={{t="A Watch on the Wastes",b="Ghost Walker Post gives the Horde a foothold on central Desolace’s dusty flats. Centaur marauders and Burning Blade cultists roam nearby, keeping the post in danger. Its facilities offer only the bare essentials. There is no inn or flight master. Tauren guards and an orcish detachment sent by Warchief Thrall keep watch over the badlands.",sp=0},{t="Guardians of the Graveyard",b="Gurda Wildmane, a tauren shaman, leads Ghost Walker Post beside the Kodo Graveyard. Shamans tend the dying kodos who come there to perish. They ease the beasts into the next life and commune with their lingering spirits.\n\nThe post’s defenders stay ready against threats. Here, the tauren honor their ancient bond with the mighty kodo.",sp=0}},faq={{q="What is Ghost Walker Post?",a="Ghost Walker Post is a small, rugged Horde outpost in central Desolace, held mainly by tauren with support from an orcish garrison.",al={"ghost walker post info","what is this camp","horde camp desolace"}},{q="Who leads Ghost Walker Post?",a="Gurda Wildmane, a tauren shaman, leads Ghost Walker Post and tends its defenses and the neighboring Kodo Graveyard.",al={"who is in charge","ghost walker leader","gurda wildmane"}},{q="Why is the post located near the Kodo Graveyard?",a="Gurda Wildmane and fellow tauren shamans live at the post to ease dying kodos into the next life and commune with the spirits of fallen beasts.",al={"why by kodo graveyard","kodo spirits camp","shaman kodo graveyard"}},{q="What enemies does Ghost Walker Post fight?",a="The garrison fights hostile centaur clans and Burning Blade forces operating across Desolace.",al={"ghost walker enemies","who attacks ghost walker post","post threats"}},{q="Can I get a flight path or rest at an inn here?",a="No. Ghost Walker Post has neither an inn nor a flight master. Travelers must seek transport elsewhere, such as Shadowprey Village.",al={"flight master ghost walker","innkeeper ghost walker","fp here?"}},{q="How does it compare to Shadowprey Village?",a="Shadowprey Village is a protected troll enclave on Desolace’s western coast. Ghost Walker Post lies inland, exposed to nearby threats, and focuses on frontier defense and spiritual duties.",al={"shadowprey vs ghost walker","other horde camp desolace"}}},ang={["race:Tauren"]="As a tauren, you see your people’s sacred duty to the natural world in their guardianship beside the kodo’s ancestral resting grounds.",["class:Shaman"]="Under Gurda Wildmane, the shamans here speak with ancient spirits and ease dying beasts into the spirit world."},kw={"burning blade","centaur","desolace","ghost walker post","gurda wildmane","horde","kodo graveyard","shadowprey village","tauren","thrall"},rel={"zone:desolace","subzone:kodo-graveyard","subzone:shadowprey-village","topic:tauren","topic:horde","topic:centaur","npc:thrall","quest:4767"},src={"Ghost Walker Post"}}
E["subzone:kodo-graveyard"] = {t="subzone",n="Kodo Graveyard",z="desolace",s="In central Desolace, kodos make their way to Kodo Graveyard to die among their ancestors. Their bones cover a broad stretch of grey earth.",h="In central Desolace, kodos make their way to Kodo Graveyard to die among their ancestors.",sec={{t="Resting Place of Titans",b="Ancient bones lie across Kodo Graveyard, some from beasts far larger than any living kodo. When a kodo nears its end, it comes here to spend its last breaths among centuries of remains. Scavengers prowl the edges. Disturb the calcified ribs or skulls, and furious kodo spirits may rise from the dust.",sp=0},{t="A Land of Spirits",b="Restless spirits wander among Kodo Graveyard’s bones. Those who look into the spirit realm can see towering kodo apparitions moving silently through the dust storms. Nearby, the Horde keeps watch from Ghost Walker Post. They guard the sacred grounds and watch over the herds and spirits that linger among the bones.",sp=0}},faq={{q="Why do the kodos come here to die?",a="When kodos grow ancient, fall sick, or near death, instinct drives them across the waste to lie among their ancestors’ skeletons in this part of Desolace.",al={"why are there bones here","kodo dying grounds","why do kodos gather here"}},{q="Why are some of the skeletons so enormous?",a="Some skeletons are much larger than the living kodos nearby. Their exact age and origins remain unknown.",al={"giant kodo bones","huge kodo ribs","massive bones desolace"}},{q="What happens if someone disturbs the bones?",a="Disturbing the remains can provoke the dead. Vengeful kodo apparitions appear and attack those who scavenge or desecrate the resting place.",al={"looting kodo bones","kodo ghosts","bone collector quest"}},{q="What is Ghost Walker Post?",a="Ghost Walker Post is a small Horde camp beside the bone fields. Horde travelers can rest there, watch the region’s spiritual activity, and find guidance through central Desolace.",al={"horde camp near bones","ghost walker camp"}}},ang={["race:Tauren"]="As a tauren, you know the kodo as a revered partner and spiritual companion. Desecrating these ancestral resting grounds is a grave matter.",["profession:Herbalism"]="As an herbalist, you can gather Grave Moss around the large skeletons. The decaying remains and spiritual resonance enrich the ground."},kw={"desolace","ghost walker post","grave moss","kodo bones","kodo graveyard","kodo spirits"},rel={"zone:desolace","subzone:ghost-walker-post","topic:horde"},src={"Kodo Graveyard"}}
E["subzone:kormek-s-hut"] = {t="subzone",n="Kormek's Hut",z="desolace",s="Willow and Bibbly F'utzbuckle make their home at Kormek's Hut in north-central Desolace. The ramshackle dwelling shelters Willow, a peaceful cultist, and Bibbly, a goblin intent on harvesting kodo bones.",h="Willow and Bibbly F'utzbuckle make their home at Kormek's Hut in north-central Desolace.",sec={{t="A Strange Oasis of Oddities",b="In north-central Desolace, you may find Willow and Bibbly F'utzbuckle at Kormek's Hut. The name belongs to someone whose identity and whereabouts remain unknown. Willow sits inside, a member of the usually hostile and nihilistic Twilight's Hammer, yet she welcomes outsiders calmly.\n\nOutside, a pen strewn with sun-bleached kodo bones is Bibbly's dance floor and work site. The excitable goblin sees profit in gathering the bones.",sp=0}},faq={{q="Who is Kormek?",a="No one knows who Kormek was. The hut bears that name, but neither Willow nor Bibbly explains it, and Kormek is nowhere to be found in the wastes.",al={"who is kormek","kormek identity","where is kormek"}},{q="Why is there a friendly Twilight's Hammer cultist here?",a="Willow lives inside the hut and belongs to the Twilight's Hammer, a cult usually hostile to all mortal life. For reasons of her own, she does not attack travelers who visit the remote shelter.",al={"willow twilights hammer","why is willow friendly","willow hut"}},{q="What is the goblin outside doing?",a="Bibbly F'utzbuckle dances around a pen filled with kodo bones. He hopes to turn the ancient desert remains into profit.",al={"bibbly futzbuckle","goblin dancing desolace","why is the goblin dancing"}},{q="Where is Kormek's Hut located?",a="Kormek's Hut sits in north-central Desolace, in the dry flats north of the central crossroads and cemetery grounds.",al={"kormek hut location","where is kormek hut","kormek desolace"}}},kw={"bibbly f'utzbuckle","desolace","kodo bones","kormek","kormek's hut","twilight's hammer","willow"},rel={"zone:desolace","topic:twilight-s-hammer"},src={"Kormek's Hut"}}
E["subzone:magram-village"] = {t="subzone",n="Magram Village",z="desolace",s="In southeastern Desolace, the Magram hold their village amid foul yellow pools. They use it as a base in their war against the Gelkis, their hated rivals.",h="In southeastern Desolace, the Magram hold their village amid foul yellow pools.",sec={{t="A Stronghold in the Mire",b="Stagnant yellow pools ring the islands and shores where the Magram make their home in southeastern Desolace. Crude wooden bridges cross the mire, joining their hide tents. The clan keeps watch against its neighbors and is known for brutality and deep hatred of the southern Gelkis. Outsiders find no welcome unless they prove their worth by slaughtering Gelkis enemies.",sp=0}},faq={{q="Who lives in Magram Village?",a="The Magram clan lives in the village, one of several centaur tribes native to Desolace. They shelter beneath crude hide canopies on islands joined by rough footbridges.",al={"who is here","magram residents","centaur village"}},{q="Can I enter Magram Village without being attacked?",a="The Magram are hostile to outsiders at first. Travelers can earn their trust by hunting and killing their sworn enemies, the Gelkis, and raising their standing with the clan.",al={"are magram friendly","magram hostile","how to visit magram village"}},{q="Why are the pools around the village yellow?",a="Sulfur and mineral runoff taint the pools around the village. The stagnant water is discolored and polluted in Desolace's barren wastes.",al={"yellow water","polluted pools","magram water"}},{q="Why are the Magram fighting the Gelkis?",a="The Magram and Gelkis are bound by a legendary, bloodthirsty rivalry among the centaur clans. For generations, they have fought for dominance over Desolace's southern reaches.",al={"magram vs gelkis","centaur blood feud","centaur war"}}},ang={["race:Tauren"]="As a tauren, you know centaur savagery has plagued Kalimdor's tribes for generations. A settlement of these nomadic marauders recalls past bloodshed."},kw={"centaur","desolace","gelkis","magram","magram village","pools"},rel={"topic:centaur","zone:desolace"},src={"Magram Village"}}
E["subzone:mannoroc-coven"] = {t="subzone",n="Mannoroc Coven",z="desolace",s="Burning Blade cultists keep portals open at Mannoroc Coven in southern Desolace. They draw felhounds, succubi, and infernals into an ancient ruin, making it the Burning Legion’s largest stronghold in central Kalimdor.",h="Burning Blade cultists keep portals open at Mannoroc Coven in southern Desolace.",sec={{t="A Bastion of Fel Fire",b="Mannoroc Coven lies south of Ghost Walker Post and east of Shadowprey Village. Fel-tainted ruins cover an ancient night elf settlement. Lord Azrethoc commands the demons, while Jugkar Grim'rod leads the Burning Blade warlocks. Their portals draw doomguards, infernals, and felhounds into Kalimdor. Horde-aligned travelers use relics such as the Hand of Iruxos to sever the links, but new rifts keep opening in the scarred earth.",sp=1,bt={"q1480.4"}}},faq={{q="Why is this place called Mannoroc Coven?",a="The encampment takes its name from Mannoroth the Destructor. The pit lord subjugated the orcs with the blood curse and perished in Ashenvale.",al={"who is mannoroc","mannoroc name origin","why named mannoroc"}},{q="Who rules over the coven?",a="Lord Azrethoc leads the demons, while Jugkar Grim'rod directs the mortal cultists as a warlock of the Burning Blade.",al={"who leads mannoroc coven","mannoroc coven boss","azrethoc"},sp=1,bt={"q1480.4"}},{q="What ruins was the coven built upon?",a="The encampment occupies the crumbling stone foundations of an ancient night elf settlement. Those ruins stood long before demons filled the region with fel magic.",al={"what ruins are here","mannoroc ancient ruins","elf ruins desolace"}},{q="How are the demons arriving in Desolace?",a="Burning Blade cultists maintain summoning portals throughout the ruins. The portals draw continuous reinforcements from the Twisting Nether, frustrating outside attempts to cleanse the site for good.",al={"where do demons come from","burning blade portals desolace"}}},ang={["class:Warlock"]="As a warlock, you can study the coven’s concentrated fel energy and active Legion portals. Demons appear before your eyes.",["race:NightElf"]="As a night elf, you see your ancestors’ stonework desecrated and trampled by demons. It recalls the War of the Ancients."},kw={"azrethoc","burning blade","coven","desolace","felhounds","infernals","jugkar grim'rod","mannoroc"},rel={"zone:desolace","topic:burning-legion","subzone:ghost-walker-post","subzone:shadowprey-village","npc:taiga-wisemane","topic:night-elf"},src={"Mannoroc Coven"}}
E["subzone:nijel-s-point"] = {t="subzone",n="Nijel's Point",z="desolace",s="Alliance soldiers and Cenarion druids hold Nijel's Point above Desolace's harsh wastes. The outpost shelters travelers, researchers, and soldiers crossing the blighted valleys below.",h="Alliance soldiers and Cenarion druids hold Nijel's Point above Desolace's harsh wastes.",sec={{t="A Bastion Above the Wastes",b="Nijel's Point clings to cliffs along the Stonetalon Mountains, high above Desolace's gray dust and marauding centaur packs. Captain Pentigast commands a Stormwind Army detachment there. His soldiers watch the clan wars that threaten Alliance interests across southern Kalimdor. High cliffs and narrow trails make the outpost easy to defend.\n\nCouriers, scouts, and griffin riders use Nijel's Point as a staging ground on routes between Stonetalon Peak, Theramore, and Feathermoon Stronghold.",sp=0},{t="Cenarion and Crusade Expeditions",b="Stormwind soldiers share Nijel's Point with emissaries whose work takes them into danger. Keeper Marandis and his dryads use the camp as a base to confront Princess Theradras deep within Maraudon and recover the fallen demigod Zaetar. Brother Anton, an emissary of the Scarlet Crusade, seeks to scour the undead ravaging the valley floor. Even among the soldiers and druids on the ridge, Nijel's identity remains an ancient mystery.",sp=0}},faq={{q="Why is the Alliance stationed in Desolace?",a="Captain Pentigast leads a Stormwind Army detachment to watch the warring centaur clans. The Alliance fears that if one clan wipes out the others, the victors will turn against nearby territories and settlements such as Stonetalon and Feralas.",al={"why is alliance here","stormwind army in desolace","why nijels point exists"}},{q="Who was Nijel?",a="No one at the outpost seems to know who Nijel was. His history has been lost to time.",al={"who is nijel","nijel lore","who was nijels point named after"}},{q="What is the Cenarion Circle doing at Nijel's Point?",a="Keeper Marandis and his dryad sisters came to Desolace to purge Maraudon, slay Princess Theradras, and reclaim Zaetar's remains for the sacred groves of the Stonetalon Mountains.",al={"druids in nijels point","keeper marandis mission","why are dryads here"}},{q="Why is the Scarlet Crusade at Nijel's Point?",a="Brother Anton is a distant emissary of the Scarlet Crusade. Brother Crowley in Stormwind sends Alliance adventurers to him, where he tests their resolve against the undead ravagers in Desolace's Valley of Bones.",al={"brother anton scarlet crusade","scarlet crusade in desolace"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can use Nijel's Point as your sole fortified refuge and flight staging ground in Desolace. It links supply lines between Stonetalon, Theramore, and Feralas.",["class:Druid"]="As a druid, you can see Keeper Marandis use this mountain sanctuary to organize the recovery of Zaetar's remains from the corruption within Maraudon."},kw={"brother anton","centaur","desolace","marandis","maraudon","nijel's point","outpost","pentigast"},rel={"zone:desolace","topic:stormwind-army","topic:cenarion-circle","topic:centaur","zone:stonetalon","subzone:feathermoon-stronghold-classic","subzone:theramore-isle","topic:scarlet-crusade"},src={"Nijel's Point"}}
E["subzone:sar-theris-strand"] = {t="subzone",n="Sar'theris Strand",z="desolace",s="Along western Desolace, Sar'theris Strand's green shores meet the Veiled Sea. Its sunny grass stands apart from the grey wastes, though naga, sea giants, and makrura make the coast perilous.",h="Along western Desolace, Sar'theris Strand's green shores meet the Veiled Sea.",sec={{t="A Green Edge on a Grey Waste",b="Green clifftops and beaches mark Sar'theris Strand along western Desolace. They offer a bright respite from the ash and dust of the inland plains. Serpentine naga patrol the surf beside towering sea giants and territorial makrura. Wrecks mark the shoals: the ruined Karnitol vessel lies to the north, and small shattered skiffs rest beneath the towers of Ethel Rethor. The sea is as treacherous as the shore.",sp=0},{t="Wreckage and Rare Waters",b="Naga and sea giants are not the strand's only dangers. Jagged shallows hide salvage from lost expeditions and merchant ventures, while rare marine life dwells in the deep surf. Among it is the Sar'theris Striker, a fish sought by master fishermen across Kalimdor.",sp=0}},faq={{q="Why is Sar'theris Strand green when the rest of Desolace is dead?",a="Sar'theris Strand is sunny and grassy, unlike Desolace's barren grey interior. No reason for the contrast is given.",al={"why green coast","desolace coastline grassy","sar'theris weather"}},{q="What creatures inhabit Sar'theris Strand?",a="Amphibious Slitherblade naga, wandering sea giants, and scuttling makrura inhabit the strand. Their patrols roam near the water's edge, so watch the surf.",al={"who lives here","sar'theris mobs","what monsters are on the strand"}},{q="What shipwrecks lie along the shore?",a="The Karnitol Shipwreck lies in the strand's northern waters. Smaller vessels are smashed on the beach bluffs beneath the ruined elven towers of Ethel Rethor.",al={"karnitol shipwreck","sunken boats strand","beach wreckage"}},{q="Why do fishermen seek out Sar'theris Strand?",a="Fishermen seek Sar'theris Strand for the Sar'theris Striker, an elusive fish found only in these coastal waters. Renowned angler Nat Pagle recognizes it as one of fishing mastery’s ultimate tests.",al={"sar'theris striker","fishing coast desolace","nat pagle fish"}}},ang={["profession:Cooking"]="Sar'theris Strand's shores and waters offer marine game, including makrura and rare ocean fish. Watch for prowling naga when you light a cooking fire."},kw={"desolace","karnitol","makrura","sar'theris","strand","striker"},rel={"zone:desolace","subzone:ethel-rethor","topic:naga","npc:nat-pagle"},src={"Sar'theris Strand"}}
E["subzone:sargeron"] = {t="subzone",n="Sargeron",z="desolace",s="Hatefury satyrs hold Sargeron in northern Desolace, amid the ruins of an ancient night elf city. The city fell in the Great Sundering, and the satyrs defiled its temples of Elune before naming the ruins for their master, Sargeras.",h="Hatefury satyrs hold Sargeron in northern Desolace, amid the ruins of an ancient night elf city.",sec={{t="A Defiled Sanctuary",b="Sargeron once flourished around sacred grounds devoted to Elune. Before the War of the Ancients broke the continent, worshippers came to Elune's Temple, Sanctuary, and Cathedral. The city's true name is lost.\n\nWhen the world shattered, Sargeron fell into rubble, leaving relics among the stones, including the Cup of Elune, Elune's Brazier, and Elune's Handmaiden. For millennia, corrupted Hatefury satyrs have overrun the ruins. They made Kaldorei holy places a stronghold in honor of the titan Sargeras.",sp=0}},faq={{q="What was Sargeron called before the Sundering?",a="The city's original night elven name has been lost. Hatefury satyrs gave the ruins their present name, Sargeron, in homage to the fallen titan Sargeras.",al={"original name","sargeron original name","what was it called"}},{q="Who occupies Sargeron now?",a="Hatefury satyrs occupy the ruins. Spawned during the War of the Ancients, these corrupt demonic beings defile ancient elven sites.",al={"who lives here","sargeron mobs","enemies in sargeron"}},{q="What holy sites were originally located here?",a="The city held Elune's Temple, Elune's Sanctuary, and Elune's Cathedral. The holy sites once sheltered revered relics such as the Cup of Elune.",al={"elune temples","holy sites","what buildings were here"}},{q="Why is Sargeron significant to night elves?",a="Sargeron recalls the War of the Ancients and the defilement of Kaldorei holy places by demonic forces. Ancient elven artifacts remain there, at risk of loss or corruption.",al={"night elf lore sargeron","why do night elves care"}}},ang={["race:NightElf"]="As a Kaldorei, you see demonic satyrs defiling Elune's sacred altars and mocking the goddess in Sargeras's name.",["class:Priest"]="As a priest, you can recognize remnants of Elune's Cathedral and holy relics scattered across the broken stones. They call for purification."},kw={"cup of elune","desolace","elune","hatefury","kaldorei","sargeras","sargeron","satyr"},rel={"zone:desolace","topic:satyr","topic:elune","topic:sargeras","topic:night-elf","topic:war-of-the-ancients"},src={"Sargeron"}}
E["subzone:shadowbreak-ravine"] = {t="subzone",n="Shadowbreak Ravine",z="desolace",s="Burning Blade cultists and demons gather in Shadowbreak Ravine, southeast of Magram Village.",h="Burning Blade cultists and demons gather in Shadowbreak Ravine, southeast of Magram Village.",sec={{t="A Hidden Enclave of Fel",b="Among barren mountain ridges southeast of Magram Village, the ravine stays hidden from wandering centaur tribes. Strange oversized mushrooms rise beside grim ritual camps, where cultists work with summoned demons. Dark practitioners call on fel energies and tend heavy ritual chains. Here, the Burning Blade gathers reinforcements and holds a demonic foothold in Desolace.",sp=0}},faq={{q="What is Shadowbreak Ravine?",a="Shadowbreak Ravine lies in the mountains of southeastern Desolace, just beyond Magram Village. Demons and Burning Blade cultists use it as a concealed camp and staging ground.",al={"shadowbreak ravine info","what is this place","where is shadowbreak ravine"}},{q="Who occupies the ravine?",a="Burning Blade cultists share the ravine with demons. They perform dark rituals there and support the Burning Blade's wider offensive across the region.",al={"who lives here","shadowbreak ravine mobs","enemies in shadowbreak ravine"}},{q="What features can be found inside the ravine?",a="Dark ritual structures, heavy iron chains, and giant mushrooms fill the fel-tainted camps hidden among the mountain clefts.",al={"what is inside shadowbreak ravine","landmarks in shadowbreak ravine"}}},ang={["class:Warlock"]="As a warlock, you can see the Burning Blade's dark arts at work in the ravine's summoning circles and concentrated fel presence."},kw={"burning blade","cultists","demons","desolace","fel","shadowbreak ravine","magram village"},rel={"zone:desolace","subzone:magram-village","topic:centaur"},src={"Shadowbreak Ravine"}}
E["subzone:shadowprey-village"] = {t="subzone",n="Shadowprey Village",z="desolace",s="Along Sar'theris Strand, Darkspear fishermen and tauren keep Shadowprey Village alive as a Horde port on Desolace's rocky southern coast. Their work sustains trade across the barren region.",h="Along Sar'theris Strand, Darkspear fishermen and tauren keep Shadowprey Village alive as a Horde port on...",sec={{t="A Haven on the Strand",b="On Desolace's southern shore, Shadowprey Village clings to cliffs where centaur clans and the wastes leave few safe harbors. Troll fishermen make up most of the settlement. Their catches feed the village and inland posts such as Ghost Walker Post.\n\nWooden piers reach into the rough sea. From them, anglers fish deep water and dive for shellfish among the wrecks scattered along Sar'theris Strand.",sp=0},{t="Coastal Tribulations",b="A port on Desolace's frontier faces danger from land and sea. Marauding centaur and the demon-summoning Burning Blade threaten from inland. Rough shoals and hungry sea life challenge those who fish the coast.\n\nTauren allies help defend the village and keep trade routes open across Kalimdor. They include Taiga Wisemane and the keepers of the inn and wind rider roost.",sp=0}},faq={{q="Why is Shadowprey Village important to the Horde?",a="Desolace is an inhospitable wasteland with few natural resources, and Shadowprey Village is the Horde's only coastal port there. Its fish and shellfish feed garrisons such as Ghost Walker Post. Its wind rider hub connects to Stonetalon, Thunder Bluff, and Feralas.",al={"shadowprey purpose","why is shadowprey here","shadowprey horde role"}},{q="Who leads Shadowprey Village?",a="No single chieftain is recorded for Shadowprey Village. Troll fishermen form a loose community, while tauren residents such as Taiga Wisemane help guard it from the Burning Blade cultists stirring in Desolace.",al={"shadowprey leader","who is in charge of shadowprey"}},{q="Why are there tauren running the services in a troll village?",a="Shadowprey began as a Darkspear fishing outpost, and its work as a regional supply hub drew support from the wider Horde. Tauren oversee shared services. They keep the inn, manage the stables, and direct the wind rider roost connecting the port to Mulgore and beyond.",al={"tauren in shadowprey","why tauren here","shadowprey tauren"}},{q="What threats are troubling the fishermen?",a="Fishermen face hostile centaur inland and the Burning Blade, whose demon-summoning cultists hold Thunder Axe Fortress. Rough waters and dangerous sea life threaten them along the coast as well.",al={"shadowprey problems","shadowprey threats"}}},ang={["race:Troll"]="As a troll, you find a rare haven of Darkspear coastal culture at Shadowprey. Your people practice spearfishing, diving, and coastal survival there.",["faction:Horde"]="As a Horde traveler crossing Desolace, you find Shadowprey Village the only coastal rest stop, flight hub, and secure supply base south of the Kodo Graveyard."},kw={"desolace","sar'theris strand","shadowprey","shadowprey village","taiga wisemane","troll fishing"},rel={"zone:desolace","subzone:sar-theris-strand","subzone:ghost-walker-post","npc:taiga-wisemane","topic:troll","topic:tauren","topic:horde","zone:thunderbluff"},src={"Shadowprey Village"}}
E["subzone:thunder-axe-fortress"] = {t="subzone",n="Thunder Axe Fortress",z="desolace",s="Burning Blade cultists hold Thunder Axe Fortress in northwestern Desolace. They guard the wastes from its stone barracks and watchtowers, with darkened caves below.",h="Burning Blade cultists hold Thunder Axe Fortress in northwestern Desolace.",sec={{t="A Bastion of the Burning Blade",b="In northwestern Desolace, Burning Blade cultists keep watch over the wastes from Thunder Axe Fortress. Stone barracks and watchtowers fortify the compound, and deep caverns run beneath it. Far from Kalimdor’s major cities, the cult gathers fel energies and summons lesser demons. Its members scheme to bring more dangerous entities into the world.",sp=0},{t="Stolen Relics and Dark Summonings",b="The Hand of Iruxos lies at Thunder Axe Fortress, bound to the demonic portals of Mannoroc Coven. A Burning Blade seer studies the stolen Sceptre of Light atop a watchtower. Azore Aldamort asks travelers to recover it. Rumor says the naga once held the sceptre.",sp=1}},faq={{q="Who controls Thunder Axe Fortress?",a="The Burning Blade cult controls Thunder Axe Fortress. Its members serve demonic power and the remnants of the Shadow Council. Warlocks such as Tyranis Malem oversee the fortress and its operations.",al={"who runs thunder axe fortress","who is in thunder axe fortress","thunder axe fortress boss"},sp=1,bt={"q5726.3"}},{q="What is the Sceptre of Light?",a="The Sceptre of Light is an ancient artifact said to be able to sink entire cities beneath the sea. Azore Aldamort asks travelers to retrieve it from a Burning Blade seer studying it atop a watchtower at Thunder Axe Fortress.",al={"sceptre of light","scepter of light","stolen naga artifact"},sp=1},{q="How is this fortress connected to Mannoroc Coven?",a="Cultists at Thunder Axe Fortress hold the Hand of Iruxos, a relic directly linked to the demon portals active at Mannoroc Coven in southern Desolace. The artifact binds their demonic efforts across the zone.",al={"mannoroc coven connection","hand of iruxos"}}},ang={["class:Warlock"]="As a Warlock, you can see how recklessly the Burning Blade experiments with demonology. They bind lesser fiends and force planar rifts for greater entities.",["faction:Alliance"]="As an Alliance traveler, you can help the Argent Dawn secure dangerous artifacts like the Sceptre of Light before fel cultists turn them against the continent."},kw={"burning blade","desolace","hand of iruxos","kohor","sceptre of light","thunder axe fortress","tyranis malem"},rel={"zone:desolace","subzone:mannoroc-coven","topic:argent-dawn","topic:naga","topic:light"},src={"Thunder Axe Fortress"}}
E["subzone:valley-of-spears"] = {t="subzone",n="Valley of Spears",z="desolace",s="In western Desolace, the Maraudine guard their stronghold in the Valley of Spears. Beyond the valley lies Maraudon, the sacred burial ground of all centaurkind.",h="In western Desolace, the Maraudine guard their stronghold in the Valley of Spears.",sec={{t="Stronghold of the Maraudine",b="The Maraudine hold the Valley of Spears in western Desolace. On foot, you can enter only through narrow mountain passes from the south and east. Rocky chokepoints guard those approaches, while hostile nomad camps fill the way to the clan’s most revered holy site.",sp=0},{t="The Threshold of Maraudon",b="At the valley’s southwestern end, an entrance opens into Maraudon. The sacred cavern holds the tomb of Zaetar, father of the centaur, and Princess Theradras dwells within. The Maraudine defend the canyon fiercely from rival clans and outsiders. Gnome cartographer Melizza Brimbuzzle and scouts who wander in unaware may be captured or slain.",sp=0}},faq={{q="Who controls the Valley of Spears?",a="The Maraudine clan controls the Valley of Spears. It is their chief territory among the centaur factions fighting for dominance in Desolace.",al={"who lives here","valley of spears centaur clan","maraudine base"}},{q="Where does the Valley of Spears lead?",a="At the valley’s southwestern end, an entrance leads to Maraudon, the holy ancestral cavern and burial ground of the centaur race.",al={"how to get to maraudon","maraudon entrance","what is at the end of valley of spears"}},{q="How do you enter the valley?",a="You can enter on foot through narrow mountain defiles to the east and south. Sheer ridges surround the valley.",al={"valley of spears entrance","how to get in","passes into valley of spears"}},{q="Is anyone trapped in the valley?",a="Yes. The Maraudine have taken the goblin Melizza Brimbuzzle prisoner and hold her in their camps.",al={"melizza brimbuzzle","captive in valley of spears","gnome prisoner"}}},ang={["race:Tauren"]="As a tauren, you face the ancient enmity between centaur and tauren tribes, which has plagued Kalimdor for generations.",["faction:Alliance"]="The Alliance watches the region cautiously. The Maraudine have captured exploratory travelers, including the gnome Melizza Brimbuzzle."},kw={"centaur","desolace","maraudine","maraudon","melizza brimbuzzle","valley of spears"},rel={"zone:desolace","topic:centaur"},src={"Valley of Spears"}}
E["zone:desolace"] = {t="zone",n="Desolace",z="desolace",s="Across Desolace, centaur tribes fight for the plains as Horde, Alliance, and demonic cults press into the wastes. Gray earth, storm-dark skies, ancient ruins, and fallen beasts mark Kalimdor’s western coast.",h="Across Desolace, centaur tribes fight for the plains as Horde, Alliance, and demonic cults press into the...",sec={{t="A Land Cursed and Broken",b="Storm-dark skies hang over Desolace, where gray earth lies broken and pools have turned yellow. Legend says Princess Theradras, an earth elemental, drained the land’s life to restore her form. Zaetar, son of Cenarius, came to subdue her, but became her mate instead. Their union brought the first centaur. Ashamed and enraged, the newborn centaur killed their father and spread across the plains, leaving the scarred waste travelers see today.",sp=0},{t="Warring Hooves",b="Thousands of hooves thunder across Desolace as four centaur tribes fight outsiders and one another. The Kolkar roam the eastern cliffs, while the Magram keep crude yurts around brackish sinkholes. Farther south, the Gelkis live beyond rope bridges in deep ravines. The fanatical Maraudine guard the approach to Maraudon. Travelers crossing the wastes are often drawn into this old blood feud. Safe passage may mean fighting one tribe to win a wary parley with another.",sp=0},{t="Cults and Shadowed Coasts",b="Beyond centaur lands, dangers gather along Desolace’s borders. The Burning Blade operates from Thunder Axe Fortress and Shadowbreak Ravine, summoning demons and satyrs whose fel fire threatens the region.\n\nNaga creep onto the storm-lashed beaches of Ethel Rethor, while Darkspear trolls spear fish from the stilts of Shadowprey Village. High in the northern crags, the Alliance keeps watch from Nijel's Point. They fear Horde expansion and the demonic taint spreading from Mannoroc Coven.",sp=0}},faq={{q="Why is Desolace such a dead wasteland?",a="Legend says Desolace was once fertile, until Princess Theradras drained its vitality to rebuild her form. Then the centaur were born and spread violently, destroying what plant life remained and leaving gray dust and ash.",al={"why is desolace dead","desolace lore origin"}},{q="Where did the centaur come from?",a="The centaur were born from Zaetar, son of Cenarius, and Princess Theradras, an earth elemental. Repulsed and enraged by their appearance, the first khans killed their father soon after birth and spread across the plains.",al={"centaur origin","who made the centaur","zaetar theradras"}},{q="Can I ally with the centaur tribes here?",a="Yes. You can earn standing with either the Gelkis or the Magram by slaying members of the rival tribe. Enough standing grants entry to that tribe’s village and peace within its territory, while the opposing tribe becomes permanently hostile.",al={"centaur reputation","gelkis or magram","how to befriend centaur"}},{q="What is Maraudon?",a="Maraudon is the centaur’s sacred ancestral burial ground, hidden in Desolace’s twisting western cliffs. It holds Zaetar’s tomb and Princess Theradras’s underground lair, where she channels elemental corruption through its caverns.",al={"where is maraudon","maraudon dungeon","what lies under desolace"}},{q="Who is the wanderer roaming Desolace with a bear?",a="The wanderer is Rexxar, Champion of the Horde, traveling with his loyal bear Misha. The half-ogre patrols the dusty roads of Desolace and the Stonetalon Mountains, watching the wilderness and aiding those on important Horde business.",al={"rexxar desolace","beastmaster in desolace","who is the orc with a bear"}},{q="Why are the Alliance and Horde fighting the Burning Blade here?",a="The Burning Blade has seized strongholds such as Thunder Axe Fortress to summon demons and bind felsteeds. Its demons and satyrs threaten to infest the region, so both the Horde and Alliance must confront them.",al={"burning blade desolace","thunder axe fortress cultists","why are demons here"}}},ang={["race:Tauren"]="For tauren, Desolace is sacred and tragic ground: the centaur’s cradle, where their scourge drove your people close to extinction.",["class:Warlock"]="Desolace’s dry plains and demonic sites such as Mannoroc Coven draw warlocks seeking secrets of felsteeds. These wild horses were twisted into fire-breathing horrors by forbidden Shadow Council rites.",["class:Druid"]="Cenarion Circle druids see Desolace as a terrible wound in nature, where Zaetar met his end and elemental decay chokes the earth.",["faction:Alliance"]="From Nijel's Point, the Alliance watches the dangerous centaur tribes, Horde settlements such as Shadowprey Village, and demonic cults spreading through Desolace.",["faction:Horde"]="The Horde works to secure the coast at Shadowprey Village and protect the kodo herds at Ghost Walker Post. It also fights to crush the Burning Blade and prove the modern Horde has escaped demonic influence."},kw={"burning blade","centaur","desolace","gelkis","magram","maraudon","nijel's point","shadowprey village","theradras","zaetar"},rel={"subzone:nijel-s-point","subzone:shadowprey-village","subzone:kodo-graveyard","subzone:gelkis-village","subzone:magram-village","subzone:thunder-axe-fortress","subzone:mannoroc-coven","zone:stonetalon"},src={"Desolace (Classic)","Desolace"}}
